  opacity: 0;
  background:
    radial-gradient(circle at 50% 42%,rgba(92,39,57,.1) 0%,rgba(10,16,28,.98) 36%,#050912 78%);
  transform: scale(1.01);
  transition: opacity 180ms ease, visibility 0s linear 180ms, transform 180ms ease;
  pointer-events: none;
  isolation: isolate;
}

.nova-page-loading.is-visible {
  visibility: visible;
  opacity: 1;
  transform: scale(1);
  transition: opacity 160ms ease, transform 160ms ease;
  pointer-events: auto;
}

.nova-page-loading.is-leaving {
  visibility: hidden;
  opacity: 0;
  transform: scale(.995);
  transition: opacity 180ms ease, visibility 0s linear 180ms, transform 180ms ease;
  pointer-events: none;
}

.nova-page-loading__inner {
  position: relative;
  z-index: 1;
  display: flex;
  max-width: calc(100vw - 40px);
  align-items: center;
  flex-direction: column;
  text-align: center;
  opacity: 1;
  transform: scale(1);
  transition: opacity 180ms ease, transform 180ms ease;
}

.nova-page-loading.is-leaving .nova-page-loading__inner {
  opacity: 0;
  transform: translateY(-2px) scale(.985);
}

.nova-page-loading__mark {
  position: relative;
  display: block;
  width: 44px;
  height: 44px;
  flex: none;
}

.nova-page-loading__mark::before,
.nova-page-loading__mark::after {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  content: "";
}

.nova-page-loading__mark::before {
  border: 1px solid rgba(137,67,91,.44);
  box-shadow: 0 0 16px rgba(105,46,67,.08);
  animation: nova-loading-breathe 2.2s ease-in-out infinite;
}

.nova-page-loading__mark::after {
  border: 1.5px solid transparent;
  border-top-color: rgba(169,82,111,.72);
  border-right-color: rgba(169,82,111,.12);
  animation: nova-loading-turn 2.2s linear infinite;
}

.nova-page-loading__inner strong {
  margin-top: 16px;
  color: rgba(224,218,223,.84);
  font: 500 1rem/1.2 "Cormorant Garamond",Georgia,serif;
  letter-spacing: .26em;
}

.nova-page-loading__inner small {
  margin-top: 7px;
  color: rgba(143,137,146,.58);
  font-size: .66rem;
  letter-spacing: .22em;
}

@keyframes nova-loading-breathe {
  0%,100% { opacity:.42; transform:scale(.96); }
  50% { opacity:.9; transform:scale(1.03); }
}

@keyframes nova-loading-turn {
  to { transform:rotate(360deg); }
}

@media (max-width: 480px) {
  .nova-page-loading__mark {
    width: 38px;
    height: 38px;
  }

  .nova-page-loading__inner strong {
    margin-top: 14px;
    font-size: .94rem;
  }

  .nova-page-loading__inner small {
    font-size: .58rem;
    letter-spacing: .18em;
  }
}

@media (prefers-reduced-motion: reduce) {
  .nova-page-loading {
    transition: opacity 180ms ease, visibility 0s linear 180ms;
  }

  .nova-page-loading.is-visible {
    transition: opacity 120ms ease;
  }

  .nova-page-loading__inner {
    transition-duration: 120ms;
  }

  .nova-page-loading__mark::before,
  .nova-page-loading__mark::after {
    animation: none;
  }

  .nova-page-loading__mark::after {
    transform: rotate(38deg);
  }

  #local-search .search-dialog { animation-duration:100ms !important; }
}

/* Native-feeling midnight search dialog. */
#search-mask {
  z-index: 10000;
  background:rgba(5,9,18,.68) !important;
  -webkit-backdrop-filter:blur(7px) saturate(82%);
  backdrop-filter:blur(7px) saturate(82%);
}

#local-search .search-dialog {
  top:50%;
  left:50%;
  z-index:10001;
  width:min(720px,calc(100% - 40px));
  max-height:min(720px,calc(100svh - 64px));
  margin:0;
  padding:28px 30px 24px;
  overflow:hidden;
  border:1px solid rgba(224,210,220,.12);
  border-radius:20px;
  color:#d9d4da;
  background:
    radial-gradient(circle at 82% 2%,rgba(151,93,126,.1),transparent 34%),
    linear-gradient(145deg,rgba(17,24,39,.96),rgba(10,16,29,.94));
  box-shadow:0 28px 80px rgba(0,0,0,.34),inset 0 1px rgba(255,255,255,.04);
  -webkit-backdrop-filter:blur(24px) saturate(110%);
  backdrop-filter:blur(24px) saturate(110%);
  transform:translate(-50%,-50%);
}

#local-search .search-nav {
  margin-bottom:20px;
  color:#eee8eb;
}

#local-search .search-dialog-title {
  font-family:"Noto Serif SC","Songti SC",serif;
  font-size:1.35rem;
  font-weight:500;
  letter-spacing:.12em;
}

#local-search .search-dialog-title::before {
  display:block;
  margin-bottom:7px;
  content:"SEARCH THE ARCHIVE";
  color:#bd7189;
  font-family:Inter,sans-serif;
  font-size:.56rem;
  font-weight:600;
  letter-spacing:.23em;
}

#local-search .search-close-button {
  display:grid;
  width:34px;
  height:34px;
  flex:none;
  place-items:center;
  border:1px solid rgba(222,210,221,.1);
  border-radius:50%;
  color:#9f98a4;
  background:rgba(255,255,255,.025);
  font-size:.78rem;
  transition:color 190ms ease,border-color 190ms ease,background-color 190ms ease,transform 190ms ease;
}

#local-search .search-close-button:hover {
  border-color:rgba(190,112,138,.32);
  color:#e2bac7;
  background:rgba(190,112,138,.08);
  transform:rotate(6deg);
}

#local-search .local-search-input {
  position:relative;
}

#local-search .local-search-input::before {
  position:absolute;
  z-index:2;
  top:50%;
  left:19px;
  content:"\f002";
  color:#a76c82;
  font-family:"Font Awesome 6 Free","Font Awesome 5 Free";
  font-size:.8rem;
  font-weight:900;
  transform:translateY(-50%);
  pointer-events:none;
}

#local-search .local-search-input input {
  height:52px;
  padding:0 18px 0 46px;
  border:1px solid rgba(218,203,216,.12) !important;
  border-radius:12px !important;
  outline:0;
  color:#e5dfe4 !important;
  background:rgba(6,12,24,.56) !important;
  box-shadow:inset 0 1px 5px rgba(0,0,0,.16);
  font-size:.94rem;
  transition:border-color 190ms ease,box-shadow 190ms ease,background-color 190ms ease;
}

#local-search .local-search-input input::placeholder {
  color:#77717e !important;
  letter-spacing:.03em;
}

#local-search .local-search-input input:focus {
  border-color:rgba(190,112,138,.64) !important;
  background:rgba(9,16,29,.72) !important;
  box-shadow:0 0 0 3px rgba(190,112,138,.1),inset 0 1px 4px rgba(0,0,0,.14);
}

#local-search .search-dialog > hr,
#local-search-stats > hr {
  height:1px;
  margin:18px 0;
  border:0;
  background:linear-gradient(90deg,transparent,rgba(218,201,214,.12) 12%,rgba(218,201,214,.12) 88%,transparent);
}

.nova-search-state {
  padding:28px 6px 18px;
  text-align:center;
}

.nova-search-state[hidden] {
  display:none;
}

.nova-search-state__eyebrow {
  display:block;
  margin-bottom:8px;
  color:#b96e86;
  font-size:.58rem;
  font-weight:600;
  letter-spacing:.22em;
}

.nova-search-state strong {
  color:#dcd6db;
  font:500 1rem/1.5 "Noto Serif SC","Songti SC",serif;
  letter-spacing:.05em;
}

.nova-search-state p {
  margin:7px 0 18px;
  color:#89828e;
  font-size:.76rem;
}

.nova-search-state nav {
  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:8px;
}

.nova-search-state nav a {
  padding:7px 13px;
  border:1px solid rgba(218,202,214,.1);
  border-radius:999px;
  color:#aaa3ad;
  background:rgba(255,255,255,.025);
  font-size:.7rem;
  transition:color 190ms ease,border-color 190ms ease,background-color 190ms ease;
}

.nova-search-state nav a:hover {
  border-color:rgba(190,112,138,.28);
  color:#dfb4c1;
  background:rgba(190,112,138,.07);
}

#local-search .search-result-list {
  max-height:min(48vh,430px);
  margin:0 -10px;
  padding:2px 10px 8px;
  scrollbar-color:rgba(190,112,138,.25) transparent;
  scrollbar-width:thin;
}

#local-search .local-search-hit-item {
  margin:5px 0;
  padding:0;
  border:1px solid transparent;
  border-radius:11px;
}

#local-search .local-search-hit-item[value]::before {
  min-width:30px;
  margin:15px 0 0 13px;
  color:#9a6077;
  font:italic 600 .7rem Georgia,serif;
}

#local-search .local-search-hit-item a {
  padding:12px 14px;
  border-radius:11px;
  color:#aaa4ae;
  transition:background-color 190ms ease,color 190ms ease;
}

#local-search .local-search-hit-item:hover {
  border-color:rgba(211,190,205,.08);
  background:rgba(255,255,255,.03);
  transform:translateY(-1px);
}

#local-search .search-result-title {
  display:block;
  margin-bottom:4px;
  color:#e0dae0;
  font-size:.92rem;
  font-weight:600;
}

#local-search .search-result {
  color:#918a96;
  font-size:.76rem;
  line-height:1.7;
}

#local-search .search-keyword {
  color:#d58ba3;
}

#local-search .search-result-stats {
  margin-top:12px;
  color:#7f7885;
  font-size:.7rem;
}

#local-search #loading-database,
#local-search .search-loading {
  padding:28px 0;
  color:#918995;
  font-size:.75rem;
  letter-spacing:.06em;
}

#local-search #loading-database i {
  color:#bd7189;
}

@keyframes titleScale {
  from { opacity:0; transform:translate(-50%,calc(-50% + 12px)) scale(.985); }
  to { opacity:1; transform:translate(-50%,-50%) scale(1); }
}

@keyframes search_close {
  from { opacity:1; transform:translate(-50%,-50%) scale(1); }
  to { opacity:0; transform:translate(-50%,calc(-50% + 8px)) scale(.988); }
}

@media(max-width:768px) {
  #local-search .search-dialog {
    top:50%;
    left:50%;
    width:calc(100% - 24px);
    height:min(760px,calc(100svh - 24px));
    padding:24px 18px 18px;
    border-radius:18px;
  }
}

html[data-theme="light"] #search-mask {
  background:rgba(47,42,52,.32) !important;
}

html[data-theme="light"] #local-search .search-dialog {
  color:#4d4651;
  border-color:rgba(80,65,84,.14);
  background:
    radial-gradient(circle at 82% 2%,rgba(166,102,132,.09),transparent 34%),
    linear-gradient(145deg,rgba(244,241,245,.97),rgba(230,226,234,.95));
  box-shadow:0 28px 70px rgba(54,43,61,.2),inset 0 1px rgba(255,255,255,.55);
}

html[data-theme="light"] #local-search .search-dialog-title,
html[data-theme="light"] .nova-search-state strong,
html[data-theme="light"] #local-search .search-result-title {
  color:#403a45;
}

html[data-theme="light"] #local-search .local-search-input input {
  color:#49424d !important;
  border-color:rgba(82,67,86,.14) !important;
  background:rgba(222,217,226,.68) !important;
}

html[data-theme="light"] #local-search .local-search-hit-item:hover {
  background:rgba(130,103,125,.055);
}

/* ========================================================================== 
   Article detail — Night Rose reading system
   Scope deliberately starts at #body-wrap.post so archive, category, music
   and other custom routes keep their own visual systems.
   ========================================================================== */
#body-wrap.post {
  --page-bg: var(--post-page-bg);
  --page-bg-secondary: var(--post-page-bg-secondary);
  --surface-primary: var(--post-surface);
  --surface-secondary: var(--post-surface-secondary);
  --surface-raised: var(--post-surface-raised);
  --surface-soft: var(--post-surface-soft);
  --text-primary: var(--post-text);
  --text-secondary: var(--post-text-secondary);
  --text-muted: var(--post-text-muted);
  --border-default: var(--post-border);
  --border-strong: var(--post-border-strong);
  --accent-primary: var(--post-accent);
  --accent-hover: var(--post-accent-hover);
  --accent-soft: var(--post-accent-soft);
  --code-bg: var(--post-code-bg);
  --code-header-bg: var(--post-code-header-bg);
  --code-gutter-bg: var(--post-code-gutter-bg);
  --code-text: var(--post-code-text);
  --inline-code-bg: var(--post-inline-code-bg);
  --shadow-card: var(--post-shadow);
  --shadow-soft: var(--post-shadow-soft);
  position: relative;
  min-height: 100vh;
  overflow-x: clip;
  color: var(--text-primary);
  background: var(--page-bg);
}

/* Preserve Butterfly's native flex layout and only normalize its geometry. */
#body-wrap.post #content-inner.layout {
  display: flex;
  gap: 30px;
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 32px 24px 72px;
  align-items: start;
}

#body-wrap.post #content-inner > #post {
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
  padding: 40px 44px;
  border: 1px solid var(--border-default);
  border-radius: 20px;
  background: var(--surface-primary);
  box-shadow: var(--shadow-card);
}

#body-wrap.post #aside-content {
  flex: 0 0 280px;
  width: 280px;
  min-width: 0;
  padding: 0;
}

#body-wrap.post #aside-content .card-widget {
  margin-top: 0;
  margin-bottom: 18px;
  padding: 22px;
  border: 1px solid var(--border-default);
  border-radius: 16px;
  background: var(--surface-secondary);
  box-shadow: var(--shadow-soft);
}

#body-wrap.post #aside-content .item-headline {
  margin-bottom: 16px;
  color: var(--text-primary);
  font-weight: 550;
  letter-spacing: .02em;
}

#body-wrap.post #aside-content .item-headline i { color: var(--accent-primary); }
#body-wrap.post #aside-content .card-info .avatar-img { width: 68px; height: 68px; }
#body-wrap.post #aside-content .card-info .avatar-img img {
  border: 1px solid var(--border-strong);
}

#body-wrap.post #aside-content .card-info-social-icons .social-icon i {
  color: var(--text-muted);
  transition: color .22s ease, transform .22s ease;
}

#body-wrap.post #aside-content .card-info-social-icons .social-icon:hover i {
  color: var(--text-primary);
  transform: translateY(-2px);
}

#body-wrap.post #aside-content #card-info-btn {
  border-radius: 10px;
  color: rgba(255, 255, 255, .9);
  background: var(--accent-primary);
}

#body-wrap.post #aside-content #card-info-btn:hover {
  background: var(--accent-hover);
  transform: translateY(-1px);
}

#body-wrap.post #aside-content .sticky_layout { position: static; }
#body-wrap.post #card-toc { position: static; }

@media (min-width: 961px) {
  body:not(.read-mode) #body-wrap.post #aside-content {
    display: flex !important;
    align-self: stretch;
    flex-direction: column;
  }

  #body-wrap.post #aside-content .sticky_layout {
    position: relative;
    flex: 1 0 auto;
    min-height: 0;
  }

  #body-wrap.post #card-toc {
    position: sticky;
    top: 82px;
    z-index: 2;
  }
}

/* 文章页普通模式始终保留侧栏；只有阅读模式可以隐藏。 */
body.read-mode #body-wrap.post #aside-content { display: none !important; }
body:has(#body-wrap.post) #rightside #hide-aside-btn { display: none !important; }

#body-wrap.post #card-toc .toc-content {
  max-height: calc(100vh - 110px);
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
}

#body-wrap.post #card-toc .toc-link {
  border-left: 2px solid transparent;
  color: var(--text-secondary);
  transition: color .22s ease, border-color .22s ease, background-color .22s ease;
}

#body-wrap.post #card-toc .toc-link.active {
  border-left-color: var(--accent-primary);
  color: var(--text-primary);
  background: var(--accent-soft);
}
#body-wrap.post #card-toc .toc-link:hover {
  color: var(--text-primary);
  background: var(--surface-soft);
}

/* Typography. */
#body-wrap.post #article-container {
  min-width: 0;
  color: var(--text-primary);
  font-size: 16.5px;
  line-height: 1.85;
  overflow-wrap: anywhere;
}

#body-wrap.post #article-container p { margin: 0 0 1.25em; }
#body-wrap.post #article-container h1,
#body-wrap.post #article-container h2,
#body-wrap.post #article-container h3,
#body-wrap.post #article-container h4 {
  color: var(--text-primary);
  font-weight: 560;
  line-height: 1.38;
}

#body-wrap.post #article-container h1 { font-size: 1.875rem; }
#body-wrap.post #article-container h2 {
  margin-top: 2.2em;
  padding-left: 14px;
  border-left: 3px solid var(--accent-primary);
  font-size: 1.55rem;
}
#body-wrap.post #article-container h3 { font-size: 1.25rem; }
#body-wrap.post #article-container a { color: var(--accent-primary); }
#body-wrap.post #article-container a:hover { color: var(--accent-hover); }
#body-wrap.post #article-container hr { border-color: var(--border-default); }
#body-wrap.post #article-container img { max-width: 100%; height: auto; border-radius: 12px; }

#body-wrap.post #article-container :not(pre) > code {
  padding: .16em .42em;
  border: 1px solid var(--border-default);
  border-radius: 5px;
  color: var(--accent-hover);
  background: var(--inline-code-bg);
}

#body-wrap.post #article-container .highlight,
#body-wrap.post #article-container pre {
  max-width: 100%;
  border: 1px solid var(--border-default);
  border-radius: 12px;
  background: var(--code-bg);
  box-shadow: var(--shadow-soft);
}

#body-wrap.post #article-container .highlight {
  overflow-x: auto;
  background: var(--code-bg);
}
#body-wrap.post #article-container .highlight .highlight-tools {
  color: var(--text-secondary);
  background: var(--code-header-bg);
}
#body-wrap.post #article-container .highlight table,
#body-wrap.post #article-container .highlight td,
#body-wrap.post #article-container .highlight .code,
#body-wrap.post #article-container .highlight .code pre {
  color: var(--code-text);
  background: var(--code-bg);
}
#body-wrap.post #article-container .highlight table {
  display: table;
  width: 100%;
  table-layout: auto;
}
#body-wrap.post #article-container .highlight .gutter {
  width: 1%;
  white-space: nowrap;
}
#body-wrap.post #article-container .highlight .code { width: auto; }
#body-wrap.post #article-container .highlight pre {
  margin: 0;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}
#body-wrap.post #article-container .highlight .gutter,
#body-wrap.post #article-container .highlight .gutter pre {
  color: #707a89;
  background: var(--code-gutter-bg);
}
#body-wrap.post #article-container .highlight .copy-button,
#body-wrap.post #article-container .highlight .expand {
  color: var(--text-secondary);
}
#body-wrap.post #article-container .highlight .keyword,
#body-wrap.post #article-container .highlight .selector-tag { color: #b78499; }
#body-wrap.post #article-container .highlight .string,
#body-wrap.post #article-container .highlight .attribute { color: #9eaf91; }
#body-wrap.post #article-container .highlight .number,
#body-wrap.post #article-container .highlight .literal { color: #b99aa8; }
#body-wrap.post #article-container .highlight .title,
#body-wrap.post #article-container .highlight .function { color: #8eabc2; }
#body-wrap.post #article-container .highlight .type,
#body-wrap.post #article-container .highlight .built_in { color: #c19b7e; }
#body-wrap.post #article-container .highlight .comment { color: #8993a1; }
#body-wrap.post #article-container .highlight .operator,
#body-wrap.post #article-container .highlight .punctuation { color: #aaa5af; }
#body-wrap.post #article-container pre {
  overflow-x: auto;
  font-size: 13.5px;
  line-height: 1.7;
}

#body-wrap.post #article-container pre code {
  padding: 0 !important;
  background: transparent !important;
}

#body-wrap.post #article-container blockquote,
#body-wrap.post #article-container .note {
  --nova-note-tone: var(--accent-primary);
  position: relative;
  margin: 1.5em 0;
  padding: 16px 18px;
  border: 1px solid var(--border-default);
  border-left: 3px solid var(--nova-note-tone);
  border-radius: 11px;
  color: var(--text-secondary);
  background: var(--surface-soft);
  box-shadow: none;
}

#body-wrap.post #article-container .note.warning { --nova-note-tone: var(--nova-note-warning); }
#body-wrap.post #article-container .note.danger { --nova-note-tone: var(--nova-note-danger); }
#body-wrap.post #article-container .note.success,
#body-wrap.post #article-container .note.done { --nova-note-tone: var(--nova-note-success); }

#body-wrap.post #article-container .note h2,
#body-wrap.post #article-container .note h3,
#body-wrap.post #article-container .note h4,
#body-wrap.post #article-container .note h5,
#body-wrap.post #article-container .note h6 {
  margin-top: 3px;
  margin-bottom: 0;
  padding-top: 0;
  border-bottom: 0;
  color: var(--text-primary);
}

#body-wrap.post #article-container .note > :first-child { margin-top: 0; }
#body-wrap.post #article-container .note > :last-child { margin-bottom: 0; }
#body-wrap.post #article-container .note .img-alt { margin: 5px 0 10px; }

#body-wrap.post #article-container .note.icon-padding { padding-left: 3em; }
#body-wrap.post #article-container .note > .note-icon,
#body-wrap.post #article-container .note:not(.no-icon)::before {
  position: absolute;
  top: calc(50% - .95em);
  left: .8em;
  display: inline-block;
  color: var(--text-secondary);
  font: 600 1.15em/1 "Font Awesome 7 Free", "Font Awesome 6 Free";
  text-rendering: auto;
  -webkit-font-smoothing: antialiased;
}

#body-wrap.post #article-container .note > .note-icon {
  top: calc(50% - .5em);
}

#body-wrap.post #article-container .note.primary:not(.no-icon)::before { content: "\f055"; }
#body-wrap.post #article-container .note.info:not(.no-icon)::before { content: "\f05a"; }
#body-wrap.post #article-container .note.success:not(.no-icon)::before,
#body-wrap.post #article-container .note.done:not(.no-icon)::before { content: "\f058"; }
#body-wrap.post #article-container .note.warning:not(.no-icon)::before { content: "\f06a"; }
#body-wrap.post #article-container .note.danger:not(.no-icon)::before { content: "\f056"; }

#body-wrap.post #article-container .note p:last-child,
#body-wrap.post #article-container blockquote p:last-child { margin-bottom: 0; }

#body-wrap.post #article-container .table-wrap table {
  display: table;
  width: 100%;
  color: var(--text-secondary);
}
#body-wrap.post #article-container .table-wrap {
  max-width: 100%;
  overflow-x: auto;
}
#body-wrap.post #article-container .table-wrap th {
  color: var(--text-primary);
  background: var(--surface-secondary);
}
#body-wrap.post #article-container .table-wrap th,
#body-wrap.post #article-container .table-wrap td { border-color: var(--border-default); }

/* Post utilities, navigation, recommendations and comments. */
#body-wrap.post .post-copyright {
  border: 1px solid var(--border-default);
  border-radius: 14px;
  background: var(--surface-soft);
}

#body-wrap.post .post-meta__tags {
  color: var(--accent-primary);
  border-color: var(--border-strong);
}

#body-wrap.post #pagination.pagination-post {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-top: 38px;
  overflow: visible;
}

#body-wrap.post #pagination .pagination-related {
  min-height: 152px;
  overflow: hidden;
  border: 1px solid var(--border-default);
  border-radius: 16px;
  background: var(--surface-raised);
  transition: transform .24s ease, border-color .24s ease, box-shadow .24s ease;
}

#body-wrap.post #pagination .pagination-related:hover {
  border-color: var(--border-strong);
  box-shadow: var(--shadow-soft);
  transform: translateY(-2px);
}

#body-wrap.post #pagination .cover { opacity: .42; transform: none !important; }
#body-wrap.post #pagination .pagination-related:hover .cover { opacity: .5; transform: none !important; }

#body-wrap.post .relatedPosts { margin-top: 42px; }
#body-wrap.post .relatedPosts > .headline { color: var(--text-primary); font-size: 1.25rem; }
#body-wrap.post .relatedPosts-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

#body-wrap.post .relatedPosts-list .pagination-related {
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  border: 1px solid var(--border-default);
  border-radius: 12px;
  background: var(--surface-secondary);
  transition: transform .24s ease, border-color .24s ease;
}

#body-wrap.post .relatedPosts-list .pagination-related:hover {
  border-color: var(--border-strong);
  transform: translateY(-2px);
}

#body-wrap.post .relatedPosts-list .cover { opacity: .38; transform: none !important; }
#body-wrap.post .relatedPosts-list .info-item-2 {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

#body-wrap.post #post-comment {
  margin-top: 42px;
  padding-top: 32px;
  border-top: 1px solid var(--border-default);
}

#body-wrap.post #post-comment .comment-headline { color: var(--text-primary); }
#body-wrap.post #post-comment .wl-panel {
  border: 1px solid var(--border-default);
  border-radius: 10px;
  background: var(--surface-secondary);
}

#body-wrap.post #post-comment :is(input, textarea) {
  color: var(--text-primary);
  background: var(--surface-secondary);
}
#body-wrap.post #post-comment :is(input, textarea)::placeholder { color: var(--text-muted); }
#body-wrap.post #post-comment .wl-panel:focus-within {
  border-color: var(--accent-primary);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
#body-wrap.post #post-comment .wl-btn.primary {
  border-color: var(--accent-primary);
  color: rgba(255, 255, 255, .92);
  background: var(--accent-primary);
  transition: background-color .22s ease, transform .22s ease;
}
#body-wrap.post #post-comment .wl-btn.primary:hover { background: var(--accent-hover); }
#body-wrap.post #post-comment img { max-width: 100%; height: auto; border-radius: 12px; }

/* Clean light theme; code remains dark for syntax clarity. */
html[data-theme="light"] #body-wrap.post {
  background: var(--page-bg);
}
html[data-theme="light"] #body-wrap.post #article-container :not(pre) > code {
  color: var(--accent-hover);
  background: var(--inline-code-bg);
}
html[data-theme="light"] #body-wrap.post #article-container .highlight,
html[data-theme="light"] #body-wrap.post #article-container pre {
  color: var(--post-code-text);
  background: var(--post-code-bg);
}
html[data-theme="light"] #body-wrap.post #article-container .highlight .gutter,
html[data-theme="light"] #body-wrap.post #article-container .highlight .gutter pre {
  color: #96919b;
}
html[data-theme="light"] #body-wrap.post #article-container .highlight .keyword,
html[data-theme="light"] #body-wrap.post #article-container .highlight .selector-tag { color: #95647a; }
html[data-theme="light"] #body-wrap.post #article-container .highlight .string,
html[data-theme="light"] #body-wrap.post #article-container .highlight .attribute { color: #65785f; }
html[data-theme="light"] #body-wrap.post #article-container .highlight .number,
html[data-theme="light"] #body-wrap.post #article-container .highlight .literal { color: #966f80; }
html[data-theme="light"] #body-wrap.post #article-container .highlight .title,
html[data-theme="light"] #body-wrap.post #article-container .highlight .function { color: #526f8b; }
html[data-theme="light"] #body-wrap.post #article-container .highlight .type,
html[data-theme="light"] #body-wrap.post #article-container .highlight .built_in { color: #8a654e; }
html[data-theme="light"] #body-wrap.post #article-container .highlight .comment { color: #92949c; }
html[data-theme="light"] #body-wrap.post #article-container .highlight .operator,
html[data-theme="light"] #body-wrap.post #article-container .highlight .punctuation { color: #68636d; }
html[data-theme="light"] #body-wrap.post #pagination .pagination-related {
  background: #35343a;
}

#body-wrap.post #rightside > div > button,
#body-wrap.post #rightside > div > a {
  border: 1px solid var(--border-default);
  color: var(--text-secondary);
  background: var(--surface-secondary);
  opacity: .62;
}
#body-wrap.post #rightside > div > button:hover,
#body-wrap.post #rightside > div > a:hover {
  color: var(--text-primary);
  opacity: 1;
  transform: translateY(-1px);
}

@media (max-width: 960px) {
  #body-wrap.post #content-inner.layout {
    flex-direction: column;
    width: 100%;
    max-width: 900px;
    gap: 24px;
    margin: 0 auto;
    padding: 24px 18px 64px;
  }
  #body-wrap.post #aside-content { flex-basis: auto; width: 100%; }
  #body-wrap.post #card-toc { position: static; max-height: none; }
  #body-wrap.post .relatedPosts-list { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 640px) {
  #body-wrap.post #content-inner.layout { width: 100%; padding: 18px 12px 56px; }
  #body-wrap.post #content-inner > #post { padding: 20px; border-radius: 18px; }
  #body-wrap.post #article-container { font-size: 16px; }
  #body-wrap.post #article-container h1 { font-size: 1.65rem; }
  #body-wrap.post #article-container h2 { font-size: 1.4rem; }
  #body-wrap.post #pagination.pagination-post,
  #body-wrap.post .relatedPosts-list { grid-template-columns: 1fr; }
  #body-wrap.post #pagination .pagination-related { min-height: 136px; }
  #body-wrap.post .relatedPosts-list .pagination-related { aspect-ratio: 16 / 9; }
  #body-wrap.post #article-container .table-wrap table { min-width: 560px; }
  #body-wrap.post #rightside { bottom: 18px; }
}

@media (prefers-reduced-motion: reduce) {
  #body-wrap.post *,
  #body-wrap.post *::before,
  #body-wrap.post *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; }
}
/* Navigation */
/* Navigation search uses an inline SVG so it never depends on icon fonts. */
#search-button .search-nav-link {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  vertical-align: top;
  border: 0;
  color: inherit;
  background: none;
  font: inherit;
  cursor: pointer;
}

#search-button .search-nav-link > span {
  display: block;
  line-height: inherit;
}

@media (min-width: 769px) {
  #nav #menus {
    display: flex;
    height: 100%;
    align-items: center;
  }

  #nav #menus > #search-button,
  #nav #menus > .menus_items,
  #nav #menus > .menus_items > .menus_item {
    display: flex;
    height: 32px;
    align-items: center;
    overflow: visible;
  }

  #nav #search-button .search-nav-link,
  #nav #menus > .menus_items > .menus_item > .site-page {
    box-sizing: border-box;
    display: flex;
    height: 32px;
    padding-bottom: 6px;
    align-items: center;
    line-height: 1;
  }
}

#search-button .search-nav-icon {
  display: block;
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Navigation dropdown */
@media (min-width: 769px) {
  #nav .menus_items .menus_item_child {
    box-sizing: border-box;
    top: 100%;
    right: 0;
    z-index: 100;
    min-width: 108px;
    height: auto;
    max-height: none;
    margin-top: 8px;
    padding: 6px;
    overflow: visible;
    border-radius: 10px;
  }

  #nav .menus_item_child > li {
    display: block;
    margin: 0;
  }

  #nav .menus_item_child .site-page {
    box-sizing: border-box;
    display: flex;
    min-height: 38px;
    padding: 0 12px;
    align-items: center;
    gap: 8px;
    border-radius: 7px;
    line-height: 1;
    white-space: nowrap;
  }

  #nav .menus_item_child .site-page > i {
    width: 1em;
    margin: 0;
    text-align: center;
  }
}

/* Navigation dark theme */
@media (min-width: 769px) {
  html[data-theme="dark"] #nav .menus_item_child {
    border: 1px solid rgba(185, 128, 153, .24);
    background: linear-gradient(145deg, rgba(16, 22, 35, .97), rgba(25, 22, 33, .97));
    box-shadow: 0 14px 34px rgba(0, 0, 0, .36), 0 0 18px rgba(137, 79, 105, .05);
    -webkit-backdrop-filter: blur(10px);
    backdrop-filter: blur(10px);
  }

  html[data-theme="dark"] #nav .menus_item_child .site-page {
    color: rgba(225, 216, 223, .88);
  }

  html[data-theme="dark"] #nav .menus_item_child .site-page:hover {
    color: rgba(232, 151, 183, .98);
    background: rgba(194, 122, 151, .10);
  }
}

/* Navigation light theme */
@media (min-width: 769px) {
  html[data-theme="light"] #nav .menus_item_child {
    border: 1px solid rgba(207, 183, 195, .50);
    background: linear-gradient(145deg, rgba(255, 252, 253, .98), rgba(247, 241, 245, .97));
    box-shadow: 0 12px 28px rgba(104, 79, 94, .12), 0 2px 7px rgba(104, 79, 94, .05);
    -webkit-backdrop-filter: blur(9px);
    backdrop-filter: blur(9px);
  }

  html[data-theme="light"] #nav .menus_item_child .site-page {
    color: rgba(65, 59, 68, .92);
  }

  html[data-theme="light"] #nav .menus_item_child .site-page:hover {
    color: rgba(181, 91, 129, .98);
    background: rgba(205, 142, 168, .11);
  }
}

@media (min-width: 769px) {
  body.nova-template-route #nav .menus_item_child a[href="/templates/"],
  body.nova-shuoshuo-route #nav .menus_item_child a[href="/shuoshuo/"],
  body.nova-gallery-route #nav .menus_item_child a[href="/Gallery/"] {
    color: rgba(234, 155, 186, .98);
    background: rgba(194, 122, 151, .13);
  }

  html[data-theme="light"] body.nova-template-route #nav .menus_item_child a[href="/templates/"],
  html[data-theme="light"] body.nova-shuoshuo-route #nav .menus_item_child a[href="/shuoshuo/"],
  html[data-theme="light"] body.nova-gallery-route #nav .menus_item_child a[href="/Gallery/"] {
    color: rgba(174, 82, 121, .98);
    background: rgba(205, 142, 168, .15);
  }
}

/* Non-home Butterfly rightside controls; JS adds this class only inside #rightside. */
body:not(.nova-home-active) #home-theme-toggle {
  display:none!important;
}

/* Archive pages use a fixed timeline layout, so the aside-layout toggle is not applicable. */
body.nova-archive-route #rightside #hide-aside-btn {
  display:none!important;
}

body:not(.nova-home-active) #rightside .fliex-rightside-button {
  display:flex;
  align-items:center;
  justify-content:center;
  width:38px;
  height:38px;
  margin-bottom:8px;
  padding:0;
  border-radius:10px;
  line-height:1;
  transition:
    background-color .24s ease,
    border-color .24s ease,
    color .24s ease,
    box-shadow .24s ease,
    transform .24s ease;
}

body:not(.nova-home-active) #rightside .fliex-rightside-button:hover {
  transform:translateY(-2px);
}

body:not(.nova-home-active) #rightside .fliex-rightside-button:active {
  transform:translateY(0) scale(.94);
}

body:not(.nova-home-active) #rightside .fliex-rightside-button svg {
  display:block;
  width:17px;
  height:17px;
  flex:0 0 auto;
  fill:none;
  stroke:currentColor;
  stroke-width:1.8;
  stroke-linecap:round;
  stroke-linejoin:round;
}

body:not(.nova-home-active) #rightside .fliex-rightside-button i {
  display:flex;
  align-items:center;
  justify-content:center;
  width:18px;
  height:18px;
  font-size:16px;
  line-height:1;
  color:currentColor;
}

html[data-theme="light"] body:not(.nova-home-active) #rightside .fliex-rightside-button {
  color:rgba(85,78,88,.9);
  background:linear-gradient(145deg,rgba(255,252,253,.96),rgba(247,241,245,.94))!important;
  border:1px solid rgba(204,181,193,.52);
  box-shadow:0 6px 18px rgba(103,78,94,.1),0 2px 5px rgba(103,78,94,.05);
  -webkit-backdrop-filter:blur(8px);
  backdrop-filter:blur(8px);
}

html[data-theme="light"] body:not(.nova-home-active) #rightside .fliex-rightside-button:hover {
  color:rgba(181,91,129,.98);
  background:linear-gradient(145deg,rgba(251,242,247,.98),rgba(244,233,239,.98))!important;
  border-color:rgba(190,119,149,.48);
}

html[data-theme="dark"] body:not(.nova-home-active) #rightside .fliex-rightside-button {
  color:rgba(214,202,211,.88);
  background:linear-gradient(145deg,rgba(19,26,41,.95),rgba(24,22,34,.94))!important;
  border:1px solid rgba(184,128,151,.24);
  box-shadow:0 8px 21px rgba(0,0,0,.3),0 0 18px rgba(136,79,104,.05);
  -webkit-backdrop-filter:blur(8px);
  backdrop-filter:blur(8px);
}

html[data-theme="dark"] body:not(.nova-home-active) #rightside .fliex-rightside-button:hover {
  color:rgba(222,140,173,.98);
  background:linear-gradient(145deg,rgba(31,34,50,.98),rgba(35,27,41,.98))!important;
  border-color:rgba(193,123,151,.42);
}

/* Keep Butterfly's 404 layout and palette; add only a clear, history-independent exit. */
.error-info .nova-error-home {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-width:112px;
  min-height:42px;
  margin-top:22px;
  padding:8px 20px;
  border:1px solid rgba(184,106,131,.5);
  border-radius:999px;
  color:var(--font-color);
  background:rgba(164,119,137,.12);
  text-decoration:none;
  transition:background-color .2s ease,color .2s ease,border-color .2s ease;
}

.error-info .nova-error-home:hover {
  border-color:#b86a83;
  color:#fff;
  background:#b86a83;
}

/* ============================================================
   About page — built on the homepage coast shell
   left homepage rail + right-top controls + sea background
   ============================================================ */

body.nova-about-route{background:#0b1620;color:var(--coast-ink);overflow-x:clip}
body.nova-about-route #body-wrap{background:transparent}
body.nova-about-route #sidebar,
body.nova-about-route #rightside,
body.nova-about-route #web_bg{display:none!important}

.nova-about-shell{position:relative;isolation:isolate;min-height:100svh;overflow-x:clip;font:400 14px/1.5 var(--coast-font);color:var(--coast-ink)}
.nova-about-shell *{box-sizing:border-box}
.nova-about-shell a{color:inherit;text-decoration:none}

/* Sea / lighthouse background. The shade matches the homepage exactly so the
   left rail's frosted glass reads the same in light and dark mode. */
.nova-about-shell .coast-background{position:fixed;z-index:-3}
.nova-about-shell .coast-shade{position:fixed;z-index:-2;background:linear-gradient(180deg,rgba(20,37,51,.10),rgba(9,20,30,.06) 65%,rgba(9,20,30,.12))}
.nova-about-shell .coast-snow{position:fixed;z-index:-1}
.nova-about-shell .coast-lightning{position:fixed}

/* Left rail and toolbar match the homepage. */
.nova-about-shell .coast-toolbar{position:fixed;z-index:8}
.nova-about-shell .coast-brand-name{margin:0 0 12px;color:#c7cfd6;font:400 40px/1.4 Inter,"Microsoft YaHei",sans-serif}
.nova-about-shell .coast-brand-name a{color:inherit}
.nova-about-shell .coast-snow-toggle{min-width:78px;height:30px;font:400 12px/30px Consolas,"Courier New",monospace;letter-spacing:.02em;color:rgba(188,204,216,.65);white-space:nowrap}
.nova-about-shell .coast-snow-toggle[aria-checked=true]{color:rgba(205,221,233,.82)}

/* Content column: clear of the fixed left rail and the right sea. */
.nova-about-content{position:relative;z-index:2;max-width:764px;padding:clamp(72px,9vh,120px) clamp(24px,4vw,72px) 96px 0}
.nova-about-content::before{content:"";position:absolute;z-index:-1;inset:-60px -8vw -80px 0;pointer-events:none;background:radial-gradient(95% 72% at 36% 32%,rgba(8,18,27,.58),rgba(8,18,27,.32) 58%,transparent 82%);filter:blur(8px)}

/* Editorial typography */
.nova-about-head{max-width:640px}
.nova-about-eyebrow{margin:0;color:rgba(159,196,220,.72);font:600 11px/1.4 "JetBrains Mono",Consolas,monospace;letter-spacing:.22em}
.nova-about-head h1{margin:18px 0 0;color:#eef4f8;font-size:clamp(2.6rem,5.4vw,4.2rem);font-weight:520;line-height:1.02;letter-spacing:.02em}
.nova-about-lede{margin:20px 0 0;max-width:600px;color:rgba(199,211,221,.8);font-size:clamp(1rem,1.5vw,1.16rem);line-height:1.85}
.nova-about-story{max-width:620px;margin:36px 0 0}
.nova-about-story p{margin:0 0 1.05em;color:rgba(206,217,226,.82);font-size:15px;line-height:1.95}
.nova-about-story p:last-child{margin-bottom:0}

/* Two offset photos: the visual focus, slightly rotated, kept off-centre. */
.nova-about-gallery{position:relative;width:min(560px,92%);height:clamp(230px,30vw,330px);margin:46px 0 10px}
.nova-about-photo{position:absolute;margin:0;border:1px solid rgba(216,229,238,.16);border-radius:3px;overflow:hidden;background:rgba(9,19,28,.4)}
.nova-about-photo img{display:block;width:100%;height:100%;object-fit:cover;filter:saturate(.78) brightness(.9) contrast(1.02)}
.nova-about-photo--back{left:0;top:6%;width:60%;height:84%;transform:rotate(-2.6deg);box-shadow:0 18px 44px rgba(3,9,15,.4)}
.nova-about-photo--front{right:0;bottom:0;z-index:1;width:54%;height:80%;transform:rotate(2.2deg);box-shadow:0 22px 52px rgba(3,9,15,.48)}

/* Bottom: NOW / PROJECTS / CONTACT — hairlines and whitespace only. */
.nova-about-editorial{margin-top:70px;border-top:1px solid rgba(216,229,238,.14)}
.nova-about-block{padding:30px 0;border-bottom:1px solid rgba(216,229,238,.12)}
.nova-about-label{margin:0 0 18px;color:rgba(159,196,220,.68);font:600 10px/1 "JetBrains Mono",Consolas,monospace;letter-spacing:.22em}
.nova-about-block dl{margin:0;display:grid;gap:12px}
.nova-about-block dl div{display:grid;grid-template-columns:88px minmax(0,1fr);gap:18px;align-items:baseline}
.nova-about-block dt{color:rgba(150,170,185,.72);font-size:11px;letter-spacing:.04em}
.nova-about-block dd{margin:0;color:#e2eaf0;font-size:14px;line-height:1.6;overflow-wrap:anywhere}
.nova-about-links{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 40px}
.nova-about-links a{display:flex;align-items:baseline;justify-content:space-between;gap:16px;padding:12px 0;border-top:1px solid rgba(216,229,238,.1);color:#cfe0ea;font-size:14px;transition:color .2s ease,border-color .2s ease}
.nova-about-links a span{flex:0 0 auto;color:rgba(150,170,185,.6);font:10px/1.5 "JetBrains Mono",Consolas,monospace;letter-spacing:.06em;text-transform:uppercase}
.nova-about-links a:hover{color:#fff;border-top-color:rgba(216,229,238,.24)}
.nova-about-links a:focus-visible{outline:2px solid rgba(159,196,220,.7);outline-offset:3px;border-radius:2px}

/* Comments, kept light. */
.nova-about-comments{margin-top:76px;padding-top:38px;border-top:1px solid rgba(216,229,238,.14)}
.nova-about-comments > header{margin-bottom:22px}
.nova-about-comments > header h2{margin:9px 0 0;color:#eef4f8;font-size:1.5rem;font-weight:520;letter-spacing:.02em}
.nova-about-comments #post-comment{margin:0}
.nova-about-comments .comment-head{display:none}
.nova-about-comments .wl-panel{border:1px solid rgba(216,229,238,.14)!important;border-radius:6px!important;background:rgba(15,30,43,.5)!important;box-shadow:none!important}
.nova-about-comments .wl-header,.nova-about-comments .wl-footer{border-color:rgba(216,229,238,.12)!important}
.nova-about-comments .wl-editor,.nova-about-comments .wl-header input{color:#dce4ea!important}
.nova-about-comments .wl-btn.primary{border-color:rgba(159,196,220,.8)!important;background:rgba(159,196,220,.92)!important;color:#0b1620!important}

@keyframes nova-about-reveal{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
.nova-about-head{animation:nova-about-reveal .5s .02s cubic-bezier(.22,.61,.36,1) both}
.nova-about-gallery{animation:nova-about-reveal .5s .08s cubic-bezier(.22,.61,.36,1) both}
.nova-about-story{animation:nova-about-reveal .5s .14s cubic-bezier(.22,.61,.36,1) both}

/* Desktop rail is fixed; the column starts after it. */
@media(min-width:901px){
  .nova-about-shell .coast-sidebar{position:fixed;top:var(--coast-panel-y);bottom:var(--coast-panel-y);left:var(--coast-panel-x);width:var(--coast-panel-width)}
  .nova-about-content{margin-left:calc(var(--coast-panel-x) + max(var(--coast-panel-width),180px) + 54px)}
}

@media(max-width:1280px){
  .nova-about-content{max-width:min(700px,calc(100vw - 300px))}
}

@media(max-width:900px){
  .nova-about-shell .coast-sidebar{position:fixed;top:74px;right:16px;bottom:auto;left:16px;width:auto}
  .nova-about-shell .coast-brand-name{font-size:32px;margin-bottom:5px}
  .nova-about-content{max-width:none;margin:0;padding:232px 20px 178px}
  .nova-about-gallery{width:min(460px,100%)}
}

@media(max-width:640px){
  .nova-about-content{padding:224px 18px 168px}
  .nova-about-head h1{font-size:clamp(2.2rem,11vw,2.8rem)}
  .nova-about-lede{font-size:1rem}
  .nova-about-gallery{width:100%;height:230px;margin-top:34px}
  .nova-about-photo--back{width:64%;height:80%}
  .nova-about-photo--front{width:58%;height:76%}
  .nova-about-block dl div{grid-template-columns:74px minmax(0,1fr);gap:14px}
  .nova-about-links{grid-template-columns:1fr;gap:0}
  .nova-about-editorial{margin-top:54px}
}

@media(prefers-reduced-motion:reduce){
  .nova-about-head,.nova-about-gallery,.nova-about-story{animation:none}
}

/* Reference composition: quiet editorial layout with the image and three bottom columns. */
.nova-about-shell .coast-background{inset:0;width:100%;height:100%;object-fit:cover;object-position:center center;filter:saturate(.86) brightness(.86)}
.nova-about-shell .coast-shade{inset:0;background:linear-gradient(90deg,rgba(17,31,45,.26),rgba(20,37,52,.05) 56%,rgba(12,24,36,.18))}
.nova-about-content{width:calc(100% - (var(--coast-panel-x) + var(--coast-panel-width) + 120px));max-width:none;min-height:100svh;margin-left:calc(var(--coast-panel-x) + var(--coast-panel-width) + 54px);padding:19vh 10px 48px 0}
.nova-about-content::before{inset:0 -30vw 0 -8vw;background:radial-gradient(70% 70% at 34% 38%,rgba(8,18,27,.34),transparent 80%);filter:blur(14px)}
.nova-about-head{max-width:620px;position:relative}
.nova-about-eyebrow{display:flex;align-items:center;gap:14px;color:#e0e8ed;font:400 13px/1.4 Georgia,serif;letter-spacing:.08em}
.nova-about-eyebrow i{display:block;width:170px;height:1px;background:rgba(225,238,246,.38)}
.nova-about-head h1{margin:22px 0 0;font:400 clamp(4rem,6vw,5.3rem)/.95 Georgia,"Times New Roman",serif;color:#f2f5f6;letter-spacing:-.02em}
.nova-about-subtitle{margin:12px 0 0;color:rgba(230,238,242,.92);font:italic 400 clamp(1.6rem,2.3vw,2.2rem)/1.2 "Segoe Script","Bradley Hand",cursive;letter-spacing:.03em}
.nova-about-lede{display:none}
.nova-about-gallery{position:absolute;left:40%;top:19%;width:min(660px,48vw);height:440px;margin:0}
.nova-about-photo{border:5px solid rgba(247,249,248,.88);border-radius:0;background:#dbe1e3;box-shadow:0 18px 42px rgba(5,12,19,.32)}
.nova-about-photo img{filter:saturate(.9) brightness(.96);}
.nova-about-photo--back{left:0;top:0;width:70%;height:78%;transform:rotate(-5deg)}
.nova-about-photo--front{right:0;bottom:0;width:57%;height:66%;transform:rotate(6deg)}
.nova-about-story{position:relative;max-width:470px;margin:64px 0 0;color:rgba(225,232,236,.76)}
.nova-about-story p{font-family:Georgia,"Microsoft YaHei",serif;font-size:16px;line-height:1.95;letter-spacing:.03em}
.nova-about-editorial{position:absolute;left:0;right:0;bottom:28px;display:grid;grid-template-columns:1.05fr 1.15fr 1fr;margin:0;border-top:0}
.nova-about-block{min-height:182px;padding:0 34px 0 0;border:0;border-right:1px solid rgba(225,238,246,.3)}
.nova-about-block+ .nova-about-block{padding-left:54px}
.nova-about-block:last-child{border-right:0}
.nova-about-label{margin:0 0 20px;color:#edf3f5;font:400 15px/1 Georgia,serif;letter-spacing:.02em}
.nova-about-label b{font-weight:400;margin-left:8px}
.nova-about-block dl{gap:11px}
.nova-about-block dl div{grid-template-columns:34px minmax(0,1fr);gap:12px}
.nova-about-block dt svg{width:20px;height:20px;fill:none;stroke:#eef4f6;stroke-width:1.6;vertical-align:middle}
.nova-about-block dd{font:14px/1.25 Georgia,"Microsoft YaHei",serif;color:#e2eaee}
.nova-about-block dd span,.nova-about-links em{font-style:normal;color:rgba(198,214,222,.7);font-size:12px}
.nova-about-links{display:grid;grid-template-columns:1fr;gap:8px}
.nova-about-links a{justify-content:flex-start;padding:0;border:0;color:#e3eaed;font-size:13px;line-height:1.3}
.nova-about-links a img{width:64px;height:34px;object-fit:cover;margin-right:10px;opacity:.86}
.nova-about-links a svg{width:22px;height:22px;flex:0 0 22px;fill:none;stroke:#eff4f5;stroke-width:1.6;margin-right:16px}
.nova-about-links a span{font:13px/1.25 Georgia,"Microsoft YaHei",serif;color:#e4ecef;letter-spacing:0;text-transform:none}
.nova-about-links a:hover{color:#fff;border:0}
@media(max-width:1280px){.nova-about-gallery{left:38%;width:min(580px,48vw)}.nova-about-block+ .nova-about-block{padding-left:32px}}
@media(max-width:900px){.nova-about-content{width:auto;margin:0;padding:232px 20px 178px}.nova-about-gallery{position:relative;left:auto;top:auto;width:min(520px,100%);height:300px;margin:42px 0 0}.nova-about-story{margin-top:38px}.nova-about-editorial{position:relative;bottom:auto;display:block;margin-top:58px}.nova-about-block,.nova-about-block+ .nova-about-block{padding:26px 0;border-right:0;border-bottom:1px solid rgba(225,238,246,.16)}}
@media(min-width:901px){
  .nova-about-editorial{position:fixed;z-index:4;left:calc(var(--coast-panel-x) + var(--coast-panel-width) + 54px);right:48px;bottom:28px}
  .nova-about-comments{display:none}
}

body.nova-archive-route{
  --nova-archive-space-1:6px;
  --nova-archive-space-2:10px;
  --nova-archive-space-3:16px;
  --nova-archive-space-4:22px;
  overflow-x:hidden;
  background:var(--nova-archive-bg);
  color:var(--nova-archive-text)
}
body.nova-archive-route #web_bg{display:none}
body.nova-archive-route #page-header.nova-archive-hero{
  height:clamp(420px,43vh,520px);
  background-position:center 46%;
  background-size:cover;
  background-repeat:no-repeat
}
body.nova-archive-route #page-header.nova-archive-hero::before{
  background:linear-gradient(90deg,rgba(5,9,20,.52),rgba(8,12,28,.14) 58%,rgba(7,10,22,.28)),linear-gradient(180deg,rgba(5,8,18,.16),rgba(7,11,23,.08) 72%,rgba(7,13,25,.24))
}
body.nova-archive-route #page-header.nova-archive-hero::after{content:"";position:absolute;z-index:1;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(4,9,20,.04) 0%,rgba(4,9,20,.08) 68%,rgba(7,13,25,.32) 88%,var(--nova-archive-bg) 100%)}
body.nova-archive-route #page-header #nav{height:68px;background:linear-gradient(180deg,rgba(4,8,18,.58),transparent);box-shadow:none}
body.nova-archive-route #page-header.nav-fixed #nav{background:rgba(7,10,20,.76);border-bottom:1px solid rgba(255,255,255,.06);backdrop-filter:blur(18px)}
body.nova-archive-route #nav a,body.nova-archive-route #nav .site-page{color:rgba(244,239,243,.8)}
body.nova-archive-route #nav a[href="/archives/"]{position:relative;color:#fff}
body.nova-archive-route #nav a[href="/archives/"]::after{content:"";position:absolute;right:12px;bottom:7px;left:12px;height:1px;background:var(--nova-archive-accent)}
body.nova-archive-route #page-site-info.nova-archive-hero-content{position:absolute;z-index:3;top:50%;right:0;left:0;width:min(760px,calc(100% - 48px));margin:0 auto;padding:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;transform:translateY(calc(-50% + 18px))}
.nova-archive-eyebrow{margin:0 0 18px;color:#e39ab3;font-size:11px;letter-spacing:.24em;text-align:center}
body.nova-archive-route #site-title{margin:0;color:#f1d9e2;font:500 clamp(42px,4vw,66px)/1.05 "Noto Serif SC","Songti SC",serif;letter-spacing:.12em;text-align:center;text-shadow:0 15px 42px rgba(0,0,0,.44)}
.nova-archive-subtitle{max-width:680px;margin:20px 0 0;color:rgba(244,238,242,.8);font-size:clamp(15px,1.25vw,19px);line-height:1.8;letter-spacing:.08em;text-align:center}
.nova-archive-scroll{display:inline-flex;align-items:center;justify-content:center;gap:12px;margin-top:28px;color:rgba(232,218,226,.52);font-size:10px;letter-spacing:.18em;text-align:center}
.nova-archive-scroll::before,.nova-archive-scroll::after{content:"";width:46px;height:1px;background:linear-gradient(90deg,transparent,rgba(213,107,138,.65))}
.nova-archive-scroll::after{transform:rotate(180deg)}

body.nova-archive-route #content-inner.nova-archive-main{
  position:relative;
  z-index:2;
  display:grid;
  grid-template-columns:minmax(0,1.68fr) minmax(330px,.92fr);
  align-items:start;
  gap:clamp(26px,3vw,38px);
  width:min(1380px,calc(100% - clamp(56px,10vw,144px)));
  max-width:none;
  margin:-56px auto 0;
  padding:0 0 clamp(52px,6vw,78px)
}
body.nova-archive-route #body-wrap{
  background:radial-gradient(circle at 82% 8%,rgba(112,137,158,.08),transparent 28%),radial-gradient(circle at 12% 38%,rgba(199,96,130,.065),transparent 30%),linear-gradient(180deg,var(--nova-archive-bg),var(--nova-archive-section-bg) 48%,var(--nova-archive-bg))
}
body.nova-archive-route #content-inner.nova-archive-main::before{content:"";position:absolute;z-index:0;inset:-20px calc(50% - 50vw) 0;pointer-events:none;background:url("/img/guidang.webp") center top/cover no-repeat;opacity:.035;filter:blur(30px) saturate(.72);mask-image:linear-gradient(180deg,rgba(0,0,0,.72),transparent 54%);-webkit-mask-image:linear-gradient(180deg,rgba(0,0,0,.72),transparent 54%)}
.nova-archive-main-card,.nova-archive-sidebar{position:relative;z-index:2}
.nova-archive-main-card,.nova-archive-sidebar,.nova-archive-profile-card,.nova-archive-stats-card{box-sizing:border-box;margin-bottom:0!important}
.nova-archive-timeline{
  display:flex;
  width:auto!important;
  height:auto;
  min-height:0;
  align-self:start!important;
  flex-direction:column;
  min-width:0;
  padding:30px 32px 26px!important;
  border:1px solid var(--nova-archive-line);
  border-radius:24px;
  background:var(--nova-archive-card)!important;
  box-shadow:0 24px 70px rgba(0,0,0,.28)!important;
  backdrop-filter:blur(16px);
  -webkit-backdrop-filter:blur(16px)
}
.nova-archive-panel-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:30px;padding-bottom:20px;border-bottom:1px solid var(--nova-archive-line)}
.nova-archive-panel-heading>div{display:grid;grid-template-columns:auto auto;align-items:center;gap:2px 10px}
.nova-archive-panel-heading span{grid-row:1/3;color:var(--nova-archive-accent);font-size:22px}
.nova-archive-panel-heading strong{color:var(--nova-archive-text);font-size:17px}
.nova-archive-panel-heading small{color:var(--nova-archive-muted);font-size:11px}
.nova-archive-panel-heading>b{color:var(--nova-archive-muted);font-size:10px;letter-spacing:.14em}
.nova-archive-timeline .article-sort{display:flex;min-height:0;margin-left:18px;padding-left:32px;flex-direction:column;border-left:1px solid rgba(171,112,137,.3)}
.nova-archive-timeline .article-sort-title{display:none}
.nova-archive-timeline .article-sort-item.year{
  height:auto;
  margin:10px 0 18px -42px;
  padding:0 0 0 42px;
  color:#e5b2c4;
  font:600 20px/1.4 "Noto Serif SC","Songti SC",serif
}
.nova-archive-timeline .article-sort-item.year::before{left:-1px;width:16px;height:16px;border:2px solid rgba(229,178,196,.32);border-radius:5px;background:var(--nova-archive-accent);box-shadow:0 0 0 4px rgba(199,96,130,.08)}
.nova-archive-timeline .nova-archive-month{
  height:auto;
  margin:30px 0 14px;
  padding:0;
  color:rgba(205,143,168,.82);
  font-size:11px;
  letter-spacing:.14em
}
.nova-archive-timeline .nova-archive-month::before{display:none}
.nova-archive-timeline .article-sort-item:not(.year):not(.nova-archive-month){
  min-height:98px;
  max-height:106px;
  margin:0 0 16px;
  padding:16px;
  flex:1 1 98px;
  border:1px solid rgba(224,194,208,.075);
  border-radius:12px;
  background:rgba(20,27,48,.52);
  transition:transform .25s,border-color .25s,box-shadow .25s,background .25s
}
.nova-archive-timeline .article-sort-item:not(.year):not(.nova-archive-month)::before{
  left:-39px;
  width:10px;
  height:10px;
  border:2px solid #d8bed0;
  background:#8b6c7a;
  box-shadow:0 0 0 4px rgba(184,111,139,.1)
}
.nova-archive-timeline .article-sort-item:not(.year):not(.nova-archive-month):hover{
  transform:translateY(-2px);
  border-color:rgba(213,107,138,.22);
  background:rgba(23,31,55,.7);
  box-shadow:0 10px 24px rgba(0,0,0,.18)
}
.nova-archive-timeline .article-sort-item:not(.year):not(.nova-archive-month):hover::before{background:var(--nova-archive-accent);box-shadow:0 0 0 5px rgba(202,112,151,.13),0 0 16px rgba(202,112,151,.12)}
.nova-archive-timeline .article-sort-item-img{width:72px;height:64px;margin-right:16px;border-radius:8px}
.nova-archive-timeline .article-sort-item-img img{width:100%;height:100%;object-fit:cover}
.nova-archive-timeline .article-sort-item-info{display:flex;min-width:0;flex:1;flex-direction:column-reverse;justify-content:center}
.nova-archive-timeline .article-sort-item-title{overflow:hidden;color:var(--nova-archive-text);font-size:15px;font-weight:500;text-overflow:ellipsis;white-space:nowrap}
.nova-archive-timeline .article-sort-item-time{margin-top:7px;color:var(--nova-archive-muted);font-size:11px}
.nova-archive-card-footer{position:relative;min-height:0;padding:20px 0 0;flex:0 0 auto}
.nova-archive-continuation{position:relative;display:grid;min-height:0;padding:22px 8px 18px 32px;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:8px 18px;border-top:1px solid rgba(222,189,207,.08);background:linear-gradient(90deg,rgba(194,99,135,.055),rgba(105,126,145,.025),transparent)}
.nova-archive-continuation-marker{position:absolute;top:37px;left:0;width:10px;height:10px;border:1px solid rgba(224,190,207,.64);background:var(--nova-archive-accent);transform:rotate(45deg);box-shadow:0 0 10px rgba(199,96,130,.14)}
.nova-archive-continuation::before{content:"";position:absolute;top:-22px;bottom:46px;left:4px;width:1px;background:linear-gradient(180deg,rgba(154,112,131,.36),rgba(199,96,130,.3))}
.nova-archive-continuation-copy>span{color:#cc839d;font-size:10px;letter-spacing:.16em}
.nova-archive-continuation-copy p{margin:5px 0 0;color:var(--nova-archive-secondary);font-size:12px}
.nova-archive-continuation-meta{color:var(--nova-archive-muted);font-size:10px;white-space:nowrap}
.nova-archive-timeline #pagination{margin:20px 0 0;padding:0}
.nova-archive-timeline #pagination .pagination{display:flex;justify-content:center;gap:8px}
.nova-archive-timeline #pagination .page-number,.nova-archive-timeline #pagination .extend{display:grid;width:36px;height:36px;margin:0;place-items:center;border:1px solid var(--nova-archive-line);border-radius:12px;color:var(--nova-archive-secondary);background:rgba(255,255,255,.035);transition:.25s}
.nova-archive-timeline #pagination .current{color:#fff;background:var(--nova-archive-accent);box-shadow:0 8px 22px rgba(199,96,130,.24)}
.nova-archive-timeline #pagination a:hover{transform:translateY(-2px);border-color:rgba(213,107,138,.3);color:#fff}

.nova-archive-sidebar{display:flex!important;width:auto!important;height:auto;min-width:0;min-height:0;align-self:start;padding:0!important;flex-direction:column;gap:20px;word-break:normal}
.nova-archive-sidebar .sticky_layout{position:static!important;display:flex;min-height:0;margin:0!important;padding:0!important;flex:none;flex-direction:column;gap:20px}
.nova-archive-stats-card{margin-top:0!important;margin-bottom:0!important}
.nova-archive-side-card{min-width:0;flex-shrink:0;overflow-wrap:anywhere}
.nova-archive-sidebar>.card-widget,.nova-archive-side-module{
  margin:0!important;
  padding:20px!important;
  border:1px solid var(--nova-archive-line)!important;
  border-radius:20px!important;
  background:var(--nova-archive-card)!important;
  box-shadow:0 18px 48px rgba(0,0,0,.2)!important;
  backdrop-filter:blur(15px)
}
.nova-archive-profile .avatar-img{width:86px;height:86px;margin:0 auto 10px}
.nova-archive-profile .author-info-name{color:var(--nova-archive-text);font:500 22px "Noto Serif SC","Songti SC",serif}
.nova-archive-profile .site-data{margin:14px 0}
.nova-archive-profile .site-data .headline{color:var(--nova-archive-muted);font-size:11px}
.nova-archive-profile .site-data .length-num{color:var(--nova-archive-text);font-size:17px}
.nova-archive-profile #card-info-btn{border:1px solid var(--nova-archive-line);border-radius:999px;background:linear-gradient(90deg,rgba(113,139,159,.12),rgba(199,96,130,.12))}
.nova-archive-side-module>header{margin-bottom:var(--nova-archive-space-2);padding-bottom:var(--nova-archive-space-2);border-bottom:1px solid var(--nova-archive-line);color:#dca0b5;font-size:12px;line-height:1.4;letter-spacing:.12em}
.nova-archive-side-module>.card-widget{margin:0!important;padding:0!important;border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important}
.nova-archive-side-module>.card-widget+.card-widget{margin-top:var(--nova-archive-space-3)!important;padding-top:var(--nova-archive-space-3)!important;border-top:1px solid var(--nova-archive-line)!important}
.nova-archive-side-module .item-headline{margin-bottom:var(--nova-archive-space-2);color:var(--nova-archive-secondary);font-size:13px;line-height:1.5}
.nova-archive-signal .announcement_content{padding:10px 12px;border-radius:10px;color:var(--nova-archive-secondary);background:rgba(199,96,130,.07)}
.nova-archive-signal .aside-list-item{padding:5px 0}
.nova-archive-signal .aside-list-item .thumbnail{width:54px;height:54px;border-radius:8px}
.nova-archive-signal .aside-list-item .title{color:var(--nova-archive-text);font-size:12px}
.nova-archive-signal .aside-list-item time{color:var(--nova-archive-muted);font-size:10px}
.nova-archive-taxonomy .card-category-list a,.nova-archive-stats .card-archive-list a{color:var(--nova-archive-secondary)}
.nova-archive-taxonomy .card-tag-cloud a{display:inline-flex;margin:3px;padding:5px 9px;border:1px solid var(--nova-archive-line);border-radius:999px;color:var(--nova-archive-secondary)!important;background:rgba(255,255,255,.035)}
.nova-archive-stats .webinfo-item{padding:3px 0;color:var(--nova-archive-secondary);line-height:1.5}
body.nova-archive-route footer#footer{margin:0;border-top:1px solid rgba(199,96,130,.12);background:#070b16}

html[data-theme="light"] body.nova-archive-route #page-header.nova-archive-hero::before{background:linear-gradient(90deg,rgba(9,12,24,.48),rgba(9,12,24,.1) 64%),linear-gradient(180deg,rgba(7,13,27,.06),rgba(7,13,27,.02) 70%,rgba(75,72,91,.08))}
html[data-theme="light"] body.nova-archive-route #page-header.nova-archive-hero::after{background:linear-gradient(180deg,rgba(8,13,27,.03) 0%,rgba(8,13,27,.02) 60%,rgba(105,98,122,.09) 78%,rgba(211,207,218,.34) 91%,var(--nova-archive-bg) 100%)}
html[data-theme="light"] body.nova-archive-route #body-wrap{background:radial-gradient(circle at 78% 8%,rgba(188,99,133,.055),transparent 30%),radial-gradient(circle at 18% 24%,rgba(111,130,145,.04),transparent 32%),linear-gradient(180deg,#efedf2 0%,#e9e7ee 52%,#e6e5eb 100%)}
html[data-theme="light"] .nova-archive-main-card,html[data-theme="light"] .nova-archive-side-card{border-color:rgba(255,255,255,.56)!important;background:linear-gradient(145deg,rgba(255,254,255,.82),rgba(244,241,247,.72))!important;box-shadow:0 24px 65px rgba(53,43,62,.105),inset 0 1px rgba(255,255,255,.62)!important;backdrop-filter:blur(20px) saturate(110%);-webkit-backdrop-filter:blur(20px) saturate(110%)}
html[data-theme="light"] .nova-archive-continuation{border-top-color:rgba(79,66,87,.08);background:linear-gradient(90deg,rgba(189,95,124,.055),rgba(111,130,145,.022),transparent)}
html[data-theme="light"] .nova-archive-timeline .nova-archive-month{color:rgba(162,93,119,.78)}
html[data-theme="light"] .nova-archive-timeline,html[data-theme="light"] .nova-archive-sidebar>.card-widget,html[data-theme="light"] .nova-archive-side-module{box-shadow:0 20px 55px rgba(56,45,65,.09)!important}
html[data-theme="light"] .nova-archive-timeline .article-sort-item:not(.year):not(.nova-archive-month){background:rgba(255,255,255,.48)}
html[data-theme="light"] .nova-archive-timeline .article-sort-item:not(.year):not(.nova-archive-month):hover{background:rgba(255,250,252,.76)}
html[data-theme="light"] .nova-archive-profile #card-info-btn{color:#fff;background:linear-gradient(90deg,#758997,#bd5f7c)}
html[data-theme="light"] body.nova-archive-route footer#footer{border-top-color:rgba(189,96,125,.16);background:linear-gradient(180deg,#dad9e2,#d0d2dd);color:#514c59}

@media(min-width:1101px) and (min-height:850px){
  .nova-archive-sidebar{position:sticky;top:88px}
}
@media(max-width:1180px){
  body.nova-archive-route #content-inner.nova-archive-main{grid-template-columns:minmax(0,1.55fr) minmax(280px,.72fr);gap:clamp(26px,3vw,34px);width:calc(100% - 48px)}
  .nova-archive-timeline{padding:24px 22px 28px!important}
}
@media(max-width:1024px){
  body.nova-archive-route #page-header.nova-archive-hero{height:340px}
  body.nova-archive-route #content-inner.nova-archive-main{display:block;width:calc(100% - 40px);margin-top:-24px;padding:0 0 58px}
  body.nova-archive-route #content-inner.nova-archive-main::before{display:none}
  .nova-archive-main-card,.nova-archive-sidebar{height:auto}
  .nova-archive-sidebar{margin-top:22px}
  .nova-archive-sidebar .sticky_layout{flex:none}
  .nova-archive-stats-card{margin-top:0!important}
  .nova-archive-timeline .article-sort{margin-left:10px;padding-left:23px}
  .nova-archive-timeline .article-sort-item:not(.year):not(.nova-archive-month)::before{left:-30px}
  .nova-archive-timeline .article-sort-item.year{margin-left:-33px;padding-left:33px}
}
@media(max-width:768px){
  body.nova-archive-route #content-inner.nova-archive-main{width:calc(100% - 28px)}
}
@media(max-width:480px){
  .nova-archive-subtitle{font-size:14px;line-height:1.8}
  .nova-archive-scroll{display:none}
  .nova-archive-timeline{padding:20px 14px 24px!important;border-radius:18px}
  .nova-archive-panel-heading small,.nova-archive-panel-heading>b{display:none}
  .nova-archive-timeline .article-sort-item:not(.year):not(.nova-archive-month){min-height:78px;padding:10px}
  .nova-archive-timeline .article-sort-item:not(.year):not(.nova-archive-month){max-height:none;flex:none}
  .nova-archive-continuation{grid-template-columns:1fr;padding-left:28px}
  .nova-archive-continuation-meta{white-space:normal}
  .nova-archive-timeline .article-sort-item-img{width:56px;height:56px;margin-right:11px}
  .nova-archive-timeline .article-sort-item-title{font-size:13px}
}

/* The desktop proportions follow the 1683 × 935 reference. */
.nova-home-active{background:#233749;overflow-x:hidden}
.nova-home-active #web_bg,.nova-home-active #page-header,.nova-home-active #rightside,.nova-home-active #footer{display:none!important}
.coast-home,.coast-home *{box-sizing:border-box}
.coast-home{position:relative;isolation:isolate;min-height:650px;height:100svh;overflow:hidden;color:var(--coast-ink);font:400 14px/1.5 var(--coast-font)}
.coast-home a{color:inherit;text-decoration:none}
:is(.coast-home,.nova-about-shell) button:disabled{cursor:default}
:is(.coast-home,.nova-about-shell) button{margin:0;padding:0;border:0;color:inherit;background:transparent;font:inherit;cursor:pointer}
:is(.coast-home,.nova-about-shell) svg{display:block;width:24px;height:24px;fill:none;stroke:currentColor;stroke-width:1.25;stroke-linecap:round;stroke-linejoin:round}
:is(.coast-home,.nova-about-shell) a:focus-visible,:is(.coast-home,.nova-about-shell) button:focus-visible{outline:2px solid #d8e9f2;outline-offset:6px;border-radius:3px}
:is(.coast-home,.nova-about-shell) a:hover,:is(.coast-home,.nova-about-shell) button:hover{color:#fff}
.coast-background,.coast-shade,.coast-snow{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.coast-background{z-index:-3;object-fit:cover;object-position:center}
.coast-shade{z-index:-2;background:linear-gradient(180deg,rgba(20,37,51,.10),rgba(9,20,30,.06) 65%,rgba(9,20,30,.12))}
.coast-snow{z-index:-1;opacity:.38}
.coast-lightning{position:absolute;left:16%;top:0;width:40%;height:35%;z-index:-1;pointer-events:none;overflow:hidden;opacity:0;mix-blend-mode:screen;mask-image:radial-gradient(ellipse,black 35%,transparent 73%);-webkit-mask-image:radial-gradient(ellipse,black 35%,transparent 73%)}
.coast-lightning img{position:absolute;left:50%;top:50%;width:auto;height:155%;max-width:none;filter:contrast(2.3) brightness(1.1);mask-image:radial-gradient(ellipse,black 35%,transparent 73%);-webkit-mask-image:radial-gradient(ellipse,black 35%,transparent 73%)}
.coast-lightning[data-region=right]{left:79%;top:5%;width:21%;height:42%}
@media(max-width:900px){.coast-lightning{left:6%;top:0;width:88%;height:30%}}
.coast-sidebar{position:absolute;left:var(--coast-panel-x);top:var(--coast-panel-y);bottom:var(--coast-panel-y);width:var(--coast-panel-width);min-width:180px;padding:38px 26px 40px;display:flex;flex-direction:column;border:1px solid var(--coast-glass-border);border-radius:var(--coast-radius);background:var(--coast-glass);backdrop-filter:blur(var(--coast-blur));-webkit-backdrop-filter:blur(var(--coast-blur));box-shadow:inset 0 1px rgba(255,255,255,.04),0 4px 18px rgba(0,0,0,.06)}
.coast-brand h1{margin:0 0 12px;color:#c7cfd6;font:400 40px/1.4 Inter,"Microsoft YaHei",sans-serif}
.coast-brand p{margin:0;font-size:clamp(11px,.72vw,12px);line-height:1.8;color:rgba(195,208,219,.62);letter-spacing:.025em}
.coast-brand{padding-bottom:28px;border-bottom:1px solid rgba(207,223,235,.12)}
.coast-nav{display:grid;gap:19px;margin-top:27px}
.coast-nav a{display:grid;grid-template-columns:22px 6px 1fr;align-items:center;gap:10px;font-size:14px;line-height:23px;color:#aab7c2}
.coast-nav a>span{color:rgba(170,183,194,.48)}.coast-nav b{font-weight:300}.coast-nav i{height:6px;width:6px;border-radius:50%;background:transparent}
.coast-nav .is-selected{color:#edf3f7}.coast-nav .is-selected>span{color:rgba(170,183,194,.48)}.coast-nav .is-selected i{background:#e3edf3}
.coast-sidebar-bottom{margin-top:auto}
.coast-music-art{position:relative;height:66px;overflow:hidden;border-radius:6px;margin-bottom:8px}
.coast-music-art img{display:block;height:100%;width:100%;object-fit:cover;object-position:center}
.coast-music-art::after{content:"";position:absolute;inset:0;background:rgba(24,43,57,.12);pointer-events:none}
.coast-music-art button{position:absolute;right:10px;bottom:10px;z-index:1;width:24px;height:24px;border:1px solid rgba(224,231,237,.72);border-radius:50%;display:grid;place-items:center;color:#eef2f6}
.coast-music-art button svg{width:14px;height:14px}.coast-music-art button svg path{fill:currentColor;stroke-width:1}
.coast-music-info{display:flex;align-items:center;gap:8px;font-size:11px;line-height:17px}.coast-music-info>svg{flex:0 0 21px;width:21px;height:21px}.coast-music-info>span{min-width:0}
.coast-music-info span span{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.coast-progress{height:.5px;background:rgba(210,224,235,.12);margin-top:12px}.coast-progress span{display:block;width:0;height:100%;background:#dae3e9}
.coast-music-retry{font-size:11px!important;margin-top:8px!important}
.coast-social{display:flex;align-items:center;justify-content:space-between;margin-top:28px}.coast-social svg{width:21px;height:21px;opacity:.8}
.coast-theme-icons{position:relative;display:block;width:21px;height:21px}
.coast-theme-icon{position:absolute;inset:0;transition:opacity .24s ease,transform .24s ease}
html[data-theme="light"] .coast-theme-icon--moon,
html[data-theme="dark"] .coast-theme-icon--sun{opacity:1;transform:rotate(0) scale(1)}
html[data-theme="light"] .coast-theme-icon--sun{opacity:0;transform:rotate(-24deg) scale(.72)}
html[data-theme="dark"] .coast-theme-icon--moon{opacity:0;transform:rotate(24deg) scale(.72)}
.coast-toolbar{position:absolute;right:1.85%;top:20px;display:flex;gap:24px;align-items:center;height:30px;color:#b8c4ce}
.coast-toolbar-rule{width:1px;height:20px;background:rgba(214,227,236,.18)}
.coast-now-playing{display:flex;align-items:center;gap:10px;font-size:13px}.coast-now-playing svg{width:24px;height:24px;color:#bdc9d2}.coast-now-playing>span{width:140px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.coast-top-play svg{width:24px;height:24px;color:#c4ced6;stroke-width:3}.coast-top-play svg path[data-play]{stroke-width:1.5;fill:currentColor}
.coast-home .coast-snow-toggle{min-width:78px;height:30px;font:400 12px/30px Consolas,"Courier New",monospace;letter-spacing:.02em;color:rgba(188,204,216,.65);white-space:nowrap}.coast-home .coast-snow-toggle[aria-checked=true]{color:rgba(205,221,233,.82)}
.coast-recent{position:absolute;top:19.45%;right:calc(8.3% + 26px);width:22.1%;min-width:340px;isolation:isolate}
.coast-recent::before{content:"";position:absolute;inset:-14px -24px;z-index:-1;pointer-events:none;background:radial-gradient(ellipse at center,rgba(9,20,30,.07),rgba(9,20,30,.04) 55%,transparent 75%)}
.coast-entry{display:grid;grid-template-columns:68px minmax(0,1fr) 20px;align-items:center;gap:18px;min-height:59px;border-bottom:1px solid rgba(216,229,238,.18);font-size:15px}.coast-entry:last-child{border-bottom:0}
.coast-entry>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.coast-entry time{font-variant-numeric:tabular-nums}.coast-entry svg{width:20px;height:20px;opacity:.8}
.coast-timeline{position:absolute;top:15.1%;right:1.5%;width:57px;color:#889aaa;font-size:13px}.coast-year,.coast-more{display:flex;align-items:center;gap:15px}.coast-year::before,.coast-more::before{content:"";width:5px;height:5px;border-radius:50%;background:#8d9ead}.coast-year{margin-bottom:10px}
.coast-months{margin-left:2px;border-left:1px solid rgba(207,223,235,.55)}.coast-months a{position:relative;display:flex;align-items:center;height:74px;padding-left:17px}.coast-months a:first-child{height:58px;padding-bottom:16px}.coast-months i{position:absolute;left:-4px;width:7px;height:7px;border-radius:50%;background:#8196a7}
.coast-months .is-selected{color:#f1f5f8}.coast-months .is-selected i{width:10px;height:10px;left:-5.5px;background:#ebf1f6;border:2px solid #263e51;outline:1px solid #d8e3ec}.coast-more{margin-top:13px}
@media(max-height:760px) and (min-width:901px){.coast-sidebar{padding-top:22px;padding-bottom:25px}.coast-brand{padding-bottom:24px}.coast-nav{gap:14px;margin-top:20px}.coast-social{margin-top:24px}}
@media(max-width:1200px) and (min-width:901px){.coast-sidebar{padding-left:22px;padding-right:22px}.coast-toolbar{gap:20px}.coast-recent{width:36%;right:calc(11% + 26px)}.coast-timeline{right:2%}}
@media(max-width:900px){
 .coast-home{min-height:800px;height:100svh}.coast-background{object-position:64% center}
 .coast-sidebar{left:16px;right:16px;top:74px;bottom:auto;width:auto;min-width:0;padding:22px 24px;background:rgba(26,44,58,.20);backdrop-filter:none;-webkit-backdrop-filter:none}
 .coast-brand{padding:0;border:0}.coast-brand h1{font-size:32px;margin:0 0 5px}.coast-brand p{font-size:11px}
 .coast-nav{grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:18px}.coast-nav a{display:flex;gap:8px;font-size:13px}.coast-nav a>span{font-size:10px}.coast-nav i{display:none}
 .coast-sidebar-bottom{position:fixed;left:16px;right:16px;bottom:16px;padding:14px 18px;border:1px solid rgba(216,229,238,.25);border-radius:10px;background:rgba(21,36,47,.48);backdrop-filter:blur(12px);display:flex;align-items:center;gap:20px}
 .coast-mini-player{flex:1;min-width:0}.coast-music-art{display:none}.coast-social{margin:0;gap:16px}.coast-social svg{width:20px;height:20px}.coast-progress{margin-top:8px}
 .coast-toolbar{top:22px;right:20px;left:20px;gap:16px}.coast-now-playing{min-width:0;flex:1;gap:8px;font-size:11px}.coast-now-playing>span{width:auto}.coast-now-playing svg{width:22px;flex-shrink:0}.coast-toolbar-rule{height:20px}
 .coast-home .coast-snow-toggle{min-width:72px;height:30px;font-size:11px;flex-shrink:0}
 .coast-recent{top:315px;left:24px;right:75px;width:auto;min-width:0}.coast-entry{grid-template-columns:43px minmax(0,1fr) 16px;gap:12px;min-height:66px;font-size:13px}.coast-entry svg{width:16px}
 .coast-timeline{top:312px;right:14px;width:43px;font-size:10px}.coast-months a{height:57px;padding-left:10px}.coast-year,.coast-more{gap:9px}
}
@media(prefers-reduced-motion:reduce){.coast-home *{transition:none!important;animation:none!important}}

/* ============================================================
   Article reading mode (sea route)
   - fixed TOC sidebar sharing the homepage cold-blue glass
   - body offset: left TOC / article / right sea stay in column
   - deep-sea blue-grey code blocks with brighter code text
   ============================================================ */

body.article-sea-route{
  --post-code-bg:rgba(23,43,58,.9);
  --post-code-header-bg:rgba(27,49,66,.94);
  --post-code-gutter-bg:rgba(16,34,49,.85);
  --post-code-text:#e8f0f4;
  --post-inline-code-bg:rgba(115,160,195,.12);
  background:#0d1925;
  color:#dce4ea;
}
body.article-sea-route #body-wrap{background:transparent}
body.article-sea-route #sidebar,body.article-sea-route .nova-page-loading{display:none}

.article-reading-shell{
  --article-sidebar-x:32px;
  --article-sidebar-w:228px;
  --article-sidebar-gap:28px;
  position:relative;
  isolation:isolate;
  min-height:100svh;
  padding:16px 32px 72px;
  overflow:hidden;
  font-family:Inter,"PingFang SC","Microsoft YaHei",sans-serif;
}

/* Background: one sea photo keeps the person and the ship on the right. */
.article-page-bg{position:fixed;z-index:-3;inset:-3%;overflow:hidden;background:#0d1925}
.article-page-bg img{width:100%;height:100%;object-fit:cover;filter:blur(12px) brightness(.72) saturate(.82);transform:scale(1.04)}
.article-reading-dimmer{position:fixed;z-index:-2;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(17,31,45,.90) 0%,rgba(20,37,52,.82) 56%,rgba(28,48,65,.46) 78%,transparent 96%)}

/* Snow: the same canvas engine and lightning layer as the homepage. */
.article-sea-snow{position:fixed;z-index:-1;inset:0;overflow:hidden;pointer-events:none;opacity:.38}
.article-sea-snow canvas{display:block;width:100%;height:100%}
.article-sea-snow .coast-lightning{position:absolute;left:16%;top:0;width:40%;height:35%;z-index:0;pointer-events:none;overflow:hidden;opacity:0;mix-blend-mode:screen;-webkit-mask-image:radial-gradient(ellipse,black 35%,transparent 73%);mask-image:radial-gradient(ellipse,black 35%,transparent 73%)}
.article-sea-snow .coast-lightning img{position:absolute;left:50%;top:50%;width:auto;height:155%;max-width:none;filter:contrast(2.3) brightness(1.1);-webkit-mask-image:radial-gradient(ellipse,black 35%,transparent 73%);mask-image:radial-gradient(ellipse,black 35%,transparent 73%)}
.article-sea-snow .coast-lightning[data-region=right]{left:79%;top:5%;width:21%;height:42%}

/* Top-right toolbar: mirrors the homepage coast toolbar. */
.article-topbar{position:fixed;z-index:8;right:1.85%;top:20px;display:flex;gap:24px;align-items:center;height:30px;color:#b8c4ce}
.article-topbar button,.article-topbar a{margin:0;padding:0;border:0;color:inherit;background:none;text-decoration:none;cursor:pointer}
.article-topbar button:disabled{cursor:default}
.article-topbar svg{display:block;width:24px;height:24px;fill:none;stroke:currentColor;stroke-width:1.25;stroke-linecap:round;stroke-linejoin:round}
.article-topbar a:hover,.article-topbar button:hover{color:#fff}
.article-topbar a:focus-visible,.article-topbar button:focus-visible{outline:2px solid #d8e9f2;outline-offset:6px;border-radius:3px}
.article-topbar .coast-toolbar-rule{width:1px;height:20px;background:rgba(214,227,236,.18)}
.article-topbar .coast-now-playing{display:flex;align-items:center;gap:10px;font:13px Inter,"Microsoft YaHei",sans-serif}
.article-topbar .coast-now-playing svg{width:24px;height:24px;color:#bdc9d2}
.article-topbar .coast-now-playing>span{width:140px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.article-topbar .coast-top-play svg{width:24px;height:24px;color:#c4ced6;stroke-width:3}
.article-topbar .coast-top-play svg path[data-play]{stroke-width:1.5;fill:currentColor}
.article-topbar .coast-top-play:disabled{opacity:.7}
.article-topbar .coast-snow-toggle{min-width:78px;height:30px;font:400 12px/30px Consolas,"Courier New",monospace;letter-spacing:.02em;color:rgba(188,204,216,.65);white-space:nowrap}
.article-topbar .coast-snow-toggle[aria-checked=true]{color:rgba(205,221,233,.82)}

/* Fixed table of contents: homepage cold-blue frosted glass, never a dark board. */
.article-toc-sidebar{
  position:fixed;
  z-index:6;
  left:var(--article-sidebar-x);
  top:16px;
  width:var(--article-sidebar-w);
  height:calc(100vh - 32px);
  padding:28px 22px 20px;
  display:flex;
  flex-direction:column;
  border:1px solid rgba(216,229,238,.19);
  border-radius:12px;
  background:linear-gradient(160deg,rgba(134,168,196,.16),rgba(21,45,64,.26));
  backdrop-filter:blur(20px) saturate(125%);
  -webkit-backdrop-filter:blur(20px) saturate(125%);
  box-shadow:inset 0 1px rgba(255,255,255,.06),0 18px 50px rgba(0,0,0,.14);
}
.article-toc-sidebar header{font:11px/1.4 "JetBrains Mono",Consolas,monospace;letter-spacing:.04em;color:#9fb4c3}
.article-toc-sidebar header>a{color:#dce8ef;text-decoration:none}
.article-toc-sidebar header>span{float:right;color:#8199aa}
.article-toc-sidebar header em{clear:both;display:block;height:1px;margin-top:22px;background:rgba(225,238,246,.15)}
.article-toc-list{min-height:0;margin:22px -8px;overflow:auto;scrollbar-width:none}
.article-toc-list::-webkit-scrollbar{display:none}
.article-toc-link{position:relative;display:block;padding:6px 8px 6px 12px;color:rgba(197,214,224,.42);font-size:12px;line-height:1.45;text-decoration:none;transition:color .25s ease,opacity .25s ease}
.article-toc-link span{display:inline-block;width:26px;font:10px/1.6 "JetBrains Mono",Consolas,monospace;color:rgba(175,197,213,.38)}
.article-toc-link--h3{padding-left:38px;font-size:11px;color:rgba(176,194,206,.3)}
.article-toc-link.is-active{color:#eef4f8}
.article-toc-link.is-active:before{content:"";position:absolute;left:0;top:7px;bottom:7px;width:2px;background:rgba(190,220,240,.85);box-shadow:0 0 10px rgba(160,205,235,.18)}
.article-toc-link.is-active span{color:#9fc9e6;text-shadow:0 0 12px rgba(120,190,230,.12)}
.article-toc-link--h3{display:none}
.article-toc-link--h3.is-expanded{display:block}
.article-toc-sidebar footer{display:flex;align-items:center;gap:14px;margin-top:auto;font:10px/1 "JetBrains Mono",Consolas,monospace}
.article-toc-sidebar footer a,.article-toc-sidebar footer button{border:0;color:#8194a3;background:none;text-decoration:none;cursor:pointer;font:inherit}
.article-toc-sidebar footer button:last-child{margin-left:auto}
.article-toc-sidebar footer button[data-article-theme]{display:inline-flex;align-items:center}
.article-theme-icons{position:relative;display:block;width:15px;height:15px}
.article-theme-icon{position:absolute;inset:0;width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.4;stroke-linecap:round;stroke-linejoin:round;transition:opacity .24s ease,transform .24s ease}
html[data-theme="light"] .article-theme-icon--moon,
html[data-theme="dark"] .article-theme-icon--sun{opacity:1;transform:rotate(0) scale(1)}
html[data-theme="light"] .article-theme-icon--sun{opacity:0;transform:rotate(-24deg) scale(.72)}
html[data-theme="dark"] .article-theme-icon--moon{opacity:0;transform:rotate(24deg) scale(.72)}

/* Article column: offset to the right of the fixed TOC, clear of the sea scene. */
.article-workspace{position:relative;z-index:2;max-width:860px;margin-left:calc(var(--article-sidebar-x) + var(--article-sidebar-w) + var(--article-sidebar-gap));padding:82px 0 80px}
.article-header{max-width:740px;margin-bottom:58px;animation:article-enter .45s cubic-bezier(.22,.61,.36,1) both}
.article-header>div{display:flex;justify-content:space-between;gap:24px;color:#91a2b2;font:11px/1.5 "JetBrains Mono",Consolas,monospace;letter-spacing:.05em}
.article-header>div b{font-weight:500;color:#a7c5d8}
.article-header h1{margin:22px 0 0;color:#f4f7fa;font-size:clamp(38px,3vw,52px);font-weight:600;line-height:1.18;letter-spacing:-.025em}
.article-header p{margin:18px 0 0;color:rgba(199,211,221,.78);font-size:17px;line-height:1.8}

.article-prose{max-width:740px;color:#dce4ea;font-size:16px;line-height:1.85;letter-spacing:.01em;animation:article-enter .5s .06s cubic-bezier(.22,.61,.36,1) both;counter-reset:article-section}
.article-prose p{margin:0 0 1.55em}
.article-prose h2,.article-prose h3{position:relative;scroll-margin-top:40px}
.article-prose h2{margin:64px 0 22px;padding:0;border:0;color:#f3f6f8;font-size:25px;font-weight:600;line-height:1.35}
.article-prose h2:before{content:counter(article-section,decimal-leading-zero) " /";counter-increment:article-section;display:block;margin-bottom:9px;color:rgba(175,197,213,.5);font:11px/1 "JetBrains Mono",Consolas,monospace}
.article-prose h3{margin:38px 0 16px;color:#e9eef2;font-size:20px;font-weight:550;line-height:1.45}
.article-prose a{color:#9fc4dc;text-decoration-color:rgba(159,196,220,.35)}
.article-prose strong{color:#f0f5f8}
.article-prose blockquote{margin:28px 0;padding:3px 0 3px 18px;border-left:1px solid rgba(190,220,240,.32);color:#a7b5c0;background:none}
.article-prose :not(pre)>code{padding:.16em .38em;border-radius:4px;background:rgba(115,160,195,.1);color:#a9cee8;font:.87em "JetBrains Mono",Consolas,monospace}
.article-prose table{width:min(850px,100%);margin:30px 0;border-collapse:collapse;background:none;color:#dce4ea}
.article-prose th{padding:10px 14px;border:0;border-bottom:1px solid rgba(220,235,245,.12);background:none;color:#a9c6d8;font:11px/1.5 "JetBrains Mono",Consolas,monospace;text-align:left}
.article-prose td{padding:13px 14px;border:0;border-bottom:1px solid rgba(220,235,245,.07)}
.article-prose tr:nth-child(2n){background:transparent}
.article-prose img{max-width:100%;border-radius:4px}

/* Deep-sea blue-grey code blocks with brighter text. */
.article-prose pre,.article-prose .highlight{width:min(880px,calc(100vw - 320px));margin:30px 0;border:1px solid rgba(170,205,224,.15);border-radius:8px;background:var(--post-code-bg);box-shadow:none}
.article-prose .highlight table{margin:0}
.article-prose pre{padding:18px;overflow:auto}
body.article-sea-route #article-container.article-prose figure.highlight,
body.article-sea-route #article-container.article-prose figure.highlight table,
body.article-sea-route #article-container.article-prose figure.highlight tbody,
body.article-sea-route #article-container.article-prose figure.highlight tr,
body.article-sea-route #article-container.article-prose figure.highlight td,
body.article-sea-route #article-container.article-prose figure.highlight .code,
body.article-sea-route #article-container.article-prose figure.highlight .code pre,
body.article-sea-route #article-container.article-prose figure.highlight pre{background:var(--post-code-bg)!important;color:var(--post-code-text)!important}
body.article-sea-route #article-container.article-prose figure.highlight{border:1px solid rgba(170,205,224,.15)!important;box-shadow:none!important}
body.article-sea-route #article-container.article-prose figure.highlight .gutter,
body.article-sea-route #article-container.article-prose figure.highlight .gutter pre{background:var(--post-code-gutter-bg)!important;color:#93aebe!important;border-right:1px solid rgba(170,205,224,.1)!important}
body.article-sea-route #article-container.article-prose figure.highlight .line,
body.article-sea-route #article-container.article-prose figure.highlight .code pre{color:var(--post-code-text)!important}
body.article-sea-route #article-container.article-prose figure.highlight .keyword,
body.article-sea-route #article-container.article-prose figure.highlight .selector-tag{color:#b9dff1!important}
body.article-sea-route #article-container.article-prose figure.highlight .string,
body.article-sea-route #article-container.article-prose figure.highlight .attribute{color:#a9d8d0!important}
body.article-sea-route #article-container.article-prose figure.highlight .number,
body.article-sea-route #article-container.article-prose figure.highlight .literal,
body.article-sea-route #article-container.article-prose figure.highlight .meta{color:#a9c6d8!important}
body.article-sea-route #article-container.article-prose figure.highlight .comment{color:#91aebe!important}

/* Remove the theme's bright h2 accent bar; keep only the small section number. */
body.article-sea-route #article-container.article-prose h2{padding-left:0!important;border-left:0!important}
body.article-sea-route #article-container.article-prose h2:before{color:rgba(175,197,213,.5)!important}
body.article-sea-route #article-container.article-prose .headerlink{color:#9fc7df!important}
body.article-sea-route #article-container.article-prose :not(pre)>code{background:rgba(115,160,195,.1)!important;color:#a9cee8!important}
body.article-sea-route #article-container.article-prose .note{border-left-color:rgba(159,199,223,.35)!important}

.article-comments{max-width:740px;margin-top:80px}
.article-comments #post-comment{background:transparent;box-shadow:none}

/* Right reading progress: a single hairline, a soft dot and a faint percent. */
.article-progress{position:fixed;z-index:5;right:1.5%;top:20%;display:flex;flex-direction:column;align-items:center;gap:14px;pointer-events:none}
.article-progress-track{position:relative;width:1px;height:48vh;min-height:200px;background:rgba(207,223,235,.14)}
.article-progress-fill{position:absolute;left:0;top:0;width:1px;height:0;background:linear-gradient(180deg,rgba(159,196,220,.12),rgba(159,196,220,.6))}
.article-progress-dot{position:absolute;left:50%;top:0;width:6px;height:6px;margin:-3px 0 0 -3px;border-radius:50%;background:#cfe3f0;box-shadow:0 0 9px rgba(150,205,235,.5),0 0 2px rgba(150,205,235,.65)}
.article-progress-percent{font:10px/1 "JetBrains Mono",Consolas,monospace;letter-spacing:.06em;color:rgba(160,181,196,.45)}

.article-mobile-toc-trigger{display:none}

.article-prose .note,.article-prose .note.info,.article-prose .note.warning,.article-prose .note.danger,.article-prose .note.success{margin:28px 0;padding:18px 20px;border:0!important;border-left:1px solid rgba(190,220,240,.32)!important;border-radius:0!important;background:rgba(31,52,68,.3)!important;box-shadow:none!important;color:#c8d6df!important}
.article-prose .note::before,.article-prose .note .note-icon{color:#9fc4dc!important}
.article-prose .note p{margin:.45em 0!important}
.article-prose .note p:first-child{color:#e1edf3!important}

@keyframes article-enter{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}

@media(max-width:900px){
  .article-progress{display:none}
}
@media(max-width:1100px){
  .article-reading-shell{padding-left:16px}
  .article-toc-sidebar{--article-sidebar-x:16px;--article-sidebar-w:210px}
  .article-workspace{margin-left:254px}
  .article-prose pre,.article-prose .highlight{width:min(880px,calc(100vw - 290px))}
}
@media(max-width:760px){
  .article-reading-shell{--article-sidebar-x:0px;padding:0 16px 48px}
  .article-page-bg img{filter:blur(16px) brightness(.52) saturate(.75)}
  .article-reading-dimmer{background:linear-gradient(90deg,rgba(10,19,29,.91),rgba(11,21,32,.83),rgba(13,25,38,.63))}
  .article-topbar{top:18px;right:16px;gap:16px}
  .article-topbar .coast-now-playing>span,.article-topbar .coast-toolbar-rule{display:none}
  .article-topbar .coast-now-playing svg{width:22px;height:22px}
  .article-sea-snow .coast-lightning{left:6%;top:0;width:88%;height:30%}
  .article-toc-sidebar{left:0;top:0;bottom:0;width:min(286px,88vw);height:100dvh;border-radius:0;transform:translateX(-105%);transition:transform .28s ease;backdrop-filter:blur(22px) saturate(125%);-webkit-backdrop-filter:blur(22px) saturate(125%)}
  .article-reading-shell.is-toc-open .article-toc-sidebar{transform:translateX(0)}
  .article-mobile-toc-trigger{position:fixed;z-index:7;display:block;left:16px;top:16px;border:0;background:none;color:#dce8ef;font:11px "JetBrains Mono",Consolas,monospace}
  .article-workspace{max-width:none;margin:0;padding-top:82px}
  .article-header{margin-bottom:40px}
  .article-header>div{padding-right:48px;font-size:10px}
  .article-header h1{font-size:34px}
  .article-header p{font-size:16px}
  .article-prose{max-width:none;font-size:16px;line-height:1.82}
  .article-prose h2{margin-top:52px;font-size:23px}
  .article-prose h3{margin-top:32px;font-size:19px}
  .article-prose pre,.article-prose .highlight{width:calc(100vw - 32px);margin-left:0;border-radius:6px}
  .article-prose table{font-size:14px;display:block;overflow:auto}
  .article-comments{max-width:none}
}
@media(prefers-reduced-motion:reduce){
  .article-header,.article-prose{animation:none}
  .article-sea-snow{opacity:0}
}

.coast-search-dialog{width:min(620px,calc(100vw - 32px));max-height:75svh;margin:12svh auto auto;padding:28px;border:1px solid rgba(214,228,238,.28);border-radius:12px;color:#d9e3ec;background:rgba(30,47,62,.96);box-shadow:0 20px 80px #07121b66;font:14px/1.7 Inter,"Microsoft YaHei",sans-serif}
.coast-search-dialog::backdrop{background:#0c182966;backdrop-filter:blur(6px)}
.coast-search-dialog header{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.coast-search-dialog h2{margin:0;color:inherit;font-size:24px;font-weight:400}.coast-search-dialog button{border:0;background:none;color:inherit;font-size:26px;cursor:pointer}
.coast-search-dialog label{display:block;color:#aebfce;font-size:12px}.coast-search-dialog input{display:block;width:100%;padding:12px 0;border:0;border-bottom:1px solid #a9bfd455;outline:0;background:transparent;color:inherit;font:inherit;appearance:none}.coast-search-dialog input:focus{border-color:#cfdfed}
.coast-search-dialog [role=status]{margin:16px 0;font-size:12px;color:#afc2d1}.coast-search-dialog ul{list-style:none;margin:0;padding:0}.coast-search-dialog li{padding:14px 0;border-top:1px solid #cfdfed22}.coast-search-dialog a{color:#e3edf5;text-decoration:none}.coast-search-dialog a:focus-visible,.coast-search-dialog button:focus-visible{outline:2px solid #cfdfed;outline-offset:4px}.coast-search-dialog li p{margin:5px 0 0;color:#aebfce;font-size:12px}
@media(prefers-reduced-motion:reduce){.coast-search-dialog{scroll-behavior:auto}}

body.nova-gallery-route {
  --nova-gallery-width: 1280px;
  color: var(--nova-gallery-text);
  background: var(--nova-gallery-bg);
}

body.nova-gallery-route #web_bg {
  opacity: 0 !important;
  background: none !important;
}

body.nova-gallery-route #body-wrap {
  background:
    radial-gradient(circle at 4% 42%, rgba(111, 38, 56, .055), transparent 25%),
    radial-gradient(circle at 94% 68%, rgba(91, 108, 123, .04), transparent 28%),
    var(--nova-gallery-bg);
}

body.nova-gallery-route #body-wrap::before {
  position: fixed;
  z-index: 0;
  inset: 0;
  content: "";
  opacity: .018;
  pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 160 160' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}

body.nova-gallery-route #page-header.nova-gallery-nav-header {
  position: fixed;
  z-index: 101;
  top: 0;
  right: 0;
  left: 0;
  height: 60px;
  background: rgba(4, 9, 17, .84) !important;
  box-shadow: 0 1px 0 rgba(255, 255, 255, .035);
  -webkit-backdrop-filter: blur(13px);
  backdrop-filter: blur(13px);
}

body.nova-gallery-route #page-header.nova-gallery-nav-header::before {
  display: none;
}

body.nova-gallery-route #page-header.nova-gallery-nav-header #nav {
  height: 60px;
  background: transparent;
}

body.nova-gallery-route main#content-inner {
  display: block;
  width: 100%;
  max-width: none;
  padding: 0;
}

body.nova-gallery-route #page {
  width: 100%;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

body.nova-gallery-route #article-container {
  padding: 0;
}

.nova-gallery-page,
.nova-gallery-page * {
  box-sizing: border-box;
}

.nova-gallery-page {
  position: relative;
  z-index: 1;
  width: 100%;
  overflow: clip;
  color: var(--nova-gallery-text);
  font-size: 16px;
}

.nova-gallery-hero {
  position: relative;
  min-height: clamp(500px, 61vh, 650px);
  isolation: isolate;
  background: url("/img/guidang.webp") center 48% / cover no-repeat;
}

.nova-gallery-hero::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  content: "";
  background:
    linear-gradient(90deg, rgba(4, 9, 18, .69) 0%, rgba(4, 9, 18, .25) 60%, rgba(4, 9, 18, .13)),
    linear-gradient(180deg, rgba(5, 9, 17, .08) 44%, var(--nova-gallery-bg) 100%);
}

.nova-gallery-hero__inner {
  position: relative;
  width: min(var(--nova-gallery-width), calc(100% - 64px));
  min-height: inherit;
  margin: 0 auto;
}

.nova-gallery-hero__content {
  padding-top: clamp(155px, 22vh, 220px);
  text-align: left;
}

.nova-gallery-eyebrow {
  margin: 0;
  color: #dfa0b3;
  font-size: .65rem;
  font-weight: 600;
  letter-spacing: .3em;
}

.nova-gallery-hero h1 {
  margin: 17px 0 11px;
  color: #f7f2ee;
  font-family: "Noto Serif SC", "Songti SC", serif;
  font-size: clamp(3rem, 5.7vw, 5rem);
  font-weight: 500;
  letter-spacing: .08em;
  line-height: 1.08;
  text-shadow: 0 7px 28px rgba(0, 0, 0, .3);
}

.nova-gallery-hero__desc {
  margin: 0;
  color: rgba(241, 232, 228, .72);
  font-size: clamp(.87rem, 1.4vw, 1rem);
  letter-spacing: .06em;
}

.nova-gallery-explore {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-top: 36px;
  color: #e4a2b5 !important;
  font-size: .61rem;
  letter-spacing: .25em;
  text-decoration: none !important;
}

.nova-gallery-explore span {
  transition: transform .2s ease;
}

.nova-gallery-explore:hover span {
  transform: translateX(4px);
}

.nova-gallery-hero__meta {
  position: absolute;
  right: 0;
  bottom: 26px;
  left: 0;
  display: flex;
  gap: 33px;
  margin: 0;
  color: rgba(226, 216, 214, .55);
  font-size: .64rem;
}

.nova-gallery-hero__meta span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.nova-gallery-hero__meta i {
  color: rgba(220, 177, 188, .7);
  font-size: .68rem;
}

.nova-gallery-hero__meta b {
  color: rgba(244, 234, 231, .78);
  font-weight: 500;
}

.nova-gallery-archive {
  width: min(var(--nova-gallery-width), calc(100% - 64px));
  margin: 0 auto;
  padding: 45px 0 96px;
  scroll-margin-top: 75px;
}

.nova-gallery-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  margin-bottom: 34px;
}

.nova-gallery-collection + .nova-gallery-collection {
  margin-top: clamp(54px, 7vw, 82px);
  padding-top: clamp(38px, 5vw, 56px);
  border-top: 1px solid var(--nova-gallery-line);
}

.nova-gallery-collection__heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 22px;
}

.nova-gallery-collection__heading span {
  display: block;
  margin-bottom: 6px;
  color: var(--nova-gallery-rose);
  font-size: .6rem;
  letter-spacing: .22em;
}

.nova-gallery-collection__heading h2 {
  margin: 0;
  color: var(--nova-gallery-text);
  font: 500 clamp(1.35rem, 2.2vw, 1.75rem)/1.25 "Noto Serif SC", "Songti SC", serif;
  letter-spacing: .06em;
}

.nova-gallery-collection__heading p {
  margin: 0 0 3px;
  color: var(--nova-gallery-faint);
  font-size: .68rem;
  letter-spacing: .08em;
}

.nova-gallery-filter {
  display: flex;
  gap: 36px;
}

.nova-gallery-filter button {
  position: relative;
  padding: 7px 1px 12px;
  border: 0;
  color: var(--nova-gallery-muted);
  background: transparent;
  font-size: .78rem;
  letter-spacing: .05em;
  cursor: pointer;
}

.nova-gallery-filter button::after {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 1px;
  content: "";
  background: var(--nova-gallery-rose);
  opacity: 0;
  transform: scaleX(.4);
  transition: opacity .2s ease, transform .2s ease;
}

.nova-gallery-filter button:hover,
.nova-gallery-filter button.is-active {
  color: var(--nova-gallery-rose);
}

.nova-gallery-filter button.is-active::after {
  opacity: 1;
  transform: scaleX(1);
}

.nova-gallery-sort {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.nova-gallery-sort select {
  padding: 7px 22px 7px 4px;
  border: 0;
  color: var(--nova-gallery-faint);
  background: transparent;
  font-size: .66rem;
  appearance: none;
  cursor: pointer;
}

.nova-gallery-sort select:focus-visible {
  outline: 1px solid var(--nova-gallery-rose);
  outline-offset: 3px;
}

.nova-gallery-sort i {
  position: absolute;
  right: 2px;
  color: var(--nova-gallery-faint);
  font-size: .55rem;
  pointer-events: none;
}

.nova-gallery-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  grid-auto-flow: dense;
  grid-auto-rows: 8px;
  gap: 11px;
  width: 100%;
}

.nova-gallery-item {
  position: relative;
  grid-column: span 4;
  margin: 0 !important;
  min-width: 0;
  grid-row: span var(--gallery-row-span, 28);
}

.nova-gallery-item[hidden] {
  display: none;
}

.nova-gallery-item[data-gallery-ratio="wide"] {
  grid-column: span 6;
}

.nova-gallery-item[data-gallery-ratio="portrait"] {
  grid-column: span 3;
}

.nova-gallery-item[data-gallery-count="1"] {
  grid-column: 1 / -1;
}

.nova-gallery-item[data-gallery-count="2"],
.nova-gallery-item[data-gallery-count="3"],
.nova-gallery-item[data-gallery-count="4"] {
  grid-column: span 6;
}

.nova-gallery-grid--archive .nova-gallery-item {
  grid-column: span 4;
}

.nova-gallery-grid--archive .nova-gallery-item[data-gallery-ratio="wide"] {
  grid-column: span 6;
}

.nova-gallery-item__image {
  position: relative;
  width: 100%;
  height: auto;
  aspect-ratio: var(--gallery-aspect, 1.5);
  overflow: hidden;
  border-radius: 7px;
  background: #101622;
  box-shadow: 0 5px 18px rgba(0, 0, 0, .1);
}

.nova-gallery-item img {
  display: block;
  width: 100%;
  height: 100%;
  margin: 0 !important;
  object-fit: cover;
  transition: transform .55s cubic-bezier(.2, .7, .2, 1);
}

.nova-gallery-item__image::after {
  position: absolute;
  inset: 0;
  content: "";
  background: rgba(4, 8, 15, .11);
  opacity: 0;
  pointer-events: none;
  transition: opacity .25s ease;
}

.nova-gallery-item:hover img {
  transform: scale(1.018);
}

.nova-gallery-item:hover .nova-gallery-item__image::after {
  opacity: 1;
}

.nova-gallery-item__view {
  position: absolute;
  z-index: 2;
  top: 13px;
  right: 13px;
  color: rgba(255, 255, 255, .78);
  font-size: .72rem;
  opacity: 0;
  transform: translateY(3px);
  transition: opacity .2s ease, transform .2s ease;
  pointer-events: none;
}

.nova-gallery-item:hover .nova-gallery-item__view {
  opacity: 1;
  transform: translateY(0);
}

.nova-gallery-item figcaption {
  position: absolute;
  z-index: 2;
  right: 12px;
  bottom: 10px;
  left: 12px;
  display: flex;
  justify-content: space-between;
  color: rgba(255, 255, 255, .68);
  font-size: .57rem;
  letter-spacing: .08em;
  opacity: 0;
  pointer-events: none;
  transition: opacity .2s ease;
}

.nova-gallery-item:hover figcaption {
  opacity: 1;
}

.nova-gallery-item.is-image-error {
  min-height: 160px;
}

.nova-gallery-item.is-image-error::before {
  position: absolute;
  z-index: 3;
  inset: 0;
  display: grid;
  place-items: center;
  content: "影像暂时无法载入";
  color: var(--nova-gallery-faint);
  background: #111723;
  font-size: .68rem;
}

.nova-gallery-empty {
  padding: 70px 0;
  color: var(--nova-gallery-muted);
  text-align: center;
}

body.nova-gallery-route #page > hr.custom-hr {
  display: none;
}

body.nova-gallery-route .nova-gallery-comments {
  width: min(var(--nova-gallery-width), calc(100% - 64px));
  margin: 0 auto 70px;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}

body.nova-gallery-route .nova-gallery-comments .comment-head {
  margin: 0 0 20px;
}

body.nova-gallery-route .nova-gallery-comments .comment-headline {
  display: block;
  text-align: left;
}

body.nova-gallery-route .nova-gallery-comments .comment-headline > span {
  display: block;
  margin-bottom: 7px;
  color: var(--nova-gallery-rose);
  font-size: .6rem;
  letter-spacing: .25em;
}

body.nova-gallery-route .nova-gallery-comments .comment-headline > strong {
  color: var(--nova-gallery-text);
  font-family: "Noto Serif SC", "Songti SC", serif;
  font-size: 1.45rem;
  font-weight: 500;
  letter-spacing: .08em;
}

body.nova-gallery-route .nova-gallery-comments .comment-wrap {
  padding: 0;
}

body.nova-gallery-route .nova-gallery-comments #waline-wrap {
  padding: 16px 18px;
  border: 1px solid rgba(218, 204, 208, .075);
  border-radius: 8px;
  background: rgba(255, 255, 255, .025);
}

body.nova-gallery-route .nova-gallery-comments img {
  max-width: 100%;
  height: auto;
  object-fit: contain;
}

body.nova-gallery-route .nova-gallery-comments .wl-btn.primary {
  border-color: var(--nova-gallery-rose);
  color: #1d1116;
  background: var(--nova-gallery-rose);
}

body.nova-gallery-route footer#footer {
  width: 100%;
  background: var(--nova-gallery-bg-deep) !important;
}

html[data-theme="light"] body.nova-gallery-route #body-wrap {
  background:
    radial-gradient(circle at 4% 42%, rgba(139, 79, 91, .055), transparent 25%),
    radial-gradient(circle at 94% 68%, rgba(104, 116, 126, .05), transparent 28%),
    var(--nova-gallery-bg);
}

html[data-theme="light"] body.nova-gallery-route #page-header.nova-gallery-nav-header {
  background: rgba(7, 11, 19, .84) !important;
}

html[data-theme="light"] .nova-gallery-item__image {
  box-shadow: 0 7px 22px rgba(65, 50, 55, .1);
}

html[data-theme="light"] body.nova-gallery-route .nova-gallery-comments #waline-wrap {
  border-color: rgba(90, 72, 78, .1);
  background: rgba(255, 255, 255, .22);
}

@media (max-width: 1024px) {
  .nova-gallery-hero__inner,
  .nova-gallery-archive,
  body.nova-gallery-route .nova-gallery-comments {
    width: calc(100% - 40px);
  }

  .nova-gallery-grid {
    grid-template-columns: repeat(6, minmax(0, 1fr));
    gap: 10px;
  }

  .nova-gallery-item,
  .nova-gallery-item--slot-1,
  .nova-gallery-item--slot-2,
  .nova-gallery-item--slot-3,
  .nova-gallery-item--slot-4,
  .nova-gallery-item--slot-5,
  .nova-gallery-item--slot-6 {
    grid-column: span 3;
  }

  .nova-gallery-item[data-gallery-ratio="wide"],
  .nova-gallery-item[data-gallery-count="1"] {
    grid-column: span 6;
  }

  .nova-gallery-grid--archive .nova-gallery-item {
    grid-column: span 3;
  }
}

@media (max-width: 768px) {
  body.nova-gallery-route #page-header.nova-gallery-nav-header,
  body.nova-gallery-route #page-header.nova-gallery-nav-header #nav {
    height: 56px;
  }

  .nova-gallery-hero {
    min-height: 480px;
  }

  .nova-gallery-hero__inner,
  .nova-gallery-archive,
  body.nova-gallery-route .nova-gallery-comments {
    width: calc(100% - 28px);
  }

  .nova-gallery-hero__content {
    padding-top: 135px;
  }

  .nova-gallery-hero__meta {
    gap: 0;
    justify-content: space-between;
    font-size: .58rem;
  }

  .nova-gallery-archive {
    padding-top: 32px;
  }

  .nova-gallery-toolbar {
    align-items: flex-end;
    margin-bottom: 24px;
  }

  .nova-gallery-collection__heading p {
    display: none;
  }

  .nova-gallery-filter {
    gap: 24px;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .nova-gallery-filter::-webkit-scrollbar {
    display: none;
  }

  .nova-gallery-sort select {
    width: 25px;
    color: transparent;
  }

  .nova-gallery-grid {
    gap: 8px;
  }

  .nova-gallery-item,
  .nova-gallery-item--slot-1,
  .nova-gallery-item--slot-2,
  .nova-gallery-item--slot-3,
  .nova-gallery-item--slot-4,
  .nova-gallery-item--slot-5,
  .nova-gallery-item--slot-6,
  .nova-gallery-grid[data-visible-remainder] .nova-gallery-item--last-group {
    grid-column: span 3;
  }

}

@media (max-width: 480px) {
  .nova-gallery-hero {
    min-height: 450px;
  }

  .nova-gallery-hero h1 {
    font-size: clamp(2.5rem, 14vw, 3.4rem);
  }

  .nova-gallery-hero__desc {
    max-width: 290px;
    font-size: .81rem;
    line-height: 1.7;
  }

  .nova-gallery-hero__meta span:last-child {
    display: none;
  }

  .nova-gallery-filter {
    gap: 20px;
  }

  .nova-gallery-grid {
    display: block;
  }

  .nova-gallery-item {
    width: 100%;
    margin-bottom: 10px !important;
  }

  .nova-gallery-item__image,
  .nova-gallery-item--slot-1 .nova-gallery-item__image,
  .nova-gallery-item--slot-2 .nova-gallery-item__image,
  .nova-gallery-item--slot-3 .nova-gallery-item__image {
    height: auto;
    aspect-ratio: auto;
  }

  .nova-gallery-item img {
    height: auto;
    object-fit: contain;
  }

  .nova-gallery-item figcaption {
    position: static;
    padding: 6px 1px 2px;
    color: var(--nova-gallery-faint);
    opacity: 1;
  }

  body.nova-gallery-route .nova-gallery-comments #waline-wrap {
    padding: 10px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .nova-gallery-page *,
  .nova-gallery-page *::before,
  .nova-gallery-page *::after {
    transition-duration: .01ms !important;
  }
}

/* Snow coast music composition: sidebar / record / lyrics / playlist. */
body.nova-music-route{background:#182c3d;overflow-x:hidden;color:#d9e3ec}
body.nova-music-route #page-header,body.nova-music-route #web_bg,body.nova-music-route #rightside,body.nova-music-route #footer{display:none!important}
body.nova-music-route #content-inner{width:100%;max-width:none;padding:0;margin:0}
.coast-music-shell{height:auto;min-height:100svh;overflow:clip}
.coast-music-shell .coast-background,.coast-music-shell .coast-shade,.coast-music-shell .coast-snow{position:fixed}
.coast-music-shell .coast-background{object-position:center;filter:saturate(.72) brightness(.8)}
.coast-music-shell .coast-shade{background:rgba(20,38,54,.12)}
.coast-music-shell .coast-sidebar{position:fixed;z-index:5}
.coast-brand-name{margin:0 0 12px;color:#c7cfd6;font:400 40px/1.4 Inter,"Microsoft YaHei",sans-serif}
.coast-music-shell .coast-toolbar{position:fixed;z-index:6;gap:18px;color:rgba(184,196,206,.78)}
.coast-music-shell .coast-toolbar-rule{opacity:.72}
.coast-music-shell .coast-now-playing{gap:8px}
.coast-music-shell .coast-now-playing>span{width:36px;font-size:12px;white-space:nowrap;overflow:hidden}
.coast-music-shell .coast-top-play,.coast-music-shell .coast-snow-toggle,.coast-music-shell .coast-search{opacity:.82}
.coast-music-shell .coast-nav .is-selected{background:rgba(173,199,222,.12);border-radius:8px;margin:-8px -12px;padding:8px 12px}
.music-sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
.nova-music-page{position:relative;margin-left:calc(var(--coast-panel-x) + var(--coast-panel-width) + 3.6vw);padding:11.6vh 1.5vw 6vh 0;display:grid;grid-template-columns:minmax(0,1.16fr) minmax(0,1fr) minmax(0,1.1fr);gap:4.4vw;color:rgba(221,233,243,.85);min-height:100svh}
.sea-player{min-width:0;position:relative;z-index:2}
.sea-player::before{content:"";position:absolute;z-index:-1;left:-5%;right:-2%;top:48%;bottom:6%;background:rgba(8,18,27,.10);filter:blur(28px);pointer-events:none}
.sea-art{position:relative;width:88%;aspect-ratio:1/1.08;margin-bottom:16px}
.nova-music-current-cover{position:relative;z-index:1;width:100%;height:100%;object-fit:cover;border:1px solid rgba(209,229,243,.62);border-radius:10px;filter:saturate(.93) hue-rotate(3deg)}
.sea-vinyl{position:absolute;width:96%;aspect-ratio:1;left:28%;top:4%;border-radius:50%;background:radial-gradient(circle,#788594 0 3%,#1a2733 3.2% 17%,#070b10 17.4% 24%,transparent 24.3%),repeating-radial-gradient(circle,#0d121a 0 2px,#202734 3px,#0a0e15 4px);box-shadow:inset 0 0 0 1px rgba(210,220,230,.22);animation:sea-record 24s linear infinite;animation-play-state:paused}
.is-playing .sea-vinyl{animation-play-state:running}@keyframes sea-record{to{transform:rotate(360deg)}}
.sea-song-heading{display:flex;align-items:center;gap:13px}.sea-song-heading h2{flex:1;margin:0;color:#dce6ee;font:400 clamp(23px,2.25vw,42px)/1.22 Georgia,"Noto Serif SC",serif;letter-spacing:.015em}.sea-song-heading button{font-size:25px!important;color:#bdd0df!important}
.nova-music-current-artist{margin:2px 0 14px;font:400 clamp(13px,1.05vw,19px)/1.5 Georgia,serif;color:#aebfce}
.sea-song-detail{font-size:12px;color:#a7bbc9}
.nova-music-progress-input{display:block;width:100%;height:3px;appearance:none;background:linear-gradient(90deg,#c7e3f8 var(--music-progress,0%),rgba(191,215,233,.22) var(--music-progress,0%));border:0;border-radius:2px;cursor:pointer}
.nova-music-progress-input::-webkit-slider-thumb{appearance:none;width:10px;height:10px;border-radius:50%;background:#d0e8f8}
.nova-music-time{display:flex;justify-content:space-between;font-size:12px;margin:8px 0 4px;color:#d0dee9}
.nova-music-controls{display:flex;justify-content:space-between;align-items:center;margin:7px 0 2px}.nova-music-controls button{width:38px;height:38px;font-size:24px;color:#ccdfed}.nova-music-controls .nova-music-toggle{width:72px;height:72px;border:1px solid rgba(198,223,241,.88);border-radius:50%;font-size:25px}.nova-music-controls [aria-pressed=true]{color:#f0f8ff}
.sea-waveform{width:100%;height:54px;display:block;margin-top:0;opacity:.78}
.sea-volume{display:flex;align-items:center;gap:10px;font-size:11px;color:#a4b7c6;margin-top:7px}.sea-volume input{width:85px;accent-color:#b4cfdf;height:2px}.nova-music-count{font-size:11px;color:#95adbf;margin-top:8px}
.sea-lyrics{position:relative;isolation:isolate;height:69vh;min-width:0;overflow:auto;scrollbar-width:none;padding:24px 0;mask-image:linear-gradient(transparent,#000 6%,#000 92%,transparent)}
.sea-lyrics::before{content:"";position:fixed;z-index:-1;width:25vw;height:62vh;margin:-1vh 0 0 -2vw;background:rgba(7,17,26,.11);filter:blur(34px);pointer-events:none}
.sea-lyrics-lines p{position:relative;margin:0 0 28px;padding:0 0 0 20px;color:rgba(197,214,228,.54);font:400 clamp(14px,1.12vw,21px)/1.58 Georgia,"Noto Serif SC",serif;transition:color .25s,font-size .25s}
.sea-lyrics-lines p.is-active{color:rgba(232,244,252,.98);font-size:clamp(15.12px,1.2096vw,22.68px)}.sea-lyrics-lines p.is-active:before{content:"";position:absolute;left:0;top:4px;bottom:4px;width:2px;background:rgba(215,236,250,.9)}
.sea-lyrics-empty{font-size:14px!important;padding-top:17vh!important;color:#a3b7c9!important}
.sea-playlist{align-self:start;min-width:0;min-height:0;max-height:78vh;border:1px solid rgba(190,213,232,.22);border-radius:11px;background:rgba(35,55,73,.35);backdrop-filter:blur(18px);padding:16px 9px;overflow:auto;scrollbar-width:thin}
.sea-playlist:has(.sea-track:nth-child(7)){min-height:68vh}
.sea-playlist-tabs{display:flex;justify-content:space-around;gap:12px;padding:0 12px 16px;border-bottom:1px solid rgba(181,205,224,.16)}.sea-playlist-tabs button{font-size:13px;position:relative;color:#a4b6c8}.sea-playlist-tabs [aria-selected=true]{color:#e7eff6}.sea-playlist-tabs [aria-selected=true]:after{content:"";position:absolute;bottom:-16px;left:0;right:0;height:2px;background:#b6d7ef}
.sea-track{display:grid;grid-template-columns:20px 44px minmax(0,1fr) 38px 18px;gap:9px;align-items:center;padding:10px 8px;border-radius:7px;margin-top:7px}.sea-track.is-current{background:rgba(181,205,226,.075)}.sea-track button{display:contents;color:inherit}.sea-track .sea-track-more{display:block;font-size:16px;align-self:center}.sea-track img{width:44px;height:48px;object-fit:cover;border-radius:4px;filter:saturate(.93) hue-rotate(3deg)}.sea-track-number,.sea-track-time{color:#9eb4c7;font-size:12px}.sea-track-name{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:400 15px/1.42 Georgia,"Noto Serif SC",serif}.sea-track-artist{display:block;margin-top:1px;color:rgba(158,180,199,.82);font-size:11px}.sea-track [aria-current=true] .sea-track-name{color:#e3f1fb}.sea-playlist-empty{padding:26px 15px;font-size:13px;color:#a5bbc9}
@media(min-width:1800px){.nova-music-page{gap:4.6vw}}
@media(max-width:1200px) and (min-width:901px){.nova-music-page{gap:2.5vw;grid-template-columns:1.1fr .85fr 1fr}.sea-track{grid-template-columns:18px 36px minmax(0,1fr) 20px;gap:7px}.sea-track img{width:36px;height:40px}.sea-track-time{display:none}.sea-song-heading h2{font-size:25px}}
@media(max-width:900px){.coast-music-shell .coast-sidebar{position:relative}.nova-music-page{margin:0;padding:40px 24px 130px;grid-template-columns:1fr 1fr;gap:35px}.sea-lyrics{height:470px}.sea-playlist{grid-column:1/-1;min-height:220px}.sea-art{width:82%}.coast-music-shell .coast-toolbar{position:absolute}}
@media(max-width:560px){.nova-music-page{grid-template-columns:1fr;padding:30px 24px 140px}.sea-player{max-width:380px;margin:0 auto;width:100%}.sea-lyrics{height:260px}.sea-playlist{grid-column:auto;max-height:480px}.sea-art{width:82%;margin-bottom:24px}.sea-song-heading h2{font-size:28px}.sea-lyrics-empty{padding-top:50px!important}}
@media(prefers-reduced-motion:reduce){.sea-vinyl{animation:none}.sea-lyrics-lines p{transition:none}}
.sea-lyrics-lines .sea-lyrics-status{font:11px/1.6 Inter,sans-serif;color:#819aac;margin-bottom:25px}
.sea-track{text-align:left}.sea-track button{text-align:left}.sea-art{aspect-ratio:1}.coast-music-shell .nova-music-toggle{font-size:25px!important}.sea-player button:focus-visible,.sea-playlist button:focus-visible{outline:1px solid #c5deef;outline-offset:5px}
.coast-home.coast-music-shell{height:auto;min-height:100svh}
.coast-music-shell .coast-music-art{margin-bottom:6px}
.coast-music-shell .coast-music-art img{filter:saturate(.94) hue-rotate(2deg)}
.coast-music-shell .coast-music-info{gap:6px;line-height:16px}
.coast-music-shell [data-music-title]{color:rgba(226,237,245,.92)}
.coast-music-shell [data-music-artist]{color:rgba(166,184,198,.68);font-size:10px}
.coast-music-shell .coast-social svg{opacity:.68}
@media(max-width:900px){.coast-music-shell .coast-sidebar{top:auto;left:auto;right:auto;bottom:auto;margin:74px 16px 0;width:auto}.coast-music-shell .coast-brand-name{font-size:32px}.coast-music-shell .coast-sidebar-bottom{z-index:8}.coast-music-shell .coast-nav{gap:8px}.coast-music-shell .coast-nav a{font-size:12px;gap:4px}}
@media(min-width:901px){.nova-music-page{margin-left:calc(var(--coast-panel-x) + max(var(--coast-panel-width),180px) + 3.6vw)}}

body.nova-category-route{
  --nova-category-space-1:6px;
  --nova-category-space-2:10px;
  --nova-category-space-3:16px;
  --nova-category-space-4:22px;
  color:var(--nova-category-text-primary);
  background:var(--nova-category-page-bg)
}
body.nova-category-route #body-wrap{
  overflow:clip;
  background:
    radial-gradient(circle at 82% 8%,rgba(189,90,133,.075),transparent 30%),
    radial-gradient(circle at 16% 26%,rgba(104,124,143,.05),transparent 34%),
    linear-gradient(180deg,var(--nova-category-page-bg) 0%,var(--nova-category-page-bg-soft) 52%,#070c17 100%)
}
body.nova-category-route #page-header.nova-category-hero{
  position:relative;
  height:clamp(390px,41vh,420px);
  overflow:hidden;
  background-position:center 48%!important;
  background-size:cover!important;
  background-repeat:no-repeat!important
}
body.nova-category-route #page-header.nova-category-hero::before{
  content:"";
  position:absolute;
  z-index:0;
  inset:0;
  background:
    linear-gradient(90deg,rgba(7,12,25,.46),rgba(7,12,25,.1) 60%,rgba(7,12,25,.24)),
    linear-gradient(180deg,rgba(5,10,22,.14),rgba(8,14,28,.05) 64%,rgba(8,14,27,.54))
}
body.nova-category-route #page-header.nova-category-hero::after{
  content:"";
  position:absolute;
  z-index:1;
  inset:auto 0 0;
  height:34%;
  pointer-events:none;
  background:linear-gradient(180deg,transparent,var(--nova-category-page-bg))
}
body.nova-category-route #page-header.nova-category-hero #nav{z-index:4;background:transparent;box-shadow:none}
.nova-category-hero-content{
  position:absolute!important;
  z-index:2;
  top:52%!important;
  right:20px;
  left:20px;
  display:flex;
  align-items:center;
  flex-direction:column;
  transform:translateY(calc(-50% + 8px))!important;
  color:#f7eff4;
  text-align:center
}
.nova-category-eyebrow{margin:0 0 15px;color:#e18ca8;font-size:11px;letter-spacing:.28em}
.nova-category-hero-content #site-title{margin:0;color:#f6e9ef;font:500 clamp(64px,6.7vw,92px)/1.05 "Noto Serif SC","Songti SC",serif;letter-spacing:.16em;text-shadow:0 10px 32px rgba(0,0,0,.26)}
.nova-category-subtitle{margin:18px 0 0;color:rgba(246,238,243,.78);font-size:15px;line-height:1.9;letter-spacing:.08em}
.nova-category-scroll-hint{display:inline-flex;align-items:center;gap:12px;margin-top:24px;color:rgba(244,228,237,.6);font-size:10px;letter-spacing:.2em}
.nova-category-scroll-hint::before,.nova-category-scroll-hint::after{content:"";width:42px;height:1px;background:linear-gradient(90deg,transparent,rgba(220,124,155,.7))}
.nova-category-scroll-hint::after{transform:rotate(180deg)}
body.nova-category-route main.nova-category-content{
  position:relative;
  z-index:3;
  display:block;
  width:100%;
  max-width:none;
  margin:0;
  padding:0 0 clamp(64px,7vw,92px)
}
body.nova-category-route main.nova-category-content::before{
  content:"";
  position:absolute;
  z-index:-1;
  inset:0;
  pointer-events:none;
  background:url("/img/guidang.webp") center top/cover no-repeat;
  opacity:.028;
  filter:blur(34px) saturate(.6);
  mask-image:linear-gradient(180deg,#000,transparent 44%);
  -webkit-mask-image:linear-gradient(180deg,#000,transparent 44%)
}
.nova-category-summary{
  position:relative;
  z-index:5;
  display:grid;
  width:min(1320px,calc(100% - 64px));
  margin:-52px auto 0;
  grid-template-columns:repeat(4,minmax(0,1fr));
  border:1px solid var(--nova-category-border);
  border-radius:20px;
  background:linear-gradient(145deg,rgba(15,23,43,.9),rgba(9,16,31,.82));
  box-shadow:0 24px 65px rgba(0,0,0,.24);
  backdrop-filter:blur(20px);
  -webkit-backdrop-filter:blur(20px)
}
.nova-category-summary>div{position:relative;display:flex;min-width:0;min-height:88px;padding:18px 24px;align-items:flex-start;justify-content:center;flex-direction:column;gap:3px}
.nova-category-summary>div+div::before{content:"";position:absolute;top:20px;bottom:20px;left:0;width:1px;background:var(--nova-category-border)}
.nova-category-summary strong{overflow:hidden;color:var(--nova-category-text-primary);font:500 24px/1.1 Georgia,"Times New Roman",serif;text-overflow:ellipsis;white-space:nowrap}
.nova-category-summary span{color:var(--nova-category-accent);font-size:11px;line-height:1.4;letter-spacing:.14em}
.nova-category-summary small{color:var(--nova-category-text-muted);font-size:12px;line-height:1.5}
.nova-category-layout{
  display:grid;
  width:min(1320px,calc(100% - 64px));
  margin:40px auto 0;
  grid-template-columns:minmax(0,1.72fr) minmax(300px,.82fr);
  align-items:start;
  gap:clamp(26px,3vw,38px)
}
.nova-category-main,.nova-category-side-card{
  min-width:0;
  border:1px solid var(--nova-category-border);
  background:linear-gradient(145deg,rgba(13,20,38,.84),rgba(9,15,29,.76));
  box-shadow:0 22px 60px rgba(0,0,0,.2);
  backdrop-filter:blur(20px);
  -webkit-backdrop-filter:blur(20px)
}
.nova-category-main{padding:28px;border:1px solid rgba(224,194,210,.09);border-radius:24px;background:linear-gradient(145deg,rgba(10,16,31,.82),rgba(8,13,26,.74));box-shadow:0 24px 70px rgba(0,0,0,.22)}
.nova-category-main-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:24px;padding-bottom:20px;border-bottom:1px solid var(--nova-category-border)}
.nova-category-main-heading span,.nova-category-side-card header span{color:var(--nova-category-accent);font-size:11px;letter-spacing:.17em}
.nova-category-main-heading h2,.nova-category-side-card h2{margin:4px 0 0;color:var(--nova-category-text-primary);font:500 21px/1.35 "Noto Serif SC","Songti SC",serif}
.nova-category-main-heading p{margin:6px 0 0;color:var(--nova-category-text-muted);font-size:14px}
.nova-category-main-heading>b{color:var(--nova-category-text-muted);font-size:10px;letter-spacing:.13em;white-space:nowrap}
.nova-category-card-list{display:grid;align-items:start;grid-auto-rows:auto;gap:24px}
.nova-category-card{
  display:grid;
  width:100%;
  height:auto;
  min-height:230px;
  align-self:start;
  overflow:hidden;
  grid-template-columns:minmax(210px,30%) minmax(0,1fr);
  border:1px solid rgba(224,194,210,.12);
  border-radius:20px;
  background:linear-gradient(145deg,rgba(16,23,43,.78),rgba(12,19,36,.7));
  box-shadow:0 10px 28px rgba(0,0,0,.14);
  transition:transform .22s ease,border-color .22s ease,box-shadow .22s ease
}
.nova-category-card:hover{transform:translateY(-2px);border-color:rgba(205,105,143,.25);box-shadow:0 16px 36px rgba(0,0,0,.2)}
.nova-category-card-cover{position:relative;display:block;width:100%;min-width:210px;min-height:230px;overflow:hidden;background:#0c1323}
.nova-category-card-cover::after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,12,27,.02),rgba(8,12,27,.32))}
.nova-category-card-cover img{position:absolute;inset:0;width:100%;height:100%;min-height:0;object-fit:cover;filter:brightness(.74) saturate(.82) contrast(1.04);transition:transform .35s ease,filter .35s ease}
.nova-category-card:hover .nova-category-card-cover img{transform:scale(1.025);filter:brightness(.78) saturate(.86) contrast(1.04)}
.nova-category-card-cover>span{position:absolute;z-index:1;right:16px;bottom:14px;padding:5px 10px;border:1px solid rgba(255,255,255,.12);border-radius:999px;color:rgba(255,255,255,.76);background:rgba(5,10,20,.52);font-size:9px;letter-spacing:.12em;backdrop-filter:blur(8px)}
.nova-category-card-body{display:flex;min-width:0;height:auto;padding:22px 24px 20px;flex:1;flex-direction:column}
.nova-category-card-heading{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:start;gap:14px}
.nova-category-card-index{color:var(--nova-category-accent);font:500 13px/1.8 Georgia,serif}
.nova-category-card-heading h2{margin:0;font:500 23px/1.35 "Noto Serif SC","Songti SC",serif}
.nova-category-card-heading h2 a{color:var(--nova-category-text-primary)}
.nova-category-card-heading p{margin:5px 0 0;color:var(--nova-category-text-secondary);font-size:14px;line-height:1.65}
.nova-category-card-arrow{display:grid;width:34px;height:34px;place-items:center;border:1px solid var(--nova-category-border);border-radius:50%;color:var(--nova-category-text-secondary);background:rgba(255,255,255,.035);transition:transform .22s ease,color .22s ease,border-color .22s ease}
.nova-category-card:hover .nova-category-card-arrow{transform:translateX(4px);border-color:rgba(205,105,143,.25);color:var(--nova-category-accent)}
.nova-category-card-children{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0 2px}
.nova-category-child-link{display:inline-flex;align-items:center;gap:8px;padding:5px 9px;border:1px solid var(--nova-category-border);border-radius:999px;color:var(--nova-category-text-secondary);background:rgba(192,107,140,.06);font-size:12px}
.nova-category-child-link span{color:var(--nova-category-accent)}
.nova-category-card-posts{display:grid;margin-top:12px;border-top:1px solid var(--nova-category-border)}
.nova-category-post-link{display:grid;min-width:0;padding:9px 2px;grid-template-columns:minmax(0,1fr) auto;gap:16px;border-bottom:1px solid var(--nova-category-border);color:var(--nova-category-text-secondary);font-size:13px}
.nova-category-post-link>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.nova-category-post-link time{color:var(--nova-category-text-muted);font-size:12px;white-space:nowrap}
.nova-category-post-link:hover{color:var(--nova-category-text-primary)}
.nova-category-empty{margin:14px 0;color:var(--nova-category-text-muted);font-size:11px}
.nova-category-card-action{display:inline-flex;align-items:center;align-self:flex-start;gap:6px;margin-top:auto;padding-top:13px;color:var(--nova-category-accent);font-size:13px;letter-spacing:.04em;transition:gap .22s ease,color .22s ease}
.nova-category-card-action span{display:inline-block}
.nova-category-card-action:hover{gap:10px;color:#df86a3}
.nova-category-sidebar{display:flex;height:auto;min-width:0;align-self:start;flex-direction:column;gap:20px}
.nova-category-side-card{padding:var(--nova-category-space-4);border-radius:20px}
.nova-category-side-card header{margin-bottom:var(--nova-category-space-3);padding-bottom:var(--nova-category-space-3);border-bottom:1px solid var(--nova-category-border)}
.nova-category-side-card header span{font-size:11px;line-height:1.4;letter-spacing:.13em}
.nova-category-side-card h2{font-size:18px;line-height:1.45}
.nova-category-focus ul{display:grid;margin:0;padding:0;gap:var(--nova-category-space-2);list-style:none}
.nova-category-focus li{position:relative;padding:9px 12px 9px 28px;border-radius:10px;color:var(--nova-category-text-secondary);background:rgba(192,107,140,.055);font-size:13px;line-height:1.65}
.nova-category-focus li::before{content:"";position:absolute;top:50%;left:13px;width:6px;height:6px;border:1px solid var(--nova-category-accent);transform:translateY(-50%) rotate(45deg)}
.nova-category-index nav{display:grid}
.nova-category-index-link{display:grid;margin:2px 0;padding:10px 12px;grid-template-columns:28px minmax(0,1fr) auto;align-items:center;gap:10px;border-radius:10px;color:var(--nova-category-text-secondary);font-size:14px;transition:transform .2s ease,background-color .2s ease,color .2s ease}
.nova-category-index-link span{color:var(--nova-category-accent);font:500 10px Georgia,serif}
.nova-category-index-link strong{overflow:hidden;font-weight:500;text-overflow:ellipsis;white-space:nowrap}
.nova-category-index-link b{color:var(--nova-category-text-muted);font-size:12px;font-weight:400}
.nova-category-index-link:hover{transform:translateX(3px);color:var(--nova-category-accent);background:rgba(197,99,137,.08)}
.nova-category-tags>div{display:flex;flex-wrap:wrap;gap:var(--nova-category-space-2)}
.nova-category-tag-link{display:inline-flex;align-items:center;gap:6px;padding:7px 11px;border:1px solid var(--nova-category-border);border-radius:999px;color:var(--nova-category-text-secondary);background:rgba(255,255,255,.035);font-size:12px}
.nova-category-tag-link span{color:var(--nova-category-text-muted);font-size:10px}
.nova-category-tag-link:hover{border-color:rgba(206,113,143,.25);color:var(--nova-category-accent)}
body.nova-category-route footer#footer{margin:0;border-top:1px solid rgba(199,97,132,.14);background:linear-gradient(180deg,rgba(12,20,39,.88),#0b162a)}
html[data-theme="light"] body.nova-category-route #body-wrap{background:radial-gradient(circle at 82% 8%,rgba(189,96,125,.06),transparent 30%),radial-gradient(circle at 16% 26%,rgba(112,130,144,.045),transparent 34%),linear-gradient(180deg,#eeebf1,#e7e5ec)}
html[data-theme="light"] body.nova-category-route #page-header.nova-category-hero::after{background:linear-gradient(180deg,rgba(8,13,27,.03) 0%,rgba(8,13,27,.02) 62%,rgba(105,98,122,.09) 80%,rgba(211,207,218,.32) 92%,var(--nova-category-page-bg) 100%)}
html[data-theme="light"] .nova-category-main{border-color:rgba(75,62,83,.09);background:linear-gradient(145deg,rgba(255,254,255,.82),rgba(244,241,247,.74));box-shadow:0 22px 60px rgba(53,43,62,.1)}
html[data-theme="light"] .nova-category-side-card,html[data-theme="light"] .nova-category-summary{border-color:rgba(255,255,255,.56);background:linear-gradient(145deg,rgba(255,254,255,.84),rgba(244,241,247,.74));box-shadow:0 22px 60px rgba(53,43,62,.1)}
html[data-theme="light"] .nova-category-card{border-color:rgba(75,62,83,.1);background:linear-gradient(145deg,rgba(255,255,255,.84),rgba(246,243,248,.78));box-shadow:0 12px 32px rgba(53,43,62,.08)}
html[data-theme="light"] .nova-category-card:hover{border-color:rgba(189,96,125,.22);box-shadow:0 16px 38px rgba(53,43,62,.11)}
html[data-theme="light"] .nova-category-focus li,html[data-theme="light"] .nova-category-child-link,html[data-theme="light"] .nova-category-tag-link{background:rgba(179,89,120,.055)}
html[data-theme="light"] body.nova-category-route footer#footer{border-top-color:rgba(189,96,125,.14);background:linear-gradient(180deg,rgba(224,221,230,.92),#d0d2dd);color:#514c59}
@media(min-width:1101px) and (min-height:820px){
  .nova-category-sidebar{position:sticky;top:88px}
}
@media(max-width:1180px){
  .nova-category-summary,.nova-category-layout{width:calc(100% - 40px)}
  .nova-category-layout{grid-template-columns:minmax(0,1fr) minmax(280px,.65fr);gap:clamp(26px,3vw,34px)}
  .nova-category-main{padding:22px}
  .nova-category-card{grid-template-columns:minmax(175px,30%) minmax(0,1fr)}
}
@media(max-width:1024px){
  body.nova-category-route #page-header.nova-category-hero{height:360px}
  .nova-category-summary{width:calc(100% - 28px);margin-top:-30px;grid-template-columns:1fr 1fr}
  .nova-category-summary>div:nth-child(3)::before{display:none}
  .nova-category-summary>div:nth-child(n+3){border-top:1px solid var(--nova-category-border)}
  .nova-category-layout{display:block;width:calc(100% - 28px);margin-top:28px}
  .nova-category-sidebar{position:static;margin-top:22px}
}
@media(max-width:560px){
  .nova-category-hero-content #site-title{font-size:52px}
  .nova-category-subtitle{font-size:13px}
  .nova-category-summary>div{padding:15px}
  .nova-category-summary strong{font-size:18px}
  .nova-category-main{padding:14px;border-radius:18px}
  .nova-category-main-heading{align-items:flex-start;flex-direction:column;gap:8px}
  .nova-category-card{display:block;min-height:0;border-radius:16px}
  .nova-category-card-cover{min-height:178px;aspect-ratio:16/9}
  .nova-category-card-cover img{min-height:178px}
  .nova-category-card-body{padding:18px 16px}
  .nova-category-card-heading{gap:9px}
  .nova-category-card-heading h2{font-size:19px}
  .nova-category-post-link{gap:8px}
}
@media(max-width:390px){
  .nova-category-summary{grid-template-columns:1fr}
  .nova-category-summary>div+div::before{top:0;right:15px;bottom:auto;left:15px;width:auto;height:1px}
  .nova-category-summary>div:nth-child(3)::before{display:block}
  .nova-category-summary>div:nth-child(n+3){border-top:0}
  .nova-category-card-heading p{font-size:10px}
  .nova-category-post-link{grid-template-columns:1fr}
}
@media(prefers-reduced-motion:reduce){
  .nova-category-card,.nova-category-card-cover img,.nova-category-card-arrow,.nova-category-card-action,.nova-category-index-link{transition:none!important}
  .nova-category-card:hover,.nova-category-card:hover .nova-category-card-cover img,.nova-category-card:hover .nova-category-card-arrow,.nova-category-index-link:hover{transform:none!important}
}

.prince-egg {
  --prince-standing-left: 16px;
  --prince-standing-bottom: 92px;
  position: fixed;
  z-index: 9000;
  left: 0;
  bottom: 158px;
  width: 112px;
  height: 142px;
  visibility: visible;
  opacity: 1;
  pointer-events: auto;
  transform: translate3d(0, 0, 0);
  transition: opacity .38s ease, visibility 0s linear 0s;
  contain: layout paint;
}

.prince-egg__character {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
  padding: 0;
  background: transparent;
  cursor: pointer;
  outline: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.prince-egg__image-stage {
  position: absolute;
  inset: 0;
  display: block;
  overflow: hidden;
  filter: drop-shadow(4px 8px 12px rgba(0, 0, 0, .2));
}

.prince-egg__peek,
.prince-egg__standing {
  position: absolute;
  display: block;
  max-width: none;
  height: auto;
  opacity: 0;
  pointer-events: none;
  user-select: none;
  -webkit-user-select: none;
  transition: opacity .12s ease;
}

.prince-egg__peek {
  top: -18px;
  left: -10px;
  width: 112px;
}

.prince-egg__standing {
  top: -20px;
  left: 0;
  width: 106px;
}

.prince-egg.is-hidden {
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  transition: opacity .3s ease, visibility 0s linear .3s;
}

.prince-egg.is-hidden .prince-egg__character {
  transform: translate3d(-18px, 5px, 0);
}

.prince-egg.is-peeking .prince-egg__peek,
.prince-egg.is-preparing .prince-egg__peek {
  opacity: .84;
}

.prince-egg.is-peeking .prince-egg__character {
  animation: prince-peek 3.5s ease-in-out infinite;
}

.prince-egg.is-preparing .prince-egg__character {
  animation: prince-prepare .14s ease-in forwards;
}

.prince-egg.is-jumping,
.prince-egg.is-standing,
.prince-egg.is-returning,
.prince-egg.is-quote-open {
  left: var(--prince-standing-left);
  bottom: var(--prince-standing-bottom);
  width: 106px;
  height: 142px;
  transition: none;
}

.prince-egg.is-jumping .prince-egg__standing,
.prince-egg.is-standing .prince-egg__standing,
.prince-egg.is-returning .prince-egg__standing,
.prince-egg.is-quote-open .prince-egg__standing {
  opacity: .9;
}

.prince-egg.is-jumping .prince-egg__character {
  animation: prince-jump .72s cubic-bezier(.2, .78, .24, 1) both;
}

.prince-egg.is-standing .prince-egg__character,
.prince-egg.is-quote-open .prince-egg__character {
  transform: translate3d(0, 0, 0);
  animation: prince-standing 3.4s ease-in-out infinite;
}

.prince-egg.is-returning .prince-egg__character {
  animation: prince-return .65s cubic-bezier(.38, .02, .42, 1) both;
  pointer-events: none;
}

.prince-quote-popover {
  position: fixed;
  z-index: 9500;
  top: 0;
  left: 0;
  width: clamp(320px, 25vw, 390px);
  max-width: calc(100vw - 40px);
  height: auto;
  padding: 20px 22px 18px;
  border: 1px solid rgba(195, 132, 158, .28);
  border-radius: 15px;
  color: inherit;
  background:
    radial-gradient(circle at 28% 0%, rgba(222, 190, 207, .08), transparent 48%),
    linear-gradient(145deg, rgba(17, 24, 38, .97), rgba(24, 20, 32, .96));
  box-shadow: 0 15px 38px rgba(0, 0, 0, .34), 0 0 24px rgba(143, 84, 110, .07);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  user-select: none;
  -webkit-user-select: none;
  transform: translateY(7px) scale(.98);
  transform-origin: left bottom;
  transition:
    opacity .38s ease,
    transform .38s cubic-bezier(.22, .72, .26, 1),
    visibility 0s linear .38s;
}

.prince-quote-popover.is-visible,
.prince-quote-popover.is-closing,
.prince-quote-popover.is-measuring {
  visibility: visible;
}

.prince-quote-popover.is-visible {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0) scale(1);
  transition-delay: 0s;
}

.prince-quote-popover.is-closing {
  opacity: 0;
  pointer-events: none;
  transform: translateY(5px) scale(1);
  transition-duration: .28s;
}

.prince-quote-popover.is-left {
  transform-origin: right bottom;
}

.prince-quote-popover__rose {
  display: block;
  width: 17px;
  height: 25px;
  margin: 0 auto 11px;
  color: rgba(207, 139, 166, .84);
}

.prince-quote-popover__rose svg {
  display: block;
  width: 100%;
  height: 100%;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.4;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.prince-quote-popover__zh,
.prince-quote-popover__en,
.prince-quote-popover__source {
  filter: none;
  backdrop-filter: none;
}

.prince-quote-popover__zh {
  margin: 0;
  color: rgba(247, 242, 246, .96);
  font-family: "Noto Serif SC", "Source Han Serif SC", "Songti SC", "STSong", serif;
  font-size: clamp(17px, 1.12vw, 20px);
  font-weight: 600;
  line-height: 1.68;
  letter-spacing: .035em;
  text-align: left;
  white-space: pre-line;
  text-shadow: 0 1px 3px rgba(0, 0, 0, .35);
}

.prince-quote-popover__en {
  margin: 13px 0 0;
  color: rgba(222, 213, 223, .46);
  font-family: "JetBrains Mono", "Fira Code", "SFMono-Regular", Consolas, "Liberation Mono", "Inter", sans-serif;
  font-size: 11px;
  font-style: italic;
  line-height: 1.68;
  letter-spacing: .012em;
  text-align: left;
}

.prince-quote-popover__source {
  margin: 14px 0 0;
  color: rgba(214, 142, 171, .8);
  font-family: "Inter", "Noto Sans SC", "Microsoft YaHei", sans-serif;
  font-size: 10.5px;
  font-style: normal;
  line-height: 1.5;
  letter-spacing: .035em;
  text-align: right;
}

.prince-quote-popover__arrow {
  position: absolute;
  bottom: 18px;
  width: 9px;
  height: 9px;
  background: rgba(22, 21, 33, .97);
  transform: rotate(45deg);
}

.prince-quote-popover.is-right .prince-quote-popover__arrow {
  left: -9px;
  border-bottom: 1px solid rgba(195, 132, 158, .28);
  border-left: 1px solid rgba(195, 132, 158, .28);
}

.prince-quote-popover.is-left .prince-quote-popover__arrow {
  right: -5px;
  border-top: 1px solid rgba(195, 132, 158, .28);
  border-right: 1px solid rgba(195, 132, 158, .28);
}

[data-theme="light"] .prince-quote-popover {
  color: rgba(65, 56, 68, .96);
  background:
    radial-gradient(circle at 28% 0%, rgba(224, 188, 205, .2), transparent 48%),
    linear-gradient(145deg, rgba(255, 251, 252, .97), rgba(246, 239, 243, .97));
  border-color: rgba(207, 181, 193, .56);
  box-shadow: 0 10px 28px rgba(112, 82, 100, .1), 0 2px 8px rgba(112, 82, 100, .05);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

[data-theme="light"] .prince-quote-popover__zh {
  color: rgba(65, 56, 68, .96);
  text-shadow: 0 1px 2px rgba(112, 82, 100, .08);
}

[data-theme="light"] .prince-quote-popover__en {
  color: rgba(72, 65, 76, .46);
}

[data-theme="light"] .prince-quote-popover__source {
  color: rgba(182, 113, 143, .9);
}

[data-theme="light"] .prince-quote-popover__rose {
  color: rgba(185, 116, 146, .88);
}

[data-theme="light"] .prince-quote-popover__arrow {
  background: rgba(249, 244, 247, .98);
}

[data-theme="light"] .prince-quote-popover.is-right .prince-quote-popover__arrow {
  border-bottom-color: rgba(207, 181, 193, .56);
  border-left-color: rgba(207, 181, 193, .56);
}

[data-theme="light"] .prince-quote-popover.is-left .prince-quote-popover__arrow {
  border-top-color: rgba(207, 181, 193, .56);
  border-right-color: rgba(207, 181, 193, .56);
}

@keyframes prince-peek {
  0%, 100% { transform: translate3d(-3px, 1px, 0) rotate(-.7deg); }
  48% { transform: translate3d(2px, -2px, 0) rotate(.8deg); }
  72% { transform: translate3d(0, -1px, 0) rotate(0); }
}

@keyframes prince-prepare {
  to { transform: translate3d(-8px, 2px, 0) rotate(-2deg) scale(.98); }
}

@keyframes prince-jump {
  0% { transform: translate3d(-32px, 66px, 0) rotate(-3deg) scale(.96); }
  42% { transform: translate3d(5px, -34px, 0) rotate(2.5deg) scale(1.02); }
  70% { transform: translate3d(-2px, 6px, 0) rotate(-1deg) scale(.99); }
  86% { transform: translate3d(1px, -3px, 0) rotate(.4deg); }
  100% { transform: translate3d(0, 0, 0) rotate(0) scale(1); }
}

@keyframes prince-standing {
  0%, 100% { transform: translate3d(0, 0, 0); }
  50% { transform: translate3d(0, -2px, 0); }
}

@keyframes prince-return {
  0% { transform: translate3d(0, 0, 0) rotate(0); opacity: 1; }
  35% { transform: translate3d(-8px, -3px, 0) rotate(-3deg); opacity: .9; }
  72% { transform: translate3d(-45px, -5px, 0) rotate(-4deg); opacity: .55; }
  100% { transform: translate3d(-70px, -2px, 0) rotate(-2deg); opacity: 0; }
}

@media (max-width: 767px) {
  .prince-egg,
  .prince-quote-popover {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .prince-egg__character,
  .prince-quote-popover {
    animation: none !important;
    transition-duration: .01ms !important;
  }

  .prince-quote-popover.is-visible {
    transform: none;
  }
}

@font-face {
  font-family: "Cormorant Garamond";
  font-style: normal;
  font-weight: 500 600;
  font-display: swap;
  src: url("../fonts/cormorant-garamond-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

@font-face {
  font-family: "Inter";
  font-style: normal;
  font-weight: 400 600;
  font-display: swap;
  src: url("../fonts/inter-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

.nova-homepage,.nova-homepage *{box-sizing:border-box}
.nova-homepage a{color:inherit;text-decoration:none}.nova-homepage img{display:block;max-width:100%}
.nova-home-active{overflow-x:hidden;background:var(--page-bg,#080b14)}
.nova-home-active #web_bg{display:none}.nova-home-active #page-header.full_page{position:absolute;inset:0 0 auto;z-index:10000;height:0;min-height:0;background:none!important}
.nova-hero-mist{position:absolute;inset:0;z-index:2;background:radial-gradient(circle at 78% 58%,rgba(179,34,79,.16),transparent 27%),radial-gradient(circle at 54% 12%,rgba(94,119,142,.16),transparent 22%);animation:novaMist 14s ease-in-out infinite alternate}
.hero-galaxy-canvas{position:absolute!important;inset:0;z-index:3!important;width:100%;height:100%;pointer-events:none!important;opacity:.58}
.nova-hero-copy{position:absolute;left:max(7vw,30px);top:48%;transform:translateY(-50%);max-width:620px}
.nova-kicker,.nova-eyebrow{margin:0 0 12px;color:var(--rose);font-size:.7rem;font-weight:700;letter-spacing:.24em}
.nova-actions{display:flex;gap:12px;margin-top:32px}
.nova-actions a:first-child{background:linear-gradient(135deg,rgba(172,50,83,.84),rgba(92,112,132,.82))}.nova-actions a:hover{transform:translateY(-2px);border-color:rgba(255,255,255,.36)}.nova-latest-signal span{color:var(--rose);letter-spacing:.14em}.nova-latest-signal strong{overflow:hidden;color:#d8dbe4;font-weight:400;text-overflow:ellipsis;white-space:nowrap}.nova-latest-signal time{color:#8f96a5}.nova-bloom-message{position:absolute;z-index:6;left:50%;bottom:11%;opacity:0;color:#e7bac8;font:italic .78rem Georgia;transform:translateX(-50%);transition:opacity .5s}.nova-bloom-message.show{opacity:.68}
.nova-petal{position:fixed;z-index:20000;width:9px;height:15px;border-radius:80% 10% 70% 20%;background:#b93257;pointer-events:none;animation:novaPetal 1.5s ease-out forwards}
.nova-observatory>section{width:min(1180px,100%);margin:0 auto 72px}.nova-about-visual h2,.nova-section-heading h2,.nova-archive h2,.nova-fragments h2{margin:0 0 18px;color:var(--text-main);font:600 clamp(1.5rem,3vw,2.15rem)/1.1 Georgia,serif}.nova-about-visual h2 i,.nova-latest-title i{color:var(--rose);font-style:normal}.nova-tags{display:flex;flex-wrap:wrap;gap:7px;margin-top:19px}.nova-status-panel dl{margin:0}.nova-status-panel dl div{margin-bottom:21px}.nova-status-panel dt{color:var(--text-secondary);font-size:.6rem;letter-spacing:.13em}.nova-status-panel dd{margin:5px 0 0;color:var(--text-main);font-size:.84rem}.nova-progress{height:3px;background:var(--line)}.nova-progress span{display:block;height:100%;background:linear-gradient(90deg,var(--rose),var(--steel))}.nova-status-panel>small{display:block;margin-top:9px;color:var(--text-secondary);font-size:.58rem;text-align:right}
.nova-section-heading{display:flex;align-items:end;justify-content:space-between;margin-bottom:22px}.nova-section-heading p{margin:0 0 5px;color:var(--text-secondary);font-size:.63rem;letter-spacing:.18em}.nova-section-heading h2{margin:0}.nova-section-heading>a{color:var(--text-secondary);font-size:.72rem}.nova-note-card--lead{grid-row:1/3}.nova-note-card .post_cover{position:absolute;inset:0;width:100%!important;height:100%!important;margin:0!important}.nova-note-card .post_cover::after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(4,6,13,.96),rgba(4,6,13,.08) 75%)}.nova-note-card .post_cover a,.nova-note-card .post_cover img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .55s}.nova-note-card:hover .post_cover img{transform:scale(1.035)}.nova-note-card .recent-post-info{position:absolute!important;z-index:2;inset:auto 0 0;padding:24px!important;color:#fff;background:none!important}.nova-latest-title{margin:28px 0 15px;font-size:.86rem}.nova-latest-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.nova-note-card--compact .post_cover::after{display:none}.nova-archive h2{margin-bottom:20px}.nova-search input{width:100%;border:0;outline:0;color:var(--text-main);background:transparent;font:inherit}.nova-search i{color:var(--text-secondary);font-size:.65rem}.nova-archive-links b{color:var(--cool-light);font-size:1.2rem}.nova-year-lines a{display:flex;align-items:center;gap:10px;flex:1;color:var(--text-secondary);font-size:.57rem}.nova-year-lines i{height:1px;flex:1;background:var(--line)}
.nova-fragment-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.nova-fragment>div{position:relative;z-index:2}.nova-fragment small{color:#e4b2c2;font-size:.58rem;letter-spacing:.16em}.nova-fragment span{color:#d18aa0;font-size:.62rem}.nova-fragment--music img{position:absolute;inset:0;z-index:0;width:100%;height:100%;object-fit:cover;object-position:center;transform:none;filter:saturate(.72) brightness(.8)}.nova-fragment--gallery{background-image:url("../img/p1.webp")}.nova-footer::before{content:"";position:absolute;top:-1px;left:8%;right:8%;height:1px;background:linear-gradient(90deg,transparent,var(--rose),var(--steel),transparent)}.nova-footer>div{display:grid;grid-template-columns:auto auto;gap:0 9px}.nova-footer>div b{grid-row:1/3;color:var(--rose)}.nova-footer>a{display:grid;width:28px;height:28px;place-items:center;border-radius:4px;background:var(--rose);color:#fff}
.nova-reveal{opacity:0;transform:translateY(18px);transition:.7s ease}.nova-reveal.is-visible{opacity:1;transform:none}
@keyframes novaMist{to{transform:translate3d(1.5%,-1%,0);opacity:.75}}@keyframes novaPetal{to{opacity:0;transform:translate(var(--x),var(--y)) rotate(var(--r))}}

/* Midnight Rose palette and base layout */
.nova-particle-layer{position:absolute;inset:0;z-index:2;display:block;overflow:hidden;pointer-events:none}
.nova-particle-layer .hero-galaxy-canvas{display:block;opacity:.82!important;mix-blend-mode:screen;filter:saturate(1.06)}
.nova-hero-copy,.nova-track-card,.nova-latest-signal{z-index:3}
.nova-hero h1{margin:0 0 24px;letter-spacing:.025em;text-shadow:0 16px 50px rgba(0,0,0,.48);width:min(580px,46vw);font-size:inherit;line-height:.82;word-break:normal}
.nova-hero h1 span{display:block;white-space:nowrap;word-break:keep-all}
.nova-hero h1>span:first-child{font-size:clamp(64px,7vw,108px)}
.nova-hero h1>span:last-child{color:#efcbd4;margin-left:clamp(20px,2.3vw,36px);font-size:clamp(72px,8vw,124px)}
.nova-letter-o{cursor:pointer;display:inline!important}
.nova-cn-subtitle{margin:0 0 3px;letter-spacing:.08em;font-size:clamp(16px,1.4vw,18px)}
.nova-en-subtitle{margin:0;color:rgba(238,239,245,.78);font-size:clamp(15px,1.2vw,16px)}
.nova-actions a{border:1px solid rgba(255,255,255,.18);background:rgba(8,10,18,.38);backdrop-filter:blur(8px);transition:transform 260ms cubic-bezier(.22,1,.36,1),border-color 260ms ease,background-color 260ms ease,box-shadow 260ms ease;display:flex;align-items:center;min-height:46px;padding:0 22px;border-radius:6px;font-size:14px}
.nova-observatory{padding:64px max(5vw,22px) 90px;transition:background .35s;background:radial-gradient(circle at 15% 0%,rgba(216,91,125,.07),transparent 32%),linear-gradient(180deg,var(--page-bg),var(--section-bg) 55%,var(--section-bg-alt))}
.nova-now{display:grid;grid-template-columns:1.6fr 1fr;border:1px solid var(--line);overflow:hidden;min-height:330px;border-radius:14px;background:var(--card-bg);box-shadow:0 18px 42px rgba(0,0,0,.2),inset 0 1px rgba(255,255,255,.025)}
.nova-about-visual>img{object-fit:cover;filter:saturate(.7);width:210px;height:260px;border-radius:10px}
.nova-status-cards{display:grid;width:100%;gap:10px}
.nova-status-cards i{display:grid;width:30px;height:30px;place-items:center;border-radius:7px;color:var(--rose);background:rgba(216,91,125,.09);font-style:normal}
.nova-note-card{position:relative;overflow:hidden;border:1px solid var(--line);transition:transform .35s,box-shadow .35s;border-radius:13px;background:var(--card-bg);box-shadow:0 18px 42px rgba(0,0,0,.2),inset 0 1px rgba(255,255,255,.025)}
.nova-note-card:hover{transform:translateY(-3px);border-color:rgba(216,91,125,.38);box-shadow:0 16px 36px rgba(216,91,125,.08)}
.nova-note-card .article-title{display:-webkit-box;overflow:hidden;color:#fff!important;-webkit-box-orient:vertical;-webkit-line-clamp:2;font-size:17px!important}
.nova-note-card .article-meta-wrap{color:rgba(255,255,255,.76)!important;font-size:13px!important}
.nova-note-card .content{display:-webkit-box!important;overflow:hidden;margin-top:8px;-webkit-box-orient:vertical;-webkit-line-clamp:2;color:rgba(255,255,255,.76)!important;font-size:14px!important}
.nova-note-card--compact .content{display:none!important}
.nova-archive-links{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:12px}.nova-year-lines{display:flex;gap:30px;margin-top:12px}

/* Typography, pagination and complete Morning Mist theme */
.nova-homepage{
  --page-bg:var(--nova-home-bg);
  --section-bg:var(--nova-home-section-bg);
  --section-bg-alt:var(--nova-home-section-bg-alt);
  --card-bg:var(--nova-home-card-bg);
  --card-bg-hover:var(--nova-home-card-hover);
  --text-main:var(--nova-home-text);
  --text-secondary:var(--nova-home-text-secondary);
  --text-muted:var(--nova-home-text-muted);
  --rose:var(--nova-home-rose);
  --steel:var(--nova-home-steel);
  --cool-light:var(--nova-home-cool);
  --line:var(--nova-home-line);
  color:var(--text-main);
  background:var(--page-bg);
  font-size:16px;
  line-height:1.7;
  font-family:Inter,"Noto Sans SC","Microsoft YaHei",sans-serif
}
.nova-hero h1,.nova-section-eyebrow{font-family:"Cormorant Garamond","Playfair Display",Georgia,serif}
.nova-section-title,.nova-about-visual h2{font-family:"Noto Serif SC","Source Han Serif SC","Songti SC",serif;font-weight:600}
.nova-section-eyebrow{display:block;margin-bottom:7px;color:var(--rose);font-size:12px;font-weight:600;letter-spacing:.16em}
.nova-section-title{margin:0!important;color:var(--text-main);font-size:clamp(28px,3vw,34px)!important;line-height:1.2}
.nova-section-heading--latest{margin-top:30px;margin-bottom:15px}
.nova-note-card[data-href]{cursor:pointer}
.nova-note-card[data-href]:focus-visible{outline:2px solid var(--rose);outline-offset:3px}
.nova-status-cards span{letter-spacing:.08em;font-size:11px;color:#aaa3b0}

[data-theme=light] .nova-homepage{
  color:var(--text-main);background:var(--page-bg)
}
[data-theme=light] .nova-observatory{background:radial-gradient(circle at 15% 10%,rgba(201,94,123,.06),transparent 34%),linear-gradient(180deg,#f7f4f1 0%,#f1f2f5 100%)}
[data-theme=light] .nova-now,[data-theme=light] .nova-note-card,[data-theme=light] .nova-archive{color:var(--text-main);background:rgba(255,255,255,.9);border-color:var(--line);box-shadow:0 14px 36px rgba(46,39,55,.09),inset 0 1px rgba(255,255,255,.7)}
[data-theme=light] .nova-about-visual>img{filter:saturate(.9) contrast(1.02) brightness(1)}
[data-theme=light] .nova-status-panel{background:rgba(112,130,144,.035);border-color:var(--line)}
[data-theme=light] .nova-status-cards article{background:rgba(244,241,238,.7);border-color:var(--line)}
[data-theme=light] .nova-status-cards span{color:var(--text-muted)}
[data-theme=light] .nova-note-card .recent-post-info{color:var(--text-main)}
[data-theme=light] .nova-note-card--compact .article-title{color:var(--text-main)!important}
[data-theme=light] .nova-note-card--compact .article-meta-wrap{color:var(--text-muted)!important}
[data-theme=light] .nova-note-card--lead .recent-post-info,[data-theme=light] .nova-note-card--side .recent-post-info{background:linear-gradient(0deg,rgba(255,255,255,.98),rgba(255,255,255,.84) 76%,transparent)!important}
[data-theme=light] .nova-note-card--lead .post_cover::after,[data-theme=light] .nova-note-card--side .post_cover::after{background:linear-gradient(0deg,rgba(255,255,255,.96),transparent 75%)}
[data-theme=light] .nova-note-card--lead .article-title,[data-theme=light] .nova-note-card--side .article-title{color:var(--text-main)!important;text-shadow:0 1px #fff}
[data-theme=light] .nova-note-card--lead .article-meta-wrap,[data-theme=light] .nova-note-card--side .article-meta-wrap,[data-theme=light] .nova-note-card--lead .content,[data-theme=light] .nova-note-card--side .content{color:var(--text-secondary)!important}
[data-theme=light] .nova-search,[data-theme=light] .nova-archive-links a{background:rgba(255,255,255,.7);border-color:var(--line)}
[data-theme=light] .nova-search input{color:var(--text-main)}
[data-theme=light] .nova-footer{color:#474653;background:#e9e8ec;border-color:rgba(55,48,67,.1)}
[data-theme=light] .nova-footer strong{color:#292733}

/* Hero-only three-part cinematic grid */
.nova-hero-primary{
  grid-column:1/span 5;
  grid-row:1;
  position:relative;
  z-index:3;
  min-width:0;
}
.nova-hero-primary .nova-kicker{margin:0 0 16px}
.nova-hero-primary h1{
  width:auto;
  margin:0 0 clamp(28px,3vh,34px);
  line-height:.82;
  word-break:normal;
}
.nova-hero-primary h1 span{display:block;white-space:nowrap;word-break:keep-all}
.nova-hero-primary h1>span:first-child{font-size:clamp(64px,6.1vw,100px)}
.nova-hero-primary h1>span:last-child{margin-left:clamp(16px,1.7vw,28px);font-size:clamp(70px,6.7vw,108px)}
.nova-hero-primary .nova-cn-subtitle{margin-bottom:8px}
.nova-hero-primary .nova-actions{margin-top:30px}
.nova-track-card{z-index:5;
  grid-column:10/span 3;
  grid-row:1/3;
  position:relative;
  right:auto;
  bottom:auto;
  align-self:center;
  justify-self:start;
  width:min(280px,100%);
  min-height:190px;
  padding:24px 26px;
  border:1px solid rgba(220,91,126,.20);
  border-radius:12px;
  background:rgba(16,12,23,.72);
  box-shadow:0 20px 55px rgba(0,0,0,.32);
  backdrop-filter:blur(18px);
}
.nova-track-card p{margin:0 0 12px;color:#d9b7c2;letter-spacing:.16em;font-size:11px}.nova-track-card ul{margin:0 0 13px;padding:0;list-style:none;font-size:15px;line-height:1.75}.nova-track-card small{color:#9ca2b0;font-size:12px}
.nova-latest-signal{z-index:3;align-items:center;font-size:.66rem;letter-spacing:.04em;
  grid-column:1/span 5;
  grid-row:2;
  position:relative;
  left:auto;
  bottom:auto;
  align-self:start;
  display:grid;
  grid-template-columns:auto minmax(0,1fr) auto;
  gap:14px;
  width:100%;
  max-width:none;
  padding-top:14px;
  border-top:1px solid rgba(255,255,255,.12);
}

/* Hero poster composition using /img/background02.webp */
.nova-home-active #nav{color:#fff;text-shadow:0 1px 12px #000;
  height:66px;
  padding-inline:max(28px,calc((100vw - 1480px)/2 + 34px));
  background:linear-gradient(to bottom,rgba(5,7,14,.58),rgba(5,7,14,.12),transparent);
}
.nova-home-active #nav .site-page{font-size:14px}
.nova-home-active #nav .menus_item>a i,.nova-home-active #nav .menus_item>.site-page>i:not(.fa-chevron-down){display:none}
.nova-home-active #nav .menus_item:first-child>a::after{content:"";position:absolute;right:12px;left:12px;background:#d85b7d;bottom:8px;height:1px;box-shadow:none}
.hero-inner{
  position:relative;
  z-index:3;
  display:grid;
  column-gap:24px;
  row-gap:clamp(56px,6vh,72px);
  margin:0 auto;
  padding-top:34px;
  grid-template-columns:repeat(12,minmax(0,1fr));
  grid-template-rows:1fr;
  align-content:stretch;
  align-items:center;
  width:min(1480px,calc(100% - 96px));
  min-height:100%;
  padding:72px 0 22px;
}
.hero-copy.nova-hero-primary{
  grid-column:1/span 5;
  grid-row:1;
  align-self:center;
  width:min(520px,100%);
  padding-top:20px;
}
.hero-copy .nova-kicker{margin:0 0 18px;font-size:12px;letter-spacing:.24em}
.hero-copy .hero-title{margin:0 0 30px;line-height:.86;letter-spacing:-.025em;text-shadow:0 10px 34px rgba(0,0,0,.32)}
.hero-copy .hero-title-nova{margin:0;color:#f3eee9;font-size:clamp(58px,6vw,94px)}
.hero-copy .hero-title-fliex{margin:0 0 0 12px;color:#dba7b4;font-size:clamp(66px,6.8vw,106px)}
.hero-copy .nova-cn-subtitle{margin:0 0 8px;color:rgba(245,241,243,.94);font-size:clamp(17px,1.35vw,19px);font-weight:400}
.hero-copy .nova-en-subtitle{margin:0;color:rgba(231,227,232,.78);font-size:clamp(15px,1.1vw,16px)}
.hero-copy .nova-actions{margin-top:30px;gap:14px}
.hero-copy .nova-actions a{height:46px;min-height:46px;padding-inline:24px;border-radius:6px}
.hero-copy .nova-actions a:first-child{background:linear-gradient(135deg,rgba(158,61,91,.96),rgba(115,57,91,.96));box-shadow:none}
.hero-copy .nova-actions a:last-child{background:transparent;border-color:rgba(219,167,180,.42)}
.hero-copy .nova-actions a:hover{transform:translateY(-2px);border-color:rgba(229,188,198,.68);box-shadow:0 10px 24px rgba(0,0,0,.20)}
.hero-copy .nova-latest-signal{
  position:relative;
  display:grid;
  grid-template-columns:auto minmax(0,1fr) auto;
  gap:13px;
  width:100%;
  margin-top:54px;
  padding:0;
  border:0;
  font-size:12px;
}
.hero-copy .nova-latest-signal::after{content:"";position:absolute;right:0;bottom:-12px;width:78px;height:1px;background:linear-gradient(90deg,rgba(216,91,125,.65),transparent)}
.nova-particle-softener{
  position:absolute;
  inset:0;
  z-index:2;
  pointer-events:none;
  background:
    linear-gradient(90deg,rgba(5,7,14,.42) 0%,rgba(5,7,14,.23) 31%,transparent 48%),
    linear-gradient(180deg,rgba(5,7,14,.32),transparent 14%);
}
/* Hero poster hierarchy: nav 10% / visual 62% / information 18% / transition 10% */
.nova-home-active #nav .nav-site-title{display:flex;align-items:center;gap:11px}
.nova-home-active #nav .site-icon{
  width:30px;
  height:30px;
  object-fit:contain;
  object-position:center;
  border-radius:0;
  opacity:.9;
  mix-blend-mode:normal;
  filter:none;
}
.nova-home-active #nav .site-name{font-family:"Cormorant Garamond",Georgia,serif;color:#f0e9e8;font-size:15px;letter-spacing:.18em}
/* Hero copy flow guard: keep every copy element horizontal and prevent grid collapse. */
.nova-hero .hero-copy{
  box-sizing:border-box;
  width:min(520px,42vw);
  min-width:420px;
  max-width:520px;
  display:flex;
  flex-direction:column;
  align-items:flex-start;
}
.nova-hero .nova-kicker{
  width:auto;
  max-width:100%;
  white-space:nowrap;
  word-break:normal;
  overflow-wrap:normal;
}
.nova-hero .nova-cn-subtitle{
  width:100%;
  min-width:0;
  white-space:normal;
  word-break:keep-all;
  overflow-wrap:normal;
}
.nova-hero .nova-en-subtitle{
  width:100%;
  min-width:0;
  white-space:normal;
  word-break:normal;
  overflow-wrap:normal;
}
.nova-hero .hero-title span{
  white-space:nowrap;
  word-break:normal;
  overflow-wrap:normal;
}
.nova-hero .nova-actions{
  display:flex;
  flex-direction:row;
  flex-wrap:nowrap;
  width:auto;
}
.nova-hero .nova-actions a{
  white-space:nowrap;
  word-break:keep-all;
  overflow-wrap:normal;
}
.nova-hero .hero-copy .nova-latest-signal > *{
  white-space:nowrap;
  word-break:normal;
  overflow-wrap:normal;
}

/* Homepage component details */
.nova-about-visual{display:grid;grid-template-columns:210px 1fr;align-items:center;gap:32px;padding:30px 32px}
.nova-about-visual>div>p:not(.nova-eyebrow){margin:0;color:var(--text-secondary);font-size:15px;line-height:1.75}
.nova-tags span{border:1px solid var(--line);border-radius:5px;color:var(--text-secondary);font-size:11px;padding:6px 10px}
.nova-status-panel{border-left:1px solid var(--line);background:rgba(109,132,152,.025);display:flex;align-items:center;padding:24px 26px}
.nova-status-cards article{display:flex;align-items:center;gap:13px;border:1px solid var(--line);border-radius:10px;background:rgba(255,255,255,.025);min-height:70px;padding:15px 18px}
.nova-status-cards b{display:block;margin-top:5px;font-weight:500;letter-spacing:0;color:var(--text-main);font-size:14px}

.nova-featured-grid{display:grid;grid-template-rows:1fr 1fr;gap:10px;height:440px;grid-template-columns:1.55fr 1fr}
.nova-note-card--lead .article-title{font-size:clamp(22px,1.7vw,24px)!important}
.nova-note-card--side .article-title{font-size:16px!important}
.nova-note-card--side .content{-webkit-line-clamp:1}
.nova-note-card--compact{
  min-height:76px;
  transition:transform .3s,border-color .3s,box-shadow .3s;
}
.nova-note-card--compact .post_cover{position:relative;float:left;
  width:88px!important;
  height:100%!important;
  min-height:76px;
  overflow:hidden;
}
.nova-note-card--compact .recent-post-info{position:relative!important;inset:auto;padding:14px 16px!important}
.nova-note-card--compact .article-title{color:var(--text-main)!important;font-size:15px!important;font-weight:600}
.nova-note-card--compact .article-meta-wrap{font-size:12.5px!important}
.nova-note-card--compact:hover{
  transform:translateY(-2px);
  border-color:rgba(216,91,125,.38);
}
.nova-note-card--compact:hover .article-title{color:var(--cool-light)!important}
.nova-note-card--compact:hover .post_cover img{transform:scale(1.03)}

.nova-archive{border:1px solid var(--line);border-radius:14px;background:var(--card-bg);box-shadow:0 18px 42px rgba(0,0,0,.16),inset 0 1px rgba(255,255,255,.025);padding:24px}
.nova-search{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px;padding:0 17px;border:1px solid var(--line);border-radius:5px;background:rgba(109,132,152,.035);height:46px;font-size:14px}
.nova-archive-links a{display:flex;align-items:center;gap:12px;border:1px solid var(--line);border-radius:8px;min-height:62px;padding:14px 16px}
.nova-archive-links span{font-size:14px;font-weight:500}
.nova-archive-links small{display:block;margin-top:3px;color:var(--text-secondary);font-size:9px;font-weight:400}
.nova-fragment::before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(90deg,rgba(7,9,16,.94),rgba(7,9,16,.42) 52%,rgba(7,9,16,.12));pointer-events:none}
.nova-fragment h3{margin:5px 0 24px;color:#fff;font-size:18px}
.nova-fragment{position:relative;display:flex;align-items:center;border:1px solid var(--line);background-position:center;transition:transform .35s;padding:26px;border-radius:13px;box-shadow:0 18px 42px rgba(0,0,0,.18);background-size:105%;min-height:216px;overflow:hidden}
.nova-fragment--moments{background-image:url("/img/guidang.webp");background-position:center 58%}
.nova-fragment:hover{border-color:rgba(216,91,125,.38);transform:translateY(-3px);background-size:109%}

.nova-footer{position:relative;display:flex;align-items:center;justify-content:space-between;color:var(--text-secondary);background:#080b14;border-top:1px solid rgba(255,255,255,.08);padding-block:30px;
  min-height:0;
  padding:24px max(5vw,22px);
}
.nova-footer strong{color:var(--text-main);font-size:16px}
.nova-footer nav{display:flex;gap:24px;font-size:13.5px}
.nova-footer small{font-size:12px}

/* Hero composition */
.nova-hero{
  background:#070911;
  position:relative;
  isolation:isolate;
  width:100%;
  min-height:100svh;
  height:100svh;
  max-height:none;
  overflow:hidden;
}
.nova-hero-bg{position:absolute;
  background:url("/img/background02.webp") center center/cover no-repeat;
  filter:saturate(.88) contrast(1.03);
  transform:none!important;
  inset:0;
  width:100%;
  height:100%;
  background-position:center 48%;
  background-size:cover;
  background-repeat:no-repeat;
}
.nova-hero-bg::after{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  background:url("/img/background03.png") center 46%/cover no-repeat;
  opacity:0;
  transition:opacity .55s ease;
}
html[data-theme="light"] body.nova-home-active .nova-hero-bg::after{opacity:1}
html[data-theme="dark"] body.nova-home-active .nova-hero-bg::after{opacity:0}
.nova-hero::before{content:"";position:absolute;
  z-index:1;
  inset:0;
  background:
    linear-gradient(90deg,rgba(4,6,12,.94) 0%,rgba(4,6,12,.72) 28%,rgba(4,6,12,.20) 52%,transparent 72%),
    linear-gradient(180deg,transparent 0%,transparent 78%,rgba(7,8,15,.24) 90%,var(--page-bg) 100%);
}
.nova-hero::after{
  position:absolute;
  inset:auto 0 0;
  z-index:2;
  pointer-events:none;
  height:64px;
  background:linear-gradient(180deg,rgba(7,9,17,0) 0%,rgba(14,12,24,.72) 45%,var(--page-bg) 100%);
  content:none;
}
.nova-hero .nova-hero-mist,
.nova-hero .nova-particle-layer,
.nova-hero .hero-galaxy-canvas{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  max-height:100%;
}
.nova-hero .hero-inner{
  width:min(1440px,calc(100% - 96px));
  height:100%;
  min-height:0;
  margin:0 auto;
  padding:0;
  display:grid;
  grid-template-rows:72px minmax(0,1fr);
  align-items:stretch;
  position:relative;
  z-index:3;
}
.nova-hero .nova-hero-main{
  grid-row:2;
  grid-column:1 / -1;
  display:flex;
  align-items:center;
  width:100%;
  min-height:0;
}
.nova-hero .hero-copy.nova-hero-copy{
  position:relative;
  left:auto;
  right:auto;
  top:auto;
  width:min(540px,42vw);
  min-width:420px;
  max-width:540px;
  margin:0;
  padding:0;
  display:flex;
  flex-direction:column;
  align-items:flex-start;
  transform:translateY(clamp(20px,3vh,32px));
}
.nova-hero .hero-copy .nova-kicker{
  margin:0 0 16px;
  color:#d86784;
  font-size:12px;
  letter-spacing:.22em;
  white-space:nowrap;
}
.nova-hero .hero-copy .hero-title{
  width:auto;
  margin:0 0 28px;
  line-height:.84;
  letter-spacing:-.025em;
  text-shadow:0 8px 26px rgba(0,0,0,.28);
}
.nova-hero .hero-copy .hero-title span{
  display:block;
  white-space:nowrap;
  word-break:normal;
}
.nova-hero .hero-copy .hero-title-nova{
  margin:0;
  color:#f3efeb;
  font-size:clamp(64px,6.4vw,98px);
}
.nova-hero .hero-copy .hero-title-fliex{
  margin:0 0 0 12px;
  color:#deb2bd;
  font-size:clamp(70px,7vw,108px);
}
.nova-hero .hero-copy .nova-cn-subtitle{
  margin:0 0 8px;
  color:rgba(246,242,244,.9);
  font-size:17px;
  line-height:1.7;
}
.nova-hero .hero-copy .nova-en-subtitle{
  margin:0;
  color:rgba(225,221,227,.79);
  font-size:14px;
  line-height:1.6;
}
.nova-hero .hero-copy .nova-actions{
  display:flex;
  flex-flow:row nowrap;
  gap:14px;
  margin-top:28px;
}
.nova-hero .hero-copy .nova-actions a{
  min-height:44px;
  height:44px;
  padding-inline:24px;
  border-radius:6px;
}
.nova-hero .hero-copy .nova-actions a:first-child{
  background:linear-gradient(135deg,#a84f6c,#7f3f59);
  box-shadow:none;
}
.nova-hero .hero-copy .nova-actions a:last-child{
  background:transparent;
  border-color:rgba(221,183,196,.48);
}
.nova-hero .hero-copy .nova-actions a:hover{
  transform:translateY(-2px);
  border-color:rgba(232,197,206,.66);
  box-shadow:0 10px 24px rgba(0,0,0,.22);
}
.nova-hero .hero-copy .nova-latest-signal{
  min-width:0;
  position:relative;
  left:auto;
  right:auto;
  bottom:auto;
  width:100%;
  max-width:100%;
  margin-top:46px;
  padding-top:18px;
  display:grid;
  grid-template-columns:auto minmax(0,1fr) auto;
  align-items:center;
  gap:10px;
  border-top:1px solid rgba(255,255,255,.08);
  font-size:12px;
}
.nova-hero .hero-copy .nova-latest-signal::after{content:none}
.nova-home-active #nav a,
.nova-home-active #nav .site-page{
  color:rgba(245,241,244,.82);
  transition:color .25s ease;
}
.nova-home-active #nav a:hover,
.nova-home-active #nav .site-page:hover{
  color:#fff;
}
.nova-scroll-hint{
  position:absolute;
  z-index:5;
  left:50%;
  bottom:28px;
  display:grid;
  width:28px;
  height:34px;
  place-items:center;
  color:rgba(235,225,230,.46);
  transform:translateX(-50%);
}
.nova-scroll-hint span{
  position:relative;
  display:block;
  width:9px;
  height:9px;
  border-right:1px solid currentColor;
  border-bottom:1px solid currentColor;
  transform:rotate(45deg);
  animation:nova-scroll-drift 3.2s ease-in-out infinite;
}
@keyframes nova-scroll-drift{
  0%,100%{top:0}
  50%{top:5px}
}

/* Midnight carriage: homepage dark theme only */
html[data-theme="dark"] body.nova-home-active .nova-homepage{
