/* Hero-to-content proportion and carriage. */
.nova-home-active .nova-observatory {
  padding-right:clamp(20px,3.25vw,54px);
  padding-left:clamp(20px,3.25vw,54px);
}

.nova-home-active .nova-observatory > section {
  width:min(1320px,100%);
}

.nova-home-active .nova-observatory > .nova-now {
  width:min(1360px,calc(100% + 40px));
  margin-right:auto;
  margin-left:auto;
  border-radius:18px;
}

html[data-theme="dark"] body.nova-home-active .nova-hero::after {
  height:clamp(110px,12vh,150px);
  background:linear-gradient(180deg,rgba(8,12,22,0),rgba(8,12,22,.62) 44%,#080c16 100%);
}

html[data-theme="dark"] body.nova-home-active .nova-observatory {
  position:relative;
  z-index:3;
  padding-top:0;
  background:
    radial-gradient(ellipse at 50% 0%,rgba(137,83,111,.09),transparent 42%),
    linear-gradient(180deg,rgba(8,12,22,.36) 0%,rgba(9,14,25,.9) 150px,#0a101c 280px,#0c1220 100%);
}

html[data-theme="dark"] body.nova-home-active .nova-observatory > .nova-now {
  position:relative;
  z-index:4;
  margin-top:-60px;
  border-color:rgba(225,215,225,.15);
  background:linear-gradient(145deg,rgba(17,22,33,.68),rgba(12,17,27,.58));
  -webkit-backdrop-filter:blur(18px) saturate(1.08);
  backdrop-filter:blur(18px) saturate(1.08);
  box-shadow:0 28px 72px rgba(0,0,0,.32),inset 0 1px rgba(255,255,255,.055),inset 0 -1px rgba(255,255,255,.018);
}

html[data-theme="light"] body.nova-home-active .nova-observatory > .nova-now {
  position:relative;
  z-index:4;
  margin-top:-60px;
  border-color:rgba(89,72,92,.16);
  background:linear-gradient(145deg,rgba(250,247,250,.48),rgba(226,223,232,.38));
  -webkit-backdrop-filter:blur(22px) saturate(1.08);
  backdrop-filter:blur(22px) saturate(1.08);
  box-shadow:0 24px 58px rgba(54,44,61,.14),inset 0 1px rgba(255,255,255,.7),inset 0 -1px rgba(91,73,96,.035);
  width:min(1360px,calc(100% + 40px));
}

.nova-home-active .nova-observatory > .nova-now::before{
  content:"";
  position:absolute;
  z-index:3;
  top:0;
  right:22px;
  left:22px;
  height:1px;
  pointer-events:none;
  background:linear-gradient(90deg,transparent,rgba(239,220,228,.22) 34%,rgba(205,218,233,.16) 68%,transparent);
}

/* Butterfly rightside controls: scoped styling, with a two-button homepage mode. */
#rightside .fliex-rightside-button {
  display:flex;
  align-items:center;
  justify-content:center;
  width:38px;
  height:38px;
  margin-bottom:8px;
  padding:0;
  border-radius:10px;
  line-height:1;
  transition:
    background-color .24s ease,
    border-color .24s ease,
    color .24s ease,
    box-shadow .24s ease,
    transform .24s ease;
}

#rightside .fliex-rightside-button:hover {
  transform:translateY(-2px);
}

#rightside .fliex-rightside-button:active {
  transform:translateY(0) scale(.94);
}

#rightside .fliex-rightside-button svg {
  display:block;
  width:17px;
  height:17px;
  flex:0 0 auto;
  fill:none;
  stroke:currentColor;
  stroke-width:1.8;
  stroke-linecap:round;
  stroke-linejoin:round;
}

#rightside .fliex-rightside-button i {
  display:flex;
  align-items:center;
  justify-content:center;
  width:18px;
  height:18px;
  font-size:16px;
  line-height:1;
  color:currentColor;
}

html[data-theme="light"] #rightside .fliex-rightside-button {
  color:rgba(85,78,88,.9);
  background:linear-gradient(145deg,rgba(255,252,253,.96),rgba(247,241,245,.94))!important;
  border:1px solid rgba(204,181,193,.52);
  box-shadow:0 6px 18px rgba(103,78,94,.1),0 2px 5px rgba(103,78,94,.05);
  -webkit-backdrop-filter:blur(8px);
  backdrop-filter:blur(8px);
}

html[data-theme="light"] #rightside .fliex-rightside-button:hover {
  color:rgba(181,91,129,.98);
  background:linear-gradient(145deg,rgba(251,242,247,.98),rgba(244,233,239,.98))!important;
  border-color:rgba(190,119,149,.48);
}

html[data-theme="dark"] #rightside .fliex-rightside-button {
  color:rgba(214,202,211,.88);
  background:linear-gradient(145deg,rgba(19,26,41,.95),rgba(24,22,34,.94))!important;
  border:1px solid rgba(184,128,151,.24);
  box-shadow:0 8px 21px rgba(0,0,0,.3),0 0 18px rgba(136,79,104,.05);
  -webkit-backdrop-filter:blur(8px);
  backdrop-filter:blur(8px);
}

html[data-theme="dark"] #rightside .fliex-rightside-button:hover {
  color:rgba(222,140,173,.98);
  background:linear-gradient(145deg,rgba(31,34,50,.98),rgba(35,27,41,.98))!important;
  border-color:rgba(193,123,151,.42);
}

#home-theme-toggle {
  display:none!important;
}

#rightside.is-home-minimal {
  opacity:1;
  transform:translate(-58px,0);
}

#rightside.is-home-minimal #rightside-config-hide,
#rightside.is-home-minimal #rightside-config {
  display:none!important;
}

#rightside.is-home-minimal #rightside-config-show > :not(#home-theme-toggle):not(#go-up) {
  display:none!important;
}

#rightside.is-home-minimal #home-theme-toggle {
  display:flex!important;
}

#rightside.is-home-minimal:not(.rightside-show) #go-up {
  display:none!important;
}

.home-theme-toggle__icons {
  position:relative;
  display:block;
  width:17px;
  height:17px;
}

#rightside .home-theme-toggle__icon {
  position:absolute;
  inset:0;
  transition:opacity .24s ease,transform .24s ease;
}

html[data-theme="light"] .home-theme-toggle__icon--moon,
html[data-theme="dark"] .home-theme-toggle__icon--sun {
  opacity:1;
  transform:rotate(0) scale(1);
}

html[data-theme="light"] .home-theme-toggle__icon--sun {
  opacity:0;
  transform:rotate(-24deg) scale(.72);
}

html[data-theme="dark"] .home-theme-toggle__icon--moon {
  opacity:0;
  transform:rotate(24deg) scale(.72);
}

/* Light-theme Hero clarity: keep the image clean and confine haze to copy. */
html[data-theme="light"] body.nova-home-active .nova-hero-bg {
  background-image:url("/img/background02.webp");
  background-position:center 46%;
  background-size:cover;
  filter:none;
  opacity:1;
  transform:none!important;
  -webkit-backdrop-filter:none;
  backdrop-filter:none;
}

