  background:
    linear-gradient(90deg,rgba(249,245,247,.26) 0%,rgba(249,245,247,.13) 25%,rgba(249,245,247,.035) 42%,transparent 57%),
    linear-gradient(0deg,rgba(247,241,244,.18) 0%,rgba(247,241,244,.06) 20%,transparent 43%);
  -webkit-backdrop-filter:none;
  backdrop-filter:none;
}

html[data-theme="light"] body.nova-home-active .nova-hero::before {
  background:
    linear-gradient(90deg,rgba(248,244,247,.74) 0%,rgba(248,244,247,.52) 17%,rgba(248,244,247,.25) 32%,rgba(248,244,247,.07) 45%,transparent 58%),
    linear-gradient(0deg,rgba(246,240,244,.24) 0%,rgba(246,240,244,.1) 22%,transparent 48%);
}

html[data-theme="light"] body.nova-home-active .nova-hero::after {
  content:"";
  position:absolute;
  z-index:2;
  right:0;
  bottom:0;
  left:0;
  pointer-events:none;
  inset:0;
  height:auto;
  background:linear-gradient(
    to bottom,
    transparent 82%,
    rgba(246,242,246,.1) 91%,
    var(--page-bg) 100%
  );
}

html[data-theme="light"] body.nova-home-active .nova-hero .hero-title-nova {
  font-size:clamp(50px,5vw,77px);
  font-weight:500;
  color:rgba(39,41,52,.96);
}

html[data-theme="light"] body.nova-home-active .nova-hero .hero-title-fliex {
