  opacity:1;
  text-shadow:0 1px 2px rgba(255,255,255,.3);
}

html[data-theme="light"] body.nova-home-active .nova-hero .nova-latest-signal,
html[data-theme="light"] body.nova-home-active .nova-hero .nova-latest-signal time {
