}

html[data-theme="light"] body.nova-home-active .nova-hero .nova-latest-signal{
  border-top-color:rgba(89,69,82,.2);
  text-shadow:0 1px 2px rgba(255,252,253,.5);
}

html[data-theme="light"] body.nova-home-active .nova-hero .nova-latest-signal strong{
  color:rgba(58,49,59,.96);
}

html[data-theme="light"] body.nova-home-active .nova-hero .nova-actions a:first-child {
  box-shadow:0 7px 18px rgba(91,62,76,.1);
  color:rgba(255,251,253,.98);
  background:rgba(187,91,128,.92);
  border-color:rgba(168,76,113,.28);
}

html[data-theme="light"] body.nova-home-active .nova-hero .nova-actions a:first-child:hover {
  border-color:#925269;
  box-shadow:0 9px 20px rgba(91,62,76,.13);
  background:rgba(174,79,116,.98);
}

html[data-theme="light"] body.nova-home-active .nova-hero .nova-actions a:last-child {
  color:rgba(55,54,64,.92);
  background:rgba(255,255,255,.28);
  border-color:rgba(255,255,255,.56);
  -webkit-backdrop-filter:blur(9px) saturate(1.04);
  backdrop-filter:blur(9px) saturate(1.04);
  box-shadow:inset 0 1px rgba(255,255,255,.5),0 4px 14px rgba(69,58,73,.045);
}

.nova-home-active .nova-hero-bg,
.nova-home-active .nova-hero::before,
.nova-home-active .nova-hero::after,
.nova-home-active .nova-particle-softener,
.nova-home-active .nova-hero .nova-kicker,
.nova-home-active .nova-hero .hero-title-nova,
.nova-home-active .nova-hero .hero-title-fliex,
.nova-home-active .nova-hero .nova-cn-subtitle,
.nova-home-active .nova-hero .nova-en-subtitle,
.nova-home-active .nova-hero .nova-latest-signal,
.nova-home-active .nova-hero .nova-latest-signal span,
.nova-home-active .nova-hero .nova-latest-signal strong,
.nova-home-active .nova-hero .nova-latest-signal time{
  transition:color .38s ease,background-color .38s ease,border-color .38s ease,box-shadow .38s ease,opacity .38s ease,filter .38s ease;
}

/* Hero entrance, typewriter and restrained breathing buttons. */
.nova-homepage .nova-hero .hero-title{
  animation:nova-title-arrive 1.2s cubic-bezier(.22,1,.36,1) .2s both;
}
.nova-hero .nova-en-subtitle{
  min-height:1.6em;
}
.nova-hero .hero-subtitle-typing{
  display:block;
  max-width:100%;
  overflow:hidden;
  white-space:nowrap;
  clip-path:inset(0 100% 0 0);
  animation:nova-subtitle-type var(--typing-duration,2.8s) steps(var(--typing-steps,35),end) 1.55s both;
}
.nova-home-active .nova-hero .nova-actions a{
  transition:
    transform 260ms cubic-bezier(.22,1,.36,1),
    border-color 260ms ease,
    background-color 260ms ease,
    box-shadow 260ms ease;
}
.nova-hero .nova-actions a:hover,
.nova-hero .nova-actions a:focus-visible{
  transform:translateY(-2px);
}
html[data-theme="dark"] body.nova-home-active .nova-hero .nova-actions a:first-child:hover,
html[data-theme="dark"] body.nova-home-active .nova-hero .nova-actions a:first-child:focus-visible{
  border-color:color-mix(in srgb,var(--rose) 58%,transparent);
  background-color:color-mix(in srgb,#98566e 95%,white);
  box-shadow:0 6px 20px color-mix(in srgb,var(--rose) 10%,transparent),0 0 18px color-mix(in srgb,var(--rose) 8%,transparent);
}
html[data-theme="dark"] body.nova-home-active .nova-hero .nova-actions a:last-child:hover,
html[data-theme="dark"] body.nova-home-active .nova-hero .nova-actions a:last-child:focus-visible{
  border-color:color-mix(in srgb,var(--rose) 30%,var(--line));
  background-color:color-mix(in srgb,rgba(16,22,34,.28) 95%,white);
  box-shadow:0 6px 18px color-mix(in srgb,var(--rose) 6%,transparent),0 0 14px color-mix(in srgb,var(--rose) 4%,transparent);
}
html[data-theme="light"] body.nova-home-active .nova-hero .nova-actions a:first-child:hover,
html[data-theme="light"] body.nova-home-active .nova-hero .nova-actions a:first-child:focus-visible{
  border-color:color-mix(in srgb,var(--rose) 54%,transparent);
  background-color:color-mix(in srgb,rgba(187,91,128,.92) 95%,white);
  box-shadow:0 6px 20px color-mix(in srgb,var(--rose) 10%,transparent),0 0 18px color-mix(in srgb,var(--rose) 7%,transparent);
}
html[data-theme="light"] body.nova-home-active .nova-hero .nova-actions a:last-child:hover,
html[data-theme="light"] body.nova-home-active .nova-hero .nova-actions a:last-child:focus-visible{
  border-color:color-mix(in srgb,var(--rose) 22%,rgba(255,255,255,.56));
  background-color:rgba(255,255,255,.33);
  box-shadow:0 6px 18px color-mix(in srgb,var(--rose) 5%,transparent),0 0 14px color-mix(in srgb,var(--rose) 3%,transparent),inset 0 1px rgba(255,255,255,.58);
}
.nova-hero .nova-actions a:focus-visible{
  outline:2px solid color-mix(in srgb,var(--rose) 58%,transparent);
  outline-offset:3px;
}
@media(hover:none){
  .nova-home-active .nova-hero .nova-actions a:hover{transform:none}
}
.nova-hero .nova-latest-signal strong{
  transition:color .3s ease;
}
.nova-hero .nova-latest-signal:hover strong,
.nova-hero .nova-latest-signal:focus-visible strong{
  color:var(--rose);
}

@keyframes nova-title-arrive{
  from{opacity:0;transform:translateY(12px)}
  to{opacity:1;transform:translateY(0)}
}
@keyframes nova-subtitle-type{
  from{clip-path:inset(0 100% 0 0)}
  to{clip-path:inset(0)}
}

@media(max-width:900px){.nova-track-card{display:none}.nova-featured-grid{height:auto;grid-template-rows:320px 210px 210px}.nova-note-card--lead{grid-row:auto}.nova-now{grid-template-columns:1fr}.nova-status-panel{border-top:1px solid var(--line);border-left:0}.nova-archive-links{grid-template-columns:1fr 1fr}.nova-fragment-grid{grid-template-columns:1fr}}

@media(max-width:650px){.nova-hero{min-height:640px}.nova-latest-signal{left:22px;right:22px;max-width:none}.nova-latest-signal time{display:none}.nova-observatory{padding-inline:14px}.nova-latest-grid{grid-template-columns:1fr}.nova-section-heading>a{display:none}.nova-year-lines{display:none}.nova-footer{align-items:flex-start;gap:24px;flex-wrap:wrap}.nova-hero-copy{left:22px;right:22px;top:44%}}

@media(prefers-reduced-motion:reduce){.nova-homepage *{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}.nova-particle-layer .hero-galaxy-canvas{display:none}.nova-reveal{opacity:1;transform:none}.nova-homepage .nova-hero .hero-title{opacity:1;transform:none;animation:none!important}.nova-hero .hero-subtitle-typing{clip-path:inset(0);animation:none!important}.nova-home-active .nova-hero .nova-actions a:hover,.nova-home-active .nova-hero .nova-actions a:focus-visible{transform:none}}

@media(max-width:650px){.nova-home-active #rightside{right:8px}.nova-footer nav{gap:14px;flex-wrap:wrap}}

@media(max-width:992px){
  .nova-hero-primary{grid-column:1/span 5}
  .nova-track-card{display:block;grid-column:6/span 3}
  .nova-latest-signal{grid-column:1/span 5}
}

@media(max-width:768px){
  .nova-hero-primary{width:100%}
  .nova-hero-primary h1{width:100%;margin-bottom:24px}
  .nova-hero-primary h1>span:first-child{font-size:clamp(58px,17vw,86px)}
  .nova-hero-primary h1>span:last-child{margin-left:16px;font-size:clamp(64px,18.5vw,94px)}
  .nova-hero-primary .nova-actions{margin-top:26px}
  .nova-track-card{order:2;width:min(100%,360px);min-height:0;margin-top:34px;padding:20px 22px}
  .nova-latest-signal{order:3;margin-top:34px;padding-top:14px}
}

@media(max-width:480px){
  .nova-actions{flex-wrap:wrap}.nova-actions a{justify-content:center;flex:1;min-width:130px}
  .nova-latest-signal{grid-template-columns:auto minmax(0,1fr)}
  .nova-latest-signal time{display:none}
}

@media(max-width:992px){
  .hero-inner{width:calc(100% - 64px)}
  .hero-copy.nova-hero-primary{grid-column:1/span 6}
}

@media(max-width:768px){
  .nova-home-active #nav{height:64px;padding-inline:18px}
  .nova-home-active #nav .site-name{font-size:13px}
  .hero-inner{
    flex-direction:column;
    align-items:stretch;
    justify-content:center;
    gap:0;display:flex;width:calc(100% - 36px);padding:100px 0 42px}
  .hero-copy.nova-hero-primary{width:100%;padding:0}
  .hero-copy .hero-title-nova{font-size:clamp(54px,17vw,78px)}
  .hero-copy .hero-title-fliex{margin-left:10px;font-size:clamp(60px,18.5vw,86px)}
  .hero-copy .nova-latest-signal{margin-top:38px}
  .nova-particle-softener{background:linear-gradient(90deg,rgba(5,7,14,.50),rgba(5,7,14,.12) 82%,transparent)}
}

@media(max-width:480px){
  .hero-inner{width:calc(100% - 30px)}
  .hero-copy .nova-actions{display:grid;grid-template-columns:1fr 1fr}
  .hero-copy .nova-actions a{min-width:0;padding-inline:16px}
  .hero-copy .nova-latest-signal{grid-template-columns:auto minmax(0,1fr);font-size:11px}
  .hero-copy .nova-latest-signal time{display:none}
}

@media(max-width:768px){
  .nova-hero .hero-copy{
    width:calc(100% - 40px);
    min-width:0;
    max-width:none;
    margin-inline:auto;
  }
  .nova-hero .nova-kicker{white-space:normal}
  .nova-hero .nova-cn-subtitle{
    word-break:normal;
    overflow-wrap:normal;
  }
  .nova-hero .nova-actions{flex-wrap:wrap}
}

@media(max-width:768px){
  .nova-hero::after{height:52px}
  .nova-featured-grid{grid-template-columns:1fr}
  .nova-fragment{min-height:180px}
}

@supports(height:100dvh){
  .nova-hero{height:100dvh}
}

@media(prefers-reduced-motion:reduce){
  .nova-scroll-hint span{animation:none}
}

@media(max-width:768px){
  .nova-hero{
    height:auto;
    min-height:100svh;
    max-height:none;
  }
  .nova-hero .hero-inner{
    width:calc(100% - 40px);
    height:auto;
    min-height:100svh;
    padding:0;
    grid-template-rows:64px auto;
  }
  .nova-hero .nova-hero-main{
    padding:24px 0 32px;
  }
  .nova-hero .hero-copy.nova-hero-copy{
    width:100%;
    min-width:0;
    max-width:520px;
    margin:0;
    transform:none;
  }
  .nova-hero .hero-copy .hero-title-nova{font-size:clamp(54px,17vw,78px)}
  .nova-hero .hero-copy .hero-title-fliex{font-size:clamp(60px,18.5vw,86px)}
  .nova-hero .hero-copy .nova-kicker{white-space:normal}
  .nova-hero .hero-copy .nova-cn-subtitle{word-break:normal}
  .nova-hero .hero-copy .nova-actions{flex-wrap:wrap}
  .nova-hero .hero-copy .nova-latest-signal{
    grid-template-columns:auto minmax(0,1fr);
    row-gap:7px;
  }
  .nova-hero .hero-copy .nova-latest-signal time{
    grid-column:2;
    display:block;
  }
}

@supports(height:100dvh){
  html[data-theme="dark"] body.nova-home-active .nova-hero{height:100dvh}
}

@media(max-width:1024px){
  html[data-theme="dark"] body.nova-home-active .nova-hero .hero-copy.nova-hero-copy{
    width:min(490px,52vw);
    min-width:0;
    transform:translateY(-30px);
  }
  html[data-theme="dark"] body.nova-home-active .nova-observatory > .nova-now{
    margin-top:-48px;
  }
}

@media(max-width:768px){
  html[data-theme="dark"] body.nova-home-active .nova-hero{
    height:auto;
    min-height:100svh;
  }
  html[data-theme="dark"] body.nova-home-active .nova-hero-bg{
    background-position:58% 48%;
  }
  html[data-theme="dark"] body.nova-home-active .nova-hero::before{
    background:
      linear-gradient(90deg,rgba(4,7,14,.82),rgba(5,8,16,.58) 48%,rgba(5,8,16,.2) 72%,transparent 92%),
      linear-gradient(180deg,rgba(5,8,15,.08),transparent 68%,rgba(8,12,21,.38) 88%,#080c16 100%);
  }
  html[data-theme="dark"] body.nova-home-active .nova-hero .hero-copy.nova-hero-copy{
    width:100%;
    max-width:500px;
    transform:none;
  }
  html[data-theme="dark"] body.nova-home-active .nova-hero .hero-title-nova{
    font-size:clamp(48px,14.5vw,68px);
  }
  html[data-theme="dark"] body.nova-home-active .nova-hero .hero-title-fliex{
    font-size:clamp(53px,16vw,75px);
  }
  html[data-theme="dark"] body.nova-home-active .nova-hero .nova-latest-signal{
    display:grid;
    grid-template-columns:auto minmax(0,1fr);
    row-gap:7px;
    white-space:normal;
  }
  html[data-theme="dark"] body.nova-home-active .nova-hero .nova-latest-signal time{
    grid-column:2;
  }
  html[data-theme="dark"] body.nova-home-active .nova-hero .nova-latest-signal strong::after{
    content:none;
  }
  html[data-theme="dark"] body.nova-home-active .nova-observatory > .nova-now{
    margin-top:-26px;
  }
}

@media(max-width:420px){
  .nova-hero .hero-copy .nova-actions{width:100%;flex-direction:column}
  .nova-hero .hero-copy .nova-actions a{width:100%;justify-content:center}
}

@media(max-width:900px) {
  .nova-home-active .nova-observatory {
    padding-right:20px;
    padding-left:20px;
  }

  .nova-home-active .nova-observatory > .nova-now {
    width:100%;
  }
}

@media(max-width:767px) {
  #rightside.is-home-minimal #home-theme-toggle {
    display:none!important;
  }

  #rightside.is-home-minimal:not(.rightside-show) {
    opacity:0;
    transform:translate(0,0);
  }
}

@media(max-width:650px) {
  .nova-home-active .nova-observatory {
    padding-right:14px;
    padding-left:14px;
  }
}

@media(max-width:1024px){
  html[data-theme="light"] body.nova-home-active .nova-hero-bg{
    background-position:52% 48%;
  }
  html[data-theme="light"] body.nova-home-active .nova-hero .hero-copy.nova-hero-copy{
    width:min(480px,52vw);
    min-width:0;
    transform:translateY(-56px);
  }
  html[data-theme="light"] body.nova-home-active .nova-hero .hero-title-nova{
    font-size:clamp(47px,6.1vw,67px);
  }
  html[data-theme="light"] body.nova-home-active .nova-hero .hero-title-fliex{
    margin-top:clamp(12px,1.4vw,16px);
    font-size:clamp(51px,6.65vw,73px);
  }
  html[data-theme="light"] body.nova-home-active .nova-observatory > .nova-now{
    margin-top:-48px;
  }
}

@media(max-width:768px){
  html[data-theme="light"] body.nova-home-active .nova-hero{
    height:auto;
    min-height:100svh;
  }
  html[data-theme="light"] body.nova-home-active .nova-hero::before{
    background:linear-gradient(180deg,transparent 0%,transparent calc(100% - 52px),rgba(221,216,223,.3) 100%);
  }
  html[data-theme="light"] body.nova-home-active .nova-hero-bg{
    background-position:55% 48%;
  }
  html[data-theme="light"] body.nova-home-active .nova-hero .hero-copy.nova-hero-copy{
