    font-size:clamp(41px,12.4vw,54px);
  }
  html[data-theme="light"] body.nova-home-active .nova-hero .hero-title-fliex{
    margin-top:10px;
    font-size:clamp(45px,13.5vw,60px);
  }
  html[data-theme="light"] body.nova-home-active .nova-hero .hero-title{
