  }
  html[data-theme="light"] body.nova-home-active .nova-observatory > .nova-now{
    margin-top:-26px;
  }
}

@media(max-width:900px) {
  html[data-theme="light"] body.nova-home-active .nova-hero::before {
    background:linear-gradient(
      90deg,
      rgba(247,243,246,.74) 0%,
      rgba(247,243,246,.52) 28%,
      rgba(247,243,246,.2) 50%,
      rgba(247,243,246,.06) 60%,
      transparent 68%
    );
  }
}

.nova-shuoshuo-route {
  background: var(--shuo-bg);
  overflow-x: clip;
}

.nova-shuoshuo-overview.is-compact {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

@media (max-width: 560px) {
  .nova-shuoshuo-overview.is-compact {
    grid-template-columns: minmax(0, 1fr);
  }
}

body.nova-shuoshuo-route #body-wrap {
  width: 100%;
  min-width: 0;
  background: var(--shuo-bg);
}

body.nova-shuoshuo-route #page-header.nova-shuoshuo-nav-header {
  position: absolute;
  z-index: 20;
  top: 0;
  right: 0;
  left: 0;
  width: 100%;
  height: 70px;
  min-height: 0;
  background: transparent;
}

body.nova-shuoshuo-route #page-header.nova-shuoshuo-nav-header::before,
body.nova-shuoshuo-route #page-header.nova-shuoshuo-nav-header #page-site-info {
  display: none;
}

body.nova-shuoshuo-route #page-header.nova-shuoshuo-nav-header #nav {
  height: 70px;
  background: linear-gradient(180deg, rgba(5, 8, 17, .54), transparent);
  box-shadow: none;
}

body.nova-shuoshuo-route #page-header.nova-shuoshuo-nav-header.nav-fixed #nav {
  background: rgba(7, 10, 20, .76);
  border-bottom: 1px solid rgba(255, 255, 255, .06);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

body.nova-shuoshuo-route main#content-inner.nova-shuoshuo-shell {
  display: block;
  flex: 1 0 auto;
  width: 100%;
  max-width: none;
  margin: 0;
  padding: 0;
  background: transparent;
}

body.nova-shuoshuo-route footer#footer {
  width: 100%;
  margin: 0;
  align-self: stretch;
  border-top: 1px solid rgba(199, 96, 130, .13);
  background: linear-gradient(180deg, #090d18, #070a13);
  color: var(--shuo-secondary);
}

.nova-shuoshuo-page {
  min-height: 100vh;
  color: var(--shuo-text);
  background:
    radial-gradient(circle at 78% 34%, rgba(111, 72, 121, .13), transparent 31%),
    radial-gradient(circle at 12% 72%, rgba(157, 68, 102, .08), transparent 26%),
    linear-gradient(180deg, #0a1021 0, var(--shuo-bg) 34%, #080b15 100%);
}

.nova-shuoshuo-hero {
  position: relative;
  min-height: clamp(470px, 61vh, 640px);
  display: grid;
  place-items: center;
  overflow: hidden;
  background: url("/img/shuoshuo.webp") center 48% / cover no-repeat;
  isolation: isolate;
}

.nova-shuoshuo-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(circle at 50% 38%, transparent 0 19%, rgba(6, 9, 19, .13) 55%),
    linear-gradient(90deg, rgba(4, 8, 18, .42), rgba(6, 8, 18, .04) 50%, rgba(4, 8, 18, .36));
}

.nova-shuoshuo-hero-shade {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(180deg, rgba(4, 7, 16, .14) 0%, rgba(6, 9, 18, .10) 57%, #0a1021 100%);
}

.nova-shuoshuo-hero-copy {
  width: min(720px, calc(100% - 40px));
  margin-top: 26px;
  text-align: center;
  text-shadow: 0 3px 28px rgba(0, 0, 0, .52);
}

.nova-shuoshuo-hero-copy p,
.nova-shuoshuo-side-kicker {
  margin: 0;
  color: var(--shuo-rose-soft);
  font: 600 12px/1.4 "Inter", "Noto Sans SC", sans-serif;
  letter-spacing: .28em;
}

.nova-shuoshuo-hero-copy h1 {
  margin: 19px 0 16px;
  color: #f2dce5;
  font: 500 clamp(54px, 6.1vw, 88px)/1.05 "Noto Serif SC", "Songti SC", serif;
  letter-spacing: .18em;
  transform: translateX(.09em);
}

.nova-shuoshuo-hero-copy > span {
  display: block;
  color: rgba(248, 241, 245, .84);
  font-size: clamp(15px, 1.4vw, 18px);
  letter-spacing: .12em;
}

.nova-shuoshuo-hero-copy a {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  margin-top: 34px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(223, 157, 181, .44);
  color: rgba(247, 231, 238, .76);
  font-size: 11px;
  letter-spacing: .22em;
  transition: color .2s ease, border-color .2s ease;
}

.nova-shuoshuo-hero-copy a:hover {
  color: #fff;
  border-color: var(--shuo-rose-soft);
}

.nova-shuoshuo-hero-copy a i {
  font-style: normal;
}

.nova-shuoshuo-body {
  position: relative;
  z-index: 2;
  width: min(1280px, calc(100% - 64px));
  margin: -58px auto 0;
  padding-bottom: clamp(72px, 9vw, 124px);
}

.nova-shuoshuo-overview,
.nova-shuoshuo-card,
.nova-shuoshuo-side-card,
.nova-shuoshuo-comments {
  border: 1px solid var(--shuo-border);
  background: linear-gradient(145deg, var(--shuo-panel), rgba(12, 16, 31, .69));
  box-shadow: 0 22px 58px rgba(0, 0, 0, .25);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.nova-shuoshuo-overview {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border-radius: 20px;
  overflow: hidden;
}

.nova-shuoshuo-overview > div {
  min-width: 0;
  padding: 21px 25px;
}

.nova-shuoshuo-overview > div + div {
  border-left: 1px solid rgba(231, 205, 218, .09);
}

.nova-shuoshuo-overview b,
.nova-shuoshuo-overview span,
.nova-shuoshuo-overview small {
  display: block;
}

.nova-shuoshuo-overview b {
  overflow: hidden;
  color: var(--shuo-text);
  font-size: clamp(20px, 2.1vw, 28px);
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nova-shuoshuo-overview span {
  margin-top: 4px;
  color: var(--shuo-rose-soft);
  font-size: 10px;
  letter-spacing: .16em;
}

.nova-shuoshuo-overview small {
  margin-top: 6px;
  color: var(--shuo-muted);
  font-size: 12px;
}

.nova-shuoshuo-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(250px, 320px);
  align-items: start;
  gap: clamp(24px, 3vw, 38px);
  margin-top: 38px;
  scroll-margin-top: 94px;
}

.nova-shuoshuo-stream,
.nova-shuoshuo-sidebar {
  min-width: 0;
}

.nova-shuoshuo-month + .nova-shuoshuo-month {
  margin-top: 48px;
}

.nova-shuoshuo-month-head {
  display: grid;
  grid-template-columns: auto auto 1fr;
  align-items: baseline;
  gap: 10px;
  margin: 0 0 18px 38px;
}

.nova-shuoshuo-month-head span {
  color: var(--shuo-rose-soft);
  font-size: 12px;
  letter-spacing: .14em;
}

.nova-shuoshuo-month-head h2 {
  margin: 0;
  color: var(--shuo-text);
  font: 500 24px/1.2 "Noto Serif SC", serif;
}

.nova-shuoshuo-month-head small {
  justify-self: end;
  color: var(--shuo-muted);
  font-size: 10px;
  letter-spacing: .15em;
}

.nova-shuoshuo-month-flow {
  position: relative;
  padding-left: 38px;
}

.nova-shuoshuo-month-flow::before {
  content: "";
  position: absolute;
  top: 10px;
  bottom: 10px;
  left: 8px;
  width: 1px;
  background: linear-gradient(180deg, rgba(211, 127, 157, .55), rgba(173, 133, 167, .09));
}

.nova-shuoshuo-card {
  position: relative;
  min-height: 0;
  padding: 23px 25px 18px;
  border-radius: 18px;
  transition: transform .25s ease, border-color .25s ease, background .25s ease;
}

.nova-shuoshuo-card + .nova-shuoshuo-card {
  margin-top: 16px;
}

.nova-shuoshuo-card:hover {
  transform: translateY(-2px);
  border-color: rgba(216, 137, 167, .3);
  background: linear-gradient(145deg, rgba(27, 29, 50, .82), rgba(14, 17, 32, .75));
}

.nova-shuoshuo-node {
  position: absolute;
  top: 28px;
  left: -36px;
  width: 11px;
  height: 11px;
  border: 2px solid rgba(232, 192, 207, .72);
  border-radius: 50%;
  background: #121526;
  box-shadow: 0 0 0 5px rgba(180, 91, 126, .08);
}

.nova-shuoshuo-card.is-latest .nova-shuoshuo-node {
  background: var(--shuo-rose);
  box-shadow: 0 0 0 5px rgba(193, 106, 140, .12), 0 0 16px rgba(211, 124, 157, .32);
}

.nova-shuoshuo-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}

.nova-shuoshuo-card-head time {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.nova-shuoshuo-card-head time b {
  color: var(--shuo-secondary);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: .1em;
}

.nova-shuoshuo-card-head time span,
.nova-shuoshuo-latest-mark {
  color: var(--shuo-muted);
  font-size: 10px;
  letter-spacing: .13em;
}

.nova-shuoshuo-latest-mark {
  color: var(--shuo-rose-soft);
}

.nova-shuoshuo-card-body {
  margin-top: 14px;
  color: var(--shuo-text);
  font-size: 16px;
  line-height: 1.9;
  overflow-wrap: anywhere;
}

.nova-shuoshuo-card-body > :first-child {
  margin-top: 0;
}

.nova-shuoshuo-card-body > :last-child {
  margin-bottom: 0;
}

.nova-shuoshuo-gallery {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 17px;
  overflow: hidden;
  border-radius: 14px;
}

.nova-shuoshuo-gallery--1 {
  grid-template-columns: minmax(0, 1fr);
}

.nova-shuoshuo-gallery img,
.nova-shuoshuo-card-body img {
  display: block;
  width: 100%;
  max-height: 560px;
  object-fit: cover;
  border-radius: 12px;
}

.nova-shuoshuo-gallery:not(.nova-shuoshuo-gallery--1) img {
  height: clamp(150px, 20vw, 250px);
}

.nova-shuoshuo-card-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  margin-top: 17px;
  color: var(--shuo-muted);
  font-size: 12px;
}

.nova-shuoshuo-card-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.nova-shuoshuo-card-tags span,
.nova-shuoshuo-tags span {
  padding: 5px 10px;
  border: 1px solid rgba(214, 169, 188, .12);
  border-radius: 999px;
  background: rgba(190, 118, 146, .08);
  color: var(--shuo-secondary);
  font-size: 11px;
}

.nova-shuoshuo-like {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 15px;
  padding: 5px 9px 5px 0;
  border: 0;
  background: transparent;
  color: var(--shuo-muted);
  cursor: pointer;
  transition: color .2s ease, transform .2s ease;
}

.nova-shuoshuo-like:hover {
  color: var(--shuo-rose-soft);
  transform: translateY(-1px);
}

.nova-shuoshuo-like.is-liked {
  color: var(--shuo-rose);
}

.nova-shuoshuo-like span {
  font-size: 18px;
}

.nova-shuoshuo-like b {
  font-size: 12px;
  font-weight: 500;
}

.nova-shuoshuo-sidebar {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.nova-shuoshuo-side-card {
  padding: 23px 24px;
  border-radius: 18px;
}

.nova-shuoshuo-side-card h2 {
  margin: 7px 0 19px;
  color: var(--shuo-text);
  font: 500 19px/1.3 "Noto Serif SC", serif;
}

.nova-shuoshuo-mood strong,
.nova-shuoshuo-mood time {
  display: block;
}

.nova-shuoshuo-mood strong {
  color: var(--shuo-secondary);
  font-size: 14px;
}

.nova-shuoshuo-mood time {
  margin-top: 5px;
  color: var(--shuo-rose-soft);
  font-size: 11px;
  letter-spacing: .08em;
}

.nova-shuoshuo-mood > p:last-child {
  margin: 15px 0 0;
  color: var(--shuo-secondary);
  font-size: 13px;
  line-height: 1.75;
  overflow-wrap: anywhere;
}

.nova-shuoshuo-archive nav {
  display: grid;
  gap: 5px;
}

.nova-shuoshuo-archive-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 11px;
  border-radius: 9px;
  color: var(--shuo-secondary);
  font-size: 13px;
  transition: color .2s ease, background .2s ease, transform .2s ease;
}

.nova-shuoshuo-archive-link:hover {
  color: var(--shuo-text);
  background: rgba(196, 110, 144, .09);
  transform: translateX(3px);
}

.nova-shuoshuo-archive-link b {
  color: var(--shuo-rose-soft);
  font-size: 11px;
  font-weight: 500;
}

.nova-shuoshuo-tags > div {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.nova-shuoshuo-continuation {
  margin: 37px 0 0 38px;
  text-align: center;
  color: var(--shuo-muted);
}

.nova-shuoshuo-continuation::before {
  content: "✦";
  display: block;
  margin-bottom: 8px;
  color: var(--shuo-rose);
  font-size: 12px;
}

.nova-shuoshuo-continuation span {
  font-size: 10px;
  letter-spacing: .25em;
}

.nova-shuoshuo-continuation p {
  margin: 5px 0 0;
  font: 400 13px/1.6 "Noto Serif SC", serif;
}

.nova-shuoshuo-comments {
  margin-top: clamp(54px, 7vw, 86px);
  padding: clamp(24px, 4vw, 42px);
  border-radius: 22px;
}

.nova-shuoshuo-comments > header {
  margin-bottom: 24px;
}

.nova-shuoshuo-comments > header span {
  color: var(--shuo-rose-soft);
  font-size: 11px;
  letter-spacing: .22em;
}

.nova-shuoshuo-comments > header h2 {
  margin: 7px 0 0;
  color: var(--shuo-text);
  font: 500 25px/1.3 "Noto Serif SC", serif;
}

.nova-shuoshuo-comments #post-comment {
  margin: 0;
}

.nova-shuoshuo-comments .comment-head {
  display: none;
}

.nova-shuoshuo-empty {
  padding: 64px 28px;
  border: 1px dashed var(--shuo-border);
  border-radius: 18px;
  text-align: center;
  color: var(--shuo-secondary);
}

.nova-shuoshuo-empty span {
  color: var(--shuo-rose-soft);
  font-size: 11px;
  letter-spacing: .2em;
}

@media (min-width: 1081px) and (min-height: 760px) {
  .nova-shuoshuo-sidebar {
    position: sticky;
    top: 92px;
  }
}

html[data-theme="light"] body.nova-shuoshuo-route #body-wrap {
  background: #e9e5ea;
}

html[data-theme="light"] body.nova-shuoshuo-route footer#footer {
  border-top-color: rgba(165, 83, 112, .14);
  background: linear-gradient(180deg, #ddd9e0, #d3d1da);
  color: #5d5662;
}

[data-theme="light"] .nova-shuoshuo-page {
  background:
    radial-gradient(circle at 78% 37%, rgba(145, 107, 155, .13), transparent 31%),
    radial-gradient(circle at 12% 76%, rgba(178, 110, 135, .10), transparent 25%),
    linear-gradient(180deg, #d9d7e1 0, #ece8ed 36%, #e5e1e7 100%);
}

[data-theme="light"] .nova-shuoshuo-hero {
  color: #fff;
}

[data-theme="light"] .nova-shuoshuo-hero-shade {
  background: linear-gradient(180deg, rgba(4, 7, 16, .14), rgba(6, 9, 18, .08) 59%, #d9d7e1 100%);
}

[data-theme="light"] .nova-shuoshuo-hero-copy h1,
[data-theme="light"] .nova-shuoshuo-hero-copy p,
[data-theme="light"] .nova-shuoshuo-hero-copy > span,
[data-theme="light"] .nova-shuoshuo-hero-copy a {
  color: #f9edf2;
}

[data-theme="light"] .nova-shuoshuo-overview,
[data-theme="light"] .nova-shuoshuo-card,
[data-theme="light"] .nova-shuoshuo-side-card,
[data-theme="light"] .nova-shuoshuo-comments {
  background: linear-gradient(145deg, rgba(252, 249, 251, .82), rgba(238, 233, 240, .74));
  box-shadow: 0 18px 45px rgba(75, 57, 75, .10);
}

[data-theme="light"] .nova-shuoshuo-card:hover {
  background: linear-gradient(145deg, rgba(255, 252, 254, .9), rgba(240, 233, 241, .82));
}

[data-theme="light"] .nova-shuoshuo-node {
  background: #eee9ee;
}

@media (max-width: 1080px) {
  .nova-shuoshuo-body {
    width: min(920px, calc(100% - 40px));
  }

  .nova-shuoshuo-layout {
    grid-template-columns: minmax(0, 1fr) 260px;
  }
}

@media (max-width: 820px) {
  .nova-shuoshuo-hero {
    min-height: 500px;
  }

  .nova-shuoshuo-overview {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .nova-shuoshuo-overview > div:nth-child(3) {
    border-left: 0;
    border-top: 1px solid rgba(231, 205, 218, .09);
  }

  .nova-shuoshuo-overview > div:nth-child(4) {
    border-top: 1px solid rgba(231, 205, 218, .09);
  }

  .nova-shuoshuo-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .nova-shuoshuo-sidebar {
    position: static;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .nova-shuoshuo-tags {
    grid-column: 1 / -1;
  }
}

@media (max-width: 560px) {
  .nova-shuoshuo-hero {
    min-height: 460px;
    background-position: 59% 50%;
  }

  .nova-shuoshuo-hero-copy h1 {
    font-size: 52px;
  }

  .nova-shuoshuo-hero-copy > span {
    font-size: 14px;
    line-height: 1.8;
  }

  .nova-shuoshuo-body {
    width: calc(100% - 28px);
    margin-top: -42px;
  }

  .nova-shuoshuo-overview > div {
    padding: 17px 15px;
  }

  .nova-shuoshuo-overview b {
    font-size: 18px;
  }

  .nova-shuoshuo-layout {
    margin-top: 28px;
  }

  .nova-shuoshuo-month-head {
    margin-left: 24px;
  }

  .nova-shuoshuo-month-head small {
    display: none;
  }

  .nova-shuoshuo-month-flow {
    padding-left: 24px;
  }

  .nova-shuoshuo-month-flow::before {
    left: 5px;
  }

  .nova-shuoshuo-node {
    left: -23px;
  }

  .nova-shuoshuo-card {
    padding: 20px 18px 16px;
  }

  .nova-shuoshuo-card-body {
    font-size: 15px;
  }

  .nova-shuoshuo-gallery {
    grid-template-columns: minmax(0, 1fr);
  }

  .nova-shuoshuo-gallery:not(.nova-shuoshuo-gallery--1) img {
    height: auto;
    max-height: 420px;
  }

  .nova-shuoshuo-sidebar {
    grid-template-columns: minmax(0, 1fr);
  }

  .nova-shuoshuo-tags {
    grid-column: auto;
  }

  .nova-shuoshuo-continuation {
    margin-left: 24px;
  }

  .nova-shuoshuo-comments {
    padding: 22px 16px;
  }
}

body.nova-tag-route{color:var(--nova-tag-text);background:var(--nova-tag-bg)}
body.nova-tag-route #body-wrap{overflow:clip;background:radial-gradient(circle at 80% 8%,rgba(193,91,134,.07),transparent 30%),radial-gradient(circle at 16% 28%,rgba(103,125,145,.05),transparent 34%),linear-gradient(180deg,#091324 0%,#080f1c 52%,#070c17 100%)}
body.nova-tag-route #page-header.nova-tag-hero{position:relative;height:clamp(370px,40vh,440px);overflow:hidden;background-position:center 48%!important;background-size:cover!important;background-repeat:no-repeat!important}
body.nova-tag-route #page-header.nova-tag-hero::before{content:"";position:absolute;z-index:0;inset:0;background:linear-gradient(90deg,rgba(7,12,25,.42),rgba(7,12,25,.08) 62%,rgba(7,12,25,.2)),linear-gradient(180deg,rgba(5,10,22,.12),transparent 58%,rgba(8,14,27,.56))}
body.nova-tag-route #page-header.nova-tag-hero::after{content:"";position:absolute;z-index:1;inset:auto 0 0;height:34%;pointer-events:none;background:linear-gradient(180deg,transparent,var(--nova-tag-bg))}
body.nova-tag-route #page-header.nova-tag-hero #nav{z-index:4;background:transparent;box-shadow:none}
.nova-tag-hero-content{position:absolute!important;z-index:2;top:53%!important;right:20px;left:20px;display:flex;align-items:center;flex-direction:column;transform:translateY(-50%)!important;color:#f7eff4;text-align:center}
.nova-tag-eyebrow{margin:0 0 14px;color:#e18ca8;font-size:11px;letter-spacing:.27em}
.nova-tag-title{margin:0;color:#f6e9ef;font:500 clamp(46px,4.2vw,66px)/1.08 "Noto Serif SC","Songti SC",serif;letter-spacing:.12em;text-shadow:0 10px 32px rgba(0,0,0,.25)}
.nova-tag-description{max-width:680px;margin:17px auto 0;color:rgba(246,238,243,.78);font-size:14px;line-height:1.8;letter-spacing:.04em}
.nova-tag-scroll-hint{display:inline-flex;align-items:center;gap:12px;margin-top:22px;color:rgba(244,228,237,.6);font-size:10px;letter-spacing:.18em}
.nova-tag-scroll-hint::before,.nova-tag-scroll-hint::after{content:"";width:40px;height:1px;background:linear-gradient(90deg,transparent,rgba(220,124,155,.68))}
.nova-tag-scroll-hint::after{transform:rotate(180deg)}
body.nova-tag-route main.nova-tag-content{position:relative;z-index:3;display:block;width:100%;max-width:none;margin:0;padding:0 0 clamp(60px,7vw,90px)}
body.nova-tag-route main.nova-tag-content::before{content:"";position:absolute;z-index:-1;inset:0;pointer-events:none;background:url("/img/guidang.webp") center top/cover no-repeat;opacity:.03;filter:blur(36px) saturate(.58);mask-image:linear-gradient(180deg,#000,transparent 43%);-webkit-mask-image:linear-gradient(180deg,#000,transparent 43%)}
.nova-tag-summary{position:relative;z-index:5;display:grid;width:min(1280px,calc(100% - 64px));margin:-38px auto 0;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--nova-tag-line);border-radius:20px;background:linear-gradient(145deg,rgba(15,23,43,.9),rgba(9,16,31,.84));box-shadow:0 24px 65px rgba(0,0,0,.24);backdrop-filter:blur(20px)}
.nova-tag-summary>div{position:relative;display:flex;min-height:88px;padding:18px 24px;justify-content:center;flex-direction:column;gap:3px}
.nova-tag-summary>div+div::before{content:"";position:absolute;top:20px;bottom:20px;left:0;width:1px;background:var(--nova-tag-line)}
.nova-tag-summary strong{overflow:hidden;color:var(--nova-tag-text);font:500 23px/1.1 Georgia,serif;text-overflow:ellipsis;white-space:nowrap}
.nova-tag-summary span{color:var(--nova-tag-accent);font-size:10px;letter-spacing:.14em}
.nova-tag-summary small{color:var(--nova-tag-muted);font-size:12px}
.nova-tag-layout{display:grid;width:min(1280px,calc(100% - 64px));margin:42px auto 0;grid-template-columns:minmax(0,1.72fr) minmax(300px,.82fr);align-items:start;gap:clamp(26px,3vw,38px)}
.nova-tag-main,.nova-tag-side-card{min-width:0;border:1px solid var(--nova-tag-line);background:linear-gradient(145deg,rgba(10,16,31,.84),rgba(8,13,26,.76));box-shadow:0 22px 62px rgba(0,0,0,.2);backdrop-filter:blur(18px)}
.nova-tag-main{padding:28px;border-radius:24px}
.nova-tag-main-header{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:24px;padding-bottom:20px;border-bottom:1px solid var(--nova-tag-line)}
.nova-tag-main-header span,.nova-tag-side-card header span{color:var(--nova-tag-accent);font-size:11px;letter-spacing:.14em}
.nova-tag-main-header h2,.nova-tag-side-card h2{margin:4px 0 0;color:var(--nova-tag-text);font:500 20px/1.4 "Noto Serif SC","Songti SC",serif}
.nova-tag-main-header p{margin:5px 0 0;color:var(--nova-tag-muted);font-size:13px}
.nova-tag-main-header>b{color:var(--nova-tag-muted);font-size:10px;letter-spacing:.12em;white-space:nowrap}
.nova-tag-post-list{display:grid;gap:20px}
.nova-tag-post-card{display:grid;min-height:184px;overflow:hidden;grid-template-columns:clamp(170px,24%,230px) minmax(0,1fr);border:1px solid rgba(224,194,210,.11);border-radius:20px;background:linear-gradient(145deg,rgba(16,23,43,.78),rgba(11,18,35,.72));box-shadow:0 12px 32px rgba(0,0,0,.15);transition:transform .22s,border-color .22s,box-shadow .22s}
.nova-tag-post-card:hover{transform:translateY(-2px);border-color:rgba(205,105,143,.25);box-shadow:0 16px 36px rgba(0,0,0,.2)}
.nova-tag-post-cover{position:relative;display:block;min-height:184px;overflow:hidden;background:#0c1323}
.nova-tag-post-cover::after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,12,27,.02),rgba(8,12,27,.28))}
.nova-tag-post-cover img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:brightness(.75) saturate(.82) contrast(1.04);transition:transform .35s}
.nova-tag-post-card:hover .nova-tag-post-cover img{transform:scale(1.03)}
.nova-tag-post-content{display:flex;min-width:0;padding:20px 22px;flex-direction:column}
.nova-tag-post-meta{display:flex;flex-wrap:wrap;gap:7px 12px;color:var(--nova-tag-muted);font-size:11px}
.nova-tag-post-meta span{color:var(--nova-tag-slate)}
.nova-tag-post-content h2{margin:10px 0 7px;font:500 19px/1.4 "Noto Serif SC","Songti SC",serif}
.nova-tag-post-content h2 a{color:var(--nova-tag-text)}
.nova-tag-post-content p{display:-webkit-box;overflow:hidden;margin:0;color:var(--nova-tag-secondary);font-size:13px;line-height:1.75;-webkit-box-orient:vertical;-webkit-line-clamp:3}
.nova-tag-post-action{display:inline-flex;align-items:center;align-self:flex-start;gap:6px;margin-top:auto;padding-top:10px;color:var(--nova-tag-accent);font-size:12px}
.nova-tag-post-action span{transition:transform .22s}.nova-tag-post-action:hover span{transform:translateX(4px)}
.nova-tag-pagination{margin-top:24px}.nova-tag-pagination #pagination{margin:0}.nova-tag-pagination .pagination{display:flex;justify-content:center;gap:8px}
.nova-tag-pagination .page-number,.nova-tag-pagination .extend{display:grid;width:36px;height:36px;margin:0;place-items:center;border:1px solid var(--nova-tag-line);border-radius:11px;color:var(--nova-tag-secondary);background:rgba(255,255,255,.035)}
.nova-tag-pagination .current{color:#fff;background:var(--nova-tag-accent)}
.nova-tag-sidebar{display:flex;height:auto;min-width:0;align-self:start;flex-direction:column;gap:20px}
.nova-tag-side-card{padding:22px;border-radius:20px}.nova-tag-side-card header{margin-bottom:16px;padding-bottom:15px;border-bottom:1px solid var(--nova-tag-line)}
.nova-tag-profile h3{margin:0;color:var(--nova-tag-text);font:500 25px/1.4 "Noto Serif SC","Songti SC",serif}.nova-tag-profile>p{margin:9px 0 15px;color:var(--nova-tag-secondary);font-size:13px;line-height:1.75}
.nova-tag-profile>div{display:flex;justify-content:space-between;color:var(--nova-tag-muted);font-size:11px}.nova-tag-profile>a,.nova-tag-map-link{display:inline-flex;margin-top:16px;color:var(--nova-tag-accent);font-size:12px}
.nova-tag-reading-path nav{display:grid}.nova-tag-reading-link{display:grid;padding:10px 6px;grid-template-columns:26px minmax(0,1fr) auto;align-items:center;gap:8px;border-radius:9px;color:var(--nova-tag-secondary);font-size:11px}
.nova-tag-reading-link span{color:var(--nova-tag-accent);font:500 10px Georgia,serif}.nova-tag-reading-link strong{font-weight:500;text-overflow:ellipsis;white-space:nowrap}.nova-tag-reading-link time{color:var(--nova-tag-muted);font-size:9px}
.nova-tag-reading-link:hover{color:var(--nova-tag-text);background:rgba(197,99,137,.07)}
.nova-tag-related>div{display:flex;flex-wrap:wrap;gap:8px}.nova-tag-related-link{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border:1px solid var(--nova-tag-line);border-radius:999px;color:var(--nova-tag-secondary);background:rgba(255,255,255,.035);font-size:11px}.nova-tag-related-link span{color:var(--nova-tag-muted);font-size:9px}
body.nova-tag-route footer#footer{margin:0;border-top:1px solid rgba(199,97,132,.14);background:linear-gradient(180deg,rgba(12,20,39,.88),#0b162a)}
html[data-theme="light"] body.nova-tag-route #body-wrap{background:radial-gradient(circle at 80% 8%,rgba(189,96,125,.06),transparent 30%),radial-gradient(circle at 16% 28%,rgba(112,130,144,.045),transparent 34%),linear-gradient(180deg,#eeebf1,#e7e5ec)}
html[data-theme="light"] body.nova-tag-route #page-header.nova-tag-hero::after{background:linear-gradient(180deg,rgba(8,13,27,.03),rgba(8,13,27,.02) 62%,rgba(105,98,122,.08) 80%,rgba(211,207,218,.3) 92%,var(--nova-tag-bg))}
html[data-theme="light"] .nova-tag-main,html[data-theme="light"] .nova-tag-side-card,html[data-theme="light"] .nova-tag-summary{border-color:rgba(255,255,255,.56);background:linear-gradient(145deg,rgba(255,254,255,.83),rgba(244,241,247,.75));box-shadow:0 22px 60px rgba(53,43,62,.1)}
html[data-theme="light"] .nova-tag-post-card{border-color:rgba(75,62,83,.1);background:linear-gradient(145deg,rgba(255,255,255,.85),rgba(246,243,248,.78));box-shadow:0 12px 32px rgba(53,43,62,.08)}
html[data-theme="light"] body.nova-tag-route footer#footer{background:linear-gradient(180deg,rgba(224,221,230,.92),#d0d2dd);color:#514c59}
@media(max-width:1180px){.nova-tag-summary,.nova-tag-layout{width:calc(100% - 40px)}.nova-tag-layout{grid-template-columns:minmax(0,1fr) minmax(280px,.65fr);gap:clamp(26px,3vw,34px)}.nova-tag-main{padding:22px}}
@media(max-width:1024px){body.nova-tag-route #page-header.nova-tag-hero{height:350px}.nova-tag-summary{grid-template-columns:1fr 1fr}.nova-tag-summary>div:nth-child(3)::before{display:none}.nova-tag-layout{display:block;margin-top:28px}.nova-tag-sidebar{position:static;margin-top:22px}}
@media(max-width:768px){.nova-tag-summary,.nova-tag-layout{width:calc(100% - 28px)}}
@media(max-width:560px){.nova-tag-title{font-size:48px}.nova-tag-description{font-size:12px}.nova-tag-summary>div{min-height:74px;padding:13px}.nova-tag-summary strong{font-size:18px}.nova-tag-main{padding:14px;border-radius:18px}.nova-tag-main-header{align-items:flex-start;flex-direction:column;gap:8px}.nova-tag-post-card{display:block;min-height:0}.nova-tag-post-cover{min-height:170px;aspect-ratio:16/9}.nova-tag-post-content{padding:18px 16px}.nova-tag-post-content h2{font-size:17px}}
@media(max-width:390px){.nova-tag-summary{grid-template-columns:1fr}.nova-tag-summary>div+div::before{top:0;right:13px;bottom:auto;left:13px;width:auto;height:1px}.nova-tag-post-meta{font-size:10px}.nova-tag-reading-link{grid-template-columns:24px minmax(0,1fr)}.nova-tag-reading-link time{display:none}}
@media(prefers-reduced-motion:reduce){.nova-tag-post-card,.nova-tag-post-cover img,.nova-tag-post-action span{transition:none!important}.nova-tag-post-card:hover,.nova-tag-post-card:hover .nova-tag-post-cover img,.nova-tag-post-action:hover span{transform:none!important}}

/* Topic reading assistant: scoped to tag detail routes only. */
.nova-tag-current-title {
  display: -webkit-box;
  overflow: hidden;
  margin: 0;
  color: var(--nova-tag-text);
  font: 500 15px/1.55 "Noto Serif SC", "Songti SC", serif;
  overflow-wrap: anywhere;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.nova-tag-current-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 14px;
  color: var(--nova-tag-muted);
  font-size: 10px;
  letter-spacing: .08em;
}

.nova-tag-current-percent {
  text-align: right;
}

.nova-tag-progress {
  height: 3px;
  margin-top: 10px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(221, 190, 207, .09);
}

.nova-tag-progress i {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--nova-tag-accent), var(--nova-tag-slate));
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform .28s ease;
}

.nova-tag-current-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 15px;
}

.nova-tag-current-actions a {
  color: var(--nova-tag-muted);
  font-size: 10px;
  transition: color .2s ease;
}

.nova-tag-current-actions a:first-child,
.nova-tag-current-actions a:hover {
  color: var(--nova-tag-accent);
}

.nova-tag-reading-link strong {
  display: -webkit-box;
  overflow: hidden;
  line-height: 1.5;
  overflow-wrap: anywhere;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.nova-tag-reading-link i {
  width: 6px;
  height: 6px;
  border: 1px solid rgba(207, 155, 180, .28);
  border-radius: 50%;
  transition: border-color .2s ease, background .2s ease, box-shadow .2s ease;
}

.nova-tag-reading-link.is-current {
  color: var(--nova-tag-text);
  background: rgba(205, 105, 143, .09);
}

.nova-tag-reading-link.is-current i {
  border-color: var(--nova-tag-accent);
  background: var(--nova-tag-accent);
  box-shadow: 0 0 0 4px rgba(205, 105, 143, .08);
}

.nova-tag-reading-link.is-complete {
  color: var(--nova-tag-muted);
}

.nova-tag-reading-link.is-complete i {
  border-color: rgba(205, 105, 143, .34);
  background: rgba(205, 105, 143, .28);
}

.nova-tag-post-card {
  scroll-margin-top: 104px;
}

.nova-tag-post-card.is-current-note {
  border-color: rgba(205, 105, 143, .3);
  box-shadow: 0 14px 34px rgba(0, 0, 0, .18);
}

html[data-theme="light"] .nova-tag-progress {
  background: rgba(105, 76, 97, .11);
}

html[data-theme="light"] .nova-tag-reading-link.is-current {
  background: rgba(179, 83, 119, .09);
}

html[data-theme="light"] .nova-tag-post-card.is-current-note {
  border-color: rgba(179, 83, 119, .3);
  box-shadow: 0 13px 30px rgba(67, 48, 66, .1);
}

@media (min-width:1101px) and (min-height:850px) {
  .nova-tag-sidebar {
    position: sticky;
    top: 88px;
    max-height: calc(100vh - 112px);
    overflow-x: hidden;
    overflow-y: auto;
    padding-right: 4px;
    scrollbar-color: rgba(205, 105, 143, .22) transparent;
    scrollbar-width: thin;
  }
}

@media (max-width:1100px), (max-height:849px) {
  .nova-tag-sidebar {
    position: static;
    max-height: none;
    overflow: visible;
  }
}

@media (max-width:768px) {
  .nova-tag-current-note {
    order: 2;
  }

  .nova-tag-reading-path {
    order: 3;
  }

  .nova-tag-related {
    order: 4;
  }
}

@media (prefers-reduced-motion:reduce) {
  .nova-tag-progress i,
  .nova-tag-reading-link i {
    transition: none !important;
  }
}

/* Tags overview shares the detail-page palette and keeps its own compact index. */
.nova-tags-overview {
  min-height: 60vh;
}

.nova-tags-index {
  width: min(1120px, calc(100% - 64px));
  margin: 42px auto 0;
  padding: 30px;
  border: 1px solid var(--nova-tag-line);
  border-radius: 24px;
  background: linear-gradient(145deg, rgba(10, 16, 31, .84), rgba(8, 13, 26, .76));
  box-shadow: 0 22px 62px rgba(0, 0, 0, .2);
}

.nova-tags-index > header {
  margin-bottom: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--nova-tag-line);
}

.nova-tags-index > header span {
  color: var(--nova-tag-accent);
  font-size: 11px;
  letter-spacing: .14em;
}

.nova-tags-index > header h2 {
  margin: 4px 0 0;
  color: var(--nova-tag-text);
  font: 500 22px/1.4 "Noto Serif SC", "Songti SC", serif;
}

.nova-tags-index > header p {
  margin: 5px 0 0;
  color: var(--nova-tag-muted);
  font-size: 13px;
}

.nova-tags-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.nova-tags-card {
  display: grid;
  min-width: 0;
  padding: 20px;
  grid-template-columns: 34px minmax(0, 1fr) auto 18px;
  align-items: center;
  gap: 14px;
  border: 1px solid rgba(224, 194, 210, .11);
  border-radius: 18px;
  color: var(--nova-tag-text);
  background: linear-gradient(145deg, rgba(16, 23, 43, .78), rgba(11, 18, 35, .72));
  transition: transform .22s ease, border-color .22s ease;
}

.nova-tags-card:hover {
  transform: translateY(-2px);
  border-color: rgba(205, 105, 143, .28);
}

.nova-tags-card > span,
.nova-tags-card > i {
  color: var(--nova-tag-accent);
  font: 500 11px Georgia, serif;
}

.nova-tags-card h2 {
  margin: 0;
  color: var(--nova-tag-text);
  font: 500 18px/1.4 "Noto Serif SC", "Songti SC", serif;
}

.nova-tags-card p {
  display: -webkit-box;
  overflow: hidden;
  margin: 5px 0 0;
  color: var(--nova-tag-secondary);
  font-size: 12px;
  line-height: 1.65;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.nova-tags-card strong {
  color: var(--nova-tag-text);
  font: 500 18px/1 Georgia, serif;
  white-space: nowrap;
}

.nova-tags-card strong small {
  color: var(--nova-tag-muted);
  font-size: 9px;
}

html[data-theme="light"] .nova-tags-index,
html[data-theme="light"] .nova-tags-card {
  border-color: rgba(75, 62, 83, .1);
  background: linear-gradient(145deg, rgba(255, 255, 255, .85), rgba(246, 243, 248, .78));
  box-shadow: 0 12px 32px rgba(53, 43, 62, .08);
}

@media (max-width: 768px) {
  .nova-tags-index {
    width: calc(100% - 28px);
    margin-top: 28px;
    padding: 18px;
  }

  .nova-tags-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 420px) {
  .nova-tags-card {
    padding: 16px;
    grid-template-columns: 26px minmax(0, 1fr) 16px;
  }

  .nova-tags-card strong {
    display: none;
  }
}

body.nova-template-route {
  overflow-x: clip;
  color: var(--atlas-text);
  background: var(--atlas-bg);
}

body.nova-template-route #body-wrap {
  width: 100%;
  min-width: 0;
  background: var(--atlas-bg);
}

body.nova-template-route #page-header.nova-template-nav-header {
  position: absolute;
  z-index: 20;
  inset: 0 0 auto;
  width: 100%;
  height: 70px;
  min-height: 0;
  background: transparent;
}

body.nova-template-route #page-header.nova-template-nav-header::before {
  display: none;
}

body.nova-template-route #page-header.nova-template-nav-header #nav {
  height: 70px;
  background: linear-gradient(180deg, rgba(5, 9, 19, .58), transparent);
  box-shadow: none;
}

body.nova-template-route #page-header.nova-template-nav-header.nav-fixed #nav {
  background: rgba(7, 11, 22, .78);
  border-bottom: 1px solid rgba(255, 255, 255, .06);
  backdrop-filter: blur(18px);
}

body.nova-template-route main#content-inner.nova-template-shell {
  display: block;
  flex: 1 0 auto;
  width: 100%;
  max-width: none;
  margin: 0;
  padding: 0;
  background: transparent;
}

.nova-template-page {
  min-height: 100vh;
  background:
    radial-gradient(circle at 80% 34%, rgba(78, 98, 120, .1), transparent 30%),
    radial-gradient(circle at 13% 72%, rgba(181, 86, 123, .07), transparent 26%),
    linear-gradient(180deg, #0b1427 0, var(--atlas-bg) 37%, #070c17 100%);
}

.nova-template-hero {
  position: relative;
  display: grid;
  min-height: clamp(410px, 51vh, 545px);
  place-items: center;
  overflow: hidden;
  background: url("/img/moban.webp") center 48% / cover no-repeat;
  isolation: isolate;
}

.nova-template-hero::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(5, 10, 22, .36), rgba(5, 10, 22, .04) 56%, rgba(5, 10, 22, .23)),
    linear-gradient(180deg, rgba(5, 9, 19, .08), transparent 58%, rgba(7, 13, 25, .58));
}

.nova-template-hero-shade {
  position: absolute;
  z-index: -1;
  inset: 0;
  background: linear-gradient(180deg, transparent 62%, #0b1427 100%);
}

.nova-template-hero-copy {
  width: min(760px, calc(100% - 40px));
  margin-top: 38px;
  text-align: center;
  text-shadow: 0 4px 28px rgba(0, 0, 0, .48);
}

.nova-template-hero-copy p,
.nova-template-side-card header span {
  margin: 0;
  color: #e49ab4;
  font: 600 11px/1.4 "Inter", sans-serif;
  letter-spacing: .24em;
}

.nova-template-hero-copy h1 {
  margin: 18px 0 15px;
  color: #f4e8ed;
  font: 500 clamp(50px, 5.5vw, 78px)/1.1 "Noto Serif SC", "Songti SC", serif;
  letter-spacing: .14em;
  transform: translateX(.07em);
}

.nova-template-hero-copy > span {
  display: block;
  color: rgba(248, 241, 245, .82);
  font-size: clamp(14px, 1.35vw, 17px);
  letter-spacing: .08em;
}

.nova-template-hero-copy > a {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-top: 31px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(225, 148, 177, .45);
  color: rgba(247, 230, 237, .8);
  font-size: 10px;
  letter-spacing: .2em;
}

.nova-template-hero-copy > a i {
  font-style: normal;
}

.nova-template-content {
  position: relative;
  z-index: 2;
  width: min(1280px, calc(100% - 64px));
  margin: -52px auto 0;
  padding-bottom: clamp(50px, 6vw, 82px);
  scroll-margin-top: 84px;
}

.nova-template-summary,
.nova-template-module,
.nova-template-side-card {
  border: 1px solid var(--atlas-border);
  background: linear-gradient(145deg, var(--atlas-panel), rgba(9, 16, 31, .74));
  box-shadow: 0 20px 55px rgba(0, 0, 0, .2);
  backdrop-filter: blur(18px);
}

.nova-template-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  overflow: hidden;
  border-radius: 19px;
}

.nova-template-summary > div {
  min-width: 0;
  padding: 20px 24px;
}

.nova-template-summary > div + div {
  border-left: 1px solid rgba(224, 192, 209, .09);
}

.nova-template-summary strong,
.nova-template-summary span,
.nova-template-summary small {
  display: block;
}

.nova-template-summary strong {
  overflow: hidden;
  color: var(--atlas-text);
  font: 500 clamp(19px, 2vw, 27px)/1.25 "Noto Serif SC", serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nova-template-summary span {
  margin-top: 4px;
  color: var(--atlas-rose);
  font-size: 10px;
  letter-spacing: .13em;
}

.nova-template-summary small {
  margin-top: 5px;
  color: var(--atlas-muted);
  font-size: 12px;
}

.nova-template-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.65fr) minmax(275px, .72fr);
  align-items: start;
  gap: clamp(24px, 3vw, 36px);
  margin-top: 32px;
}

.nova-template-main,
.nova-template-sidebar {
  min-width: 0;
}

.nova-template-main {
  display: grid;
  gap: 18px;
}

.nova-template-module {
  display: grid;
  grid-template-columns: clamp(180px, 29%, 235px) minmax(0, 1fr);
  gap: 24px;
  min-height: 230px;
  padding: 26px;
  border-radius: 20px;
  scroll-margin-top: 94px;
}

.nova-template-module-cover {
  position: relative;
  min-height: 100%;
  overflow: hidden;
  border: 1px solid rgba(220, 183, 201, .1);
  border-radius: 14px;
  background: #0a1223;
}

.nova-template-module-cover::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(7, 13, 27, .08), rgba(7, 13, 27, .62)),
    linear-gradient(90deg, rgba(16, 24, 40, .2), rgba(130, 57, 101, .08));
}

.nova-template-module-cover img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(.62) saturate(.72) contrast(1.06);
  transition: transform .35s ease;
}

.nova-template-module:hover .nova-template-module-cover img {
  transform: scale(1.025);
}

.nova-template-module-cover span {
  position: absolute;
  z-index: 2;
  right: 14px;
  bottom: 13px;
  left: 14px;
  color: rgba(242, 222, 231, .76);
  font-size: 10px;
  letter-spacing: .13em;
}

.nova-template-module-content {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(145px, .62fr) minmax(0, 1.38fr);
  align-items: center;
  gap: 22px;
}

.nova-template-module-intro {
  position: relative;
  min-width: 0;
  padding: 4px 4px 4px 8px;
}

.nova-template-module-number {
  color: var(--atlas-rose);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: .12em;
}

.nova-template-module-symbol {
  display: flex;
  height: 45px;
  align-items: end;
  gap: 5px;
  margin: 14px 0 10px;
}

.nova-template-module-symbol i {
  display: block;
  width: 30px;
  height: 30px;
  border: 1px solid rgba(202, 112, 147, .42);
  background: linear-gradient(145deg, rgba(94, 119, 140, .25), rgba(190, 85, 132, .13));
  transform: rotate(30deg) skew(-4deg);
}

.nova-template-module-symbol i:nth-child(2) {
  height: 38px;
  transform: translateY(-7px) rotate(30deg) skew(-4deg);
}

.nova-template-module-intro h2 {
  margin: 7px 0 2px;
  color: var(--atlas-text);
  font: 500 26px/1.3 "Noto Serif SC", serif;
}

.nova-template-module-intro small {
  color: var(--atlas-rose);
  font-size: 10px;
  letter-spacing: .18em;
}

.nova-template-module-intro p {
  margin: 14px 0 16px;
  color: var(--atlas-secondary);
  font-size: 13px;
  line-height: 1.75;
}

.nova-template-module-intro b {
  display: inline-flex;
  padding: 5px 10px;
  border-radius: 999px;
  color: var(--atlas-secondary);
  background: rgba(255, 255, 255, .045);
  font-size: 10px;
  font-weight: 500;
}

.nova-template-links {
  display: flex;
  min-width: 0;
  flex-direction: column;
  justify-content: center;
  gap: 7px;
}

.nova-template-links > a:not(.nova-template-module-action) {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 13px;
  border: 1px solid rgba(224, 190, 208, .08);
  border-radius: 9px;
  color: var(--atlas-secondary);
  background: rgba(255, 255, 255, .025);
  font-size: 14px;
  transition: transform .2s ease, border-color .2s ease, color .2s ease, background .2s ease;
}

.nova-template-links > a small {
  flex: 0 0 auto;
  color: var(--atlas-muted);
  font-size: 10px;
  letter-spacing: .08em;
}

.nova-template-links > a:not(.nova-template-module-action)::before {
  content: "";
  width: 4px;
  height: 4px;
  flex: 0 0 auto;
  border-radius: 1px;
  background: var(--atlas-rose);
}

.nova-template-links > a span {
  min-width: 0;
  margin-right: auto;
  overflow-wrap: normal;
  word-break: keep-all;
}

.nova-template-links > a i {
  flex: 0 0 auto;
  color: var(--atlas-rose);
  font-style: normal;
}

.nova-template-links > a:not(.nova-template-module-action):hover {
  color: var(--atlas-text);
  border-color: rgba(205, 113, 145, .25);
  background: rgba(199, 104, 141, .06);
  transform: translateX(3px);
}

.nova-template-module-action {
  align-self: flex-end;
  margin-top: 4px;
  color: var(--atlas-rose);
  font-size: 11px;
  text-align: right;
}

.nova-template-sidebar {
  display: flex;
  height: auto;
  min-height: 0;
  align-self: start;
  flex-direction: column;
  gap: 18px;
}

.nova-template-side-card {
  height: auto;
  min-height: 0;
  flex: none;
  padding: 22px;
  border-radius: 18px;
}

.nova-template-side-card header {
  margin-bottom: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(224, 192, 209, .1);
}

.nova-template-side-card header h2 {
  margin: 5px 0 0;
  color: var(--atlas-text);
  font: 500 20px/1.35 "Noto Serif SC", serif;
}

.nova-template-side-card header span {
  font-size: 12px;
}

.nova-template-index nav {
  display: grid;
  gap: 7px;
}

.nova-template-index nav a {
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  padding: 10px;
  border-radius: 9px;
  color: var(--atlas-secondary);
  background: rgba(255, 255, 255, .025);
  font-size: 11px;
  transition: background .2s ease, transform .2s ease;
}

.nova-template-index nav a:hover {
  background: rgba(199, 104, 141, .08);
  transform: translateX(3px);
}

.nova-template-index nav span,
.nova-template-index nav b {
  color: var(--atlas-rose);
  font-size: 10px;
  font-weight: 500;
}

.nova-template-index nav strong {
  font-weight: 500;
}

.nova-template-recent > div {
  display: grid;
  gap: 2px;
}

.nova-template-recent a {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 9px 3px;
  color: var(--atlas-secondary);
  font-size: 13px;
}

.nova-template-recent a + a {
  border-top: 1px solid rgba(224, 192, 209, .07);
}

.nova-template-recent a span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nova-template-recent time {
  color: var(--atlas-muted);
  font-size: 12px;
}

.nova-template-howto {
  height: auto;
  min-height: 0;
  flex: none;
}

.nova-template-howto ol {
  display: grid;
  gap: 19px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.nova-template-howto li {
  position: relative;
  padding-left: 31px;
}

.nova-template-howto li::before {
  content: counter(list-item);
  position: absolute;
  top: 1px;
  left: 0;
  display: grid;
  width: 21px;
  height: 21px;
  place-items: center;
  border-radius: 7px;
  color: var(--atlas-rose);
  background: rgba(199, 104, 141, .1);
  font-size: 9px;
}

.nova-template-howto b,
.nova-template-howto span {
  display: block;
}

.nova-template-howto b {
  color: var(--atlas-secondary);
  font-size: 14px;
  font-weight: 500;
}

.nova-template-howto span {
  margin-top: 4px;
  color: var(--atlas-muted);
  font-size: 12px;
  line-height: 1.65;
}

body.nova-template-route footer#footer {
  width: 100%;
  margin: 0;
  border-top: 1px solid rgba(199, 97, 132, .13);
  background: linear-gradient(180deg, #091020, #070c17);
  color: var(--atlas-secondary);
}

html[data-theme="light"] body.nova-template-route #body-wrap,
html[data-theme="light"] .nova-template-page {
  background:
    radial-gradient(circle at 80% 36%, rgba(105, 119, 132, .08), transparent 30%),
    radial-gradient(circle at 13% 73%, rgba(181, 102, 132, .08), transparent 26%),
    linear-gradient(180deg, #dbd9e3 0, #ece9ee 38%, #e5e3e9 100%);
}

html[data-theme="light"] .nova-template-summary,
html[data-theme="light"] .nova-template-module,
html[data-theme="light"] .nova-template-side-card {
  background: linear-gradient(145deg, rgba(252, 250, 252, .82), rgba(239, 235, 242, .74));
  box-shadow: 0 18px 48px rgba(64, 49, 67, .09);
}

html[data-theme="light"] .nova-template-links > a:not(.nova-template-module-action),
html[data-theme="light"] .nova-template-index nav a {
  background: rgba(95, 73, 99, .035);
}

html[data-theme="light"] body.nova-template-route footer#footer {
  border-top-color: rgba(179, 89, 120, .14);
  background: linear-gradient(180deg, #dcdae2, #d2d1da);
  color: #5c5661;
}

@media (max-width: 1000px) {
  .nova-template-content {
    width: calc(100% - 40px);
  }

  .nova-template-layout {
    grid-template-columns: minmax(0, 1fr) 270px;
    gap: 22px;
  }

  .nova-template-module {
    grid-template-columns: minmax(165px, .58fr) minmax(0, 1.42fr);
    padding: 22px;
  }

  .nova-template-module-content {
    grid-template-columns: minmax(135px, .58fr) minmax(0, 1.42fr);
    gap: 18px;
  }
}

@media (max-width: 780px) {
  .nova-template-content {
    width: calc(100% - 28px);
    margin-top: -40px;
  }

  .nova-template-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .nova-template-summary > div:nth-child(3) {
    border-top: 1px solid rgba(224, 192, 209, .09);
    border-left: 0;
  }

  .nova-template-summary > div:nth-child(4) {
    border-top: 1px solid rgba(224, 192, 209, .09);
  }

  .nova-template-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .nova-template-module {
    grid-template-columns: minmax(0, 1fr);
  }

  .nova-template-module-cover {
    min-height: 210px;
  }

  .nova-template-module-content {
    grid-template-columns: minmax(0, 1fr);
    gap: 14px;
  }

  .nova-template-sidebar {
    position: static;
    height: auto;
    max-height: none;
    overflow: visible;
  }

  .nova-template-howto {
    flex: none;
  }
}

@media (max-width: 560px) {
  .nova-template-hero-copy h1 {
    font-size: 48px;
  }

  .nova-template-hero-copy > span {
    font-size: 13px;
    line-height: 1.8;
  }

  .nova-template-summary > div {
    padding: 16px 14px;
  }

  .nova-template-summary strong {
    font-size: 18px;
  }

  .nova-template-module {
    grid-template-columns: minmax(0, 1fr);
    min-height: 0;
    padding: 19px 16px;
  }

  .nova-template-module-symbol {
    height: 35px;
    margin-block: 10px 7px;
  }

  .nova-template-module-symbol i {
    width: 24px;
    height: 24px;
  }

  .nova-template-module-symbol i:nth-child(2) {
    height: 31px;
  }

  .nova-template-links > a:not(.nova-template-module-action) {
    padding: 11px;
  }

  .nova-template-module-cover {
    min-height: 180px;
  }

  .nova-template-links > a small {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .nova-template-links > a,
  .nova-template-index nav a {
    transition: none;
  }

  .nova-template-links > a:hover,
  .nova-template-index nav a:hover {
    transform: none;
  }

  .nova-template-module-cover img {
    transition: none;
  }

  .nova-template-module:hover .nova-template-module-cover img {
    transform: none;
  }
}

:root {
  --coast-ink: #c3ccd3;
  --coast-muted: #aab7c2;
  --coast-surface: #233749;
  --coast-rule: rgba(216,229,238,.18);
  --coast-glass-border: rgba(216,229,238,.19);
  --coast-glass: linear-gradient(160deg,rgba(134,151,165,.10),rgba(13,23,30,.12));
  --coast-blur: 10px;
  --coast-radius: 12px;
  --coast-font: Inter,"Microsoft YaHei",sans-serif;
  --coast-panel-x: .85%;
  --coast-panel-y: 1.4%;
  --coast-panel-width: 12%;
}

(() => {
  'use strict'
  if (window.__fliexArticleReading) return
  let cleanup = () => {}
  const init = () => {
    const root = document.querySelector('.article-reading-shell')
    if (!root || root.dataset.ready) return
    root.dataset.ready = 'true'
    const links = [...root.querySelectorAll('[data-article-toc]')]
    const chapterById = new Map()
    let activeChapter = null
    links.forEach(link => {
      if (link.classList.contains('article-toc-link--h2')) activeChapter = link.dataset.articleToc
      chapterById.set(link.dataset.articleToc, activeChapter)
    })
    const percent = root.querySelector('[data-article-percent]')
    const rail = root.querySelector('[data-article-progress]')
    const dot = root.querySelector('[data-article-progress-dot]')
    const updateProgress = () => {
      const max = Math.max(1, document.documentElement.scrollHeight - innerHeight)
      const value = Math.max(0, Math.min(100, scrollY / max * 100))
      if (percent) percent.textContent = Math.round(value) + '%'
      if (rail) rail.style.height = value + '%'
      if (dot) dot.style.top = value + '%'
    }
    const headingNodes = links.map(link => document.getElementById(link.dataset.articleToc)).filter(Boolean)
    const setActive = id => {
      const chapter = chapterById.get(id)
      links.forEach(link => {
        const isCurrent = link.dataset.articleToc === id
        link.classList.toggle('is-active', isCurrent)
        link.classList.toggle('is-expanded', link.classList.contains('article-toc-link--h3') && chapterById.get(link.dataset.articleToc) === chapter)
      })
    }
    const updateCurrentHeading = () => {
      let current = headingNodes[0]
      headingNodes.forEach(heading => { if (heading.getBoundingClientRect().top  {})

    const renderMusic = () => {
      const state = window.__fliexMusic?.snapshot()
      if (!state || !music) return
      music.disabled = !state.ready
      music.title = state.ready ? '' : '等待添加歌曲'
      music.setAttribute('aria-label', state.ready ? (state.playing ? '暂停音乐' : '播放音乐') : '暂无可播放音乐')
      music.innerHTML = ''
      if (musicSummary) musicSummary.textContent = state.playing ? state.artist + ' — ' + state.title : state.ready ? 'Music / Ready' : 'Music'
    }
    document.addEventListener('fliex:music', renderMusic)

    const isDark = () => document.documentElement.getAttribute('data-theme') === 'dark'
    const syncTheme = () => {
      const label = isDark() ? '切换到浅色模式' : '切换到深色模式'
      theme.setAttribute('aria-label', label)
      theme.setAttribute('title', label)
    }
    const toggleTheme = () => {
      const next = isDark() ? 'light' : 'dark'
      if (window.btf?.activateDarkMode && window.btf?.activateLightMode) {
        if (next === 'dark') window.btf.activateDarkMode()
        else window.btf.activateLightMode()
        window.btf.saveToLocal?.set('theme', next, 2)
      } else if (document.getElementById('darkmode')) {
        document.getElementById('darkmode').click()
        return
      } else {
        document.documentElement.setAttribute('data-theme', next)
      }
      syncTheme()
    }
    const themeObserver = new MutationObserver(syncTheme)
    themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] })
    syncTheme()

    const onScroll = () => { updateProgress(); updateCurrentHeading() }
    addEventListener('scroll', onScroll, { passive: true })
    top.addEventListener('click', () => scrollTo({ top: 0, behavior: 'smooth' }))
    mobile.addEventListener('click', () => { const open = root.classList.toggle('is-toc-open'); mobile.setAttribute('aria-expanded', String(open)) })
    links.forEach(link => link.addEventListener('click', () => { root.classList.remove('is-toc-open'); mobile.setAttribute('aria-expanded', 'false'); requestAnimationFrame(() => setActive(link.dataset.articleToc)) }))
    search.addEventListener('click', () => window.__fliexOpenSearch?.())
    theme.addEventListener('click', toggleTheme)
    music?.addEventListener('click', () => window.__fliexMusic?.toggle())
    updateProgress(); updateCurrentHeading(); renderMusic()
    window.__fliexMusic?.load()
    cleanup = () => {
      removeEventListener('scroll', onScroll)
      document.removeEventListener('fliex:music', renderMusic)
      themeObserver.disconnect()
      stopSnow()
      delete root.dataset.ready
    }
  }
  window.__fliexArticleReading = { init }
  document.addEventListener('pjax:send', () => cleanup())
  document.addEventListener('pjax:complete', init)
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true }); else init()
})()

(() => {
  'use strict'
  if (window.__fliexOpenSearch) return
  let dialog = null, input = null, results = null, status = null, previousFocus = null, entries = null, loading = null
  const render = () => {
    results.replaceChildren()
    const query = input.value.trim().toLocaleLowerCase()
    if (!entries) return
    if (!query) { status.textContent = '输入关键词，搜索文章、笔记与公开页面。'; return }
    const matches = entries.filter(entry => (entry.title + ' ' + entry.content).toLocaleLowerCase().includes(query)).slice(0, 30)
    status.textContent = matches.length ? '找到 ' + matches.length + ' 条记录' : '没有找到相关记录，试试更短的关键词。'
    matches.forEach(entry => {
      const li = document.createElement('li'), a = document.createElement('a'), text = document.createElement('p')
      a.href = entry.url; a.textContent = entry.title
      text.textContent = entry.content.slice(0, 100)
      li.append(a, text); results.append(li)
    })
  }
  const load = () => {
    if (entries) return Promise.resolve()
    if (loading) return loading
    status.textContent = '正在载入搜索索引…'
    loading = (async () => {
      const response = await fetch('/search.xml')
      if (!response.ok) throw new Error('搜索索引暂时不可用')
      const xml = new DOMParser().parseFromString(await response.text(), 'application/xml')
      if (xml.querySelector('parsererror')) throw new Error('搜索索引格式异常')
      entries = [...xml.querySelectorAll('entry')].map(entry => {
        const raw = entry.querySelector('content')?.textContent || ''
        const fragment = new DOMParser().parseFromString(raw, 'text/html')
        return { title: entry.querySelector('title')?.textContent || '', url: entry.querySelector('url')?.textContent || '', content: fragment.body.textContent.replace(/\s+/g, ' ').trim() }
      }).filter(entry => entry.title && /^\/(?!\/)/.test(entry.url))
      render()
    })().catch(error => { status.textContent = error.message + '，关闭后重新打开可重试。' }).finally(() => { loading = null })
    return loading
  }
  const close = () => { if (dialog?.open) dialog.close() }
  const open = () => {
    if (!dialog) {
      dialog = document.createElement('dialog'); dialog.className = 'coast-search-dialog'
      dialog.setAttribute('aria-labelledby', 'coast-search-title')
      dialog.innerHTML = 'Search×搜索文章、笔记与项目'
      document.body.appendChild(dialog)
      input = dialog.querySelector('input'); results = dialog.querySelector('ul'); status = dialog.querySelector('[role=status]')
      input.addEventListener('input', render)
      dialog.querySelector('button').addEventListener('click', close)
      dialog.addEventListener('close', () => { if (previousFocus?.isConnected) previousFocus.focus() })
      dialog.addEventListener('click', event => {
        if (event.target.closest('a')) close()
        if (event.target === dialog) {
          const rect = dialog.getBoundingClientRect()
          if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) close()
        }
      })
      dialog.addEventListener('keydown', event => {
        if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(); return }
        if (event.key === 'Enter' && event.target === input) { const link = results.querySelector('a'); if (link) link.click() }
      })
    }
    if (dialog.open) { input.focus(); return }
    previousFocus = document.activeElement
    dialog.showModal(); input.focus(); render(); load()
  }
  window.__fliexOpenSearch = open
  document.addEventListener('keydown', event => {
    if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); open() }
  })
  document.addEventListener('click', event => {
    if (!event.target.closest('#search-button > .search')) return
    event.preventDefault(); event.stopImmediatePropagation(); open()
  }, true)
  document.addEventListener('pjax:send', close)
})()

(() => {
  'use strict'

  if (window.__novaDecorativeScriptsScheduled) return
  window.__novaDecorativeScriptsScheduled = true

  const CDN_ROOT = 'https://cdn.jsdelivr.net/npm/butterfly-extsrc@1.1.6/dist/'

  const appendScript = (id, src, attributes = {}, onload) => {
    if (document.getElementById(id)) return
    const script = document.createElement('script')
    script.id = id
    script.src = src
    script.async = true
    Object.entries(attributes).forEach(([name, value]) => script.setAttribute(name, value))
    if (onload) script.addEventListener('load', onload, { once: true })
    document.body.appendChild(script)
  }

  const loadDecorativeScripts = () => {
    appendScript(
      'nova-power-mode',
      `${CDN_ROOT}activate-power-mode.min.js`,
      {},
      () => {
        if (!window.POWERMODE || document.body.dataset.novaPowerModeReady) return
        window.POWERMODE.colorful = true
        window.POWERMODE.shake = false
        window.POWERMODE.mobile = false
        document.body.addEventListener('input', window.POWERMODE)
        document.body.dataset.novaPowerModeReady = 'true'
      }
    )
  }

  if ('requestIdleCallback' in window) {
    window.requestIdleCallback(loadDecorativeScripts, { timeout: 2200 })
  } else {
    window.setTimeout(loadDecorativeScripts, 1500)
  }
})()

