    { r: 255, g: 232, b: 234, a: 0.88 },
    { r: 238, g: 150, b: 166, a: 0.84 },
    { r: 218, g: 82, b: 112, a: 0.78 },
    { r: 168, g: 48, b: 72, a: 0.72 },
    { r: 195, g: 184, b: 205, a: 0.68 },
