    { r: 151, g: 103, b: 122, a: 0.48 },
    { r: 169, g: 135, b: 158, a: 0.44 },
    { r: 139, g: 128, b: 171, a: 0.42 },
    { r: 190, g: 171, b: 183, a: 0.38 },
    { r: 236, g: 226, b: 221, a: 0.34 },
