    { r: 145, g: 112, b: 129 },
    { r: 151, g: 137, b: 173 },
    { r: 184, g: 153, b: 164 },
  ];
  const DARK_GLOW_COLORS = [
    { r: 242, g: 232, b: 233 },
    { r: 224, g: 193, b: 206 },
    { r: 211, g: 214, b: 229 },
    { r: 196, g: 176, b: 205 },
  ];
  const LIGHT_GLOW_COLORS = [
    { r: 174, g: 157, b: 164 },
    { r: 190, g: 163, b: 171 },
    { r: 162, g: 153, b: 161 },
    { r: 199, g: 181, b: 184 },
