          const sameCluster = a.clusterId >= 0 && a.clusterId === b.clusterId;
          const seedGap = Math.abs(a.linkSeed - b.linkSeed);
          if (!nearMouse) {
            if (!sameCluster && seedGap > 0.24) continue;
            if (sameCluster && seedGap > 0.58) continue;
