  function loop(time) {
    if (document.hidden) {
      rafId = 0;
      lastFrameTime = 0;
      window.__novaRoseGalaxy.rafId = 0;
      return;
    }
    if (!lastFrameTime || time - lastFrameTime >= FRAME_INTERVAL) {
      lastFrameTime = time - ((time - lastFrameTime) % FRAME_INTERVAL);
      for (const scene of scenes) {
        if (scene.visible) scene.draw(time, true);
      }
    }
    rafId = window.requestAnimationFrame(loop);
    window.__novaRoseGalaxy.rafId = rafId;
  }

  function resizeAll() {
    if (!scenes.length) return;
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      for (const scene of scenes) scene.resize();
    }, 120);
  }

  function restart() {
    if (reducedMotionQuery.matches) {
      destroy();
      return;
    }
    window.cancelAnimationFrame(rafId);
    rafId = 0;
    lastFrameTime = 0;
    window.__novaRoseGalaxy.rafId = 0;
    if (!scenes.length) return;
    for (const scene of scenes) scene.resize();
    rafId = window.requestAnimationFrame(loop);
    window.__novaRoseGalaxy.rafId = rafId;
  }

  function handleVisibility() {
    if (!reducedMotionQuery.matches && !document.hidden && !rafId && scenes.length) {
      lastFrameTime = 0;
      rafId = window.requestAnimationFrame(loop);
      window.__novaRoseGalaxy.rafId = rafId;
    }
  }

  function destroy() {
    window.cancelAnimationFrame(rafId);
    window.clearTimeout(resizeTimer);
    rafId = 0;
    resizeTimer = 0;
    lastFrameTime = 0;
    scenes.splice(0).forEach((scene) => scene.destroy());
    window.__novaRoseGalaxy.running = false;
    window.__novaRoseGalaxy.rafId = 0;
  }

  function init() {
    if (reducedMotionQuery.matches) {
      destroy();
      return;
    }
    const hero = document.getElementById("hero");
    if (
      scenes.length &&
      scenes.some((scene) => scene.host === hero) &&
      scenes.every((scene) => scene.host.isConnected)
    ) {
      return;
    }
    destroy();
    setupScenes();
    if (!scenes.length) return;
    window.__novaRoseGalaxy.running = true;
    lastFrameTime = 0;
    rafId = window.requestAnimationFrame(loop);
    window.__novaRoseGalaxy.rafId = rafId;
  }

  const syncTheme = () => {
    if (!window.document?.documentElement) return;
    destroy();
    init();
  };

  const themeObserver = new MutationObserver((records) => {
    if (records.some((record) => record.attributeName === "data-theme")) syncTheme();
  });
  themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });

  window.__novaRoseGalaxy = { running: false, rafId: 0, init, destroy, syncTheme };
  window.addEventListener("resize", resizeAll, { passive: true });
  document.addEventListener("visibilitychange", handleVisibility);
  document.addEventListener("pjax:send", destroy);
  document.addEventListener("pjax:complete", init);

  if (reducedMotionQuery.addEventListener) {
    reducedMotionQuery.addEventListener("change", () => {
      if (reducedMotionQuery.matches) destroy();
      else init();
    });
  } else if (reducedMotionQuery.addListener) {
    reducedMotionQuery.addListener(() => {
      if (reducedMotionQuery.matches) destroy();
      else init();
    });
  }

  init();
})();

(() => {
  'use strict'

  if (window.__novaGalleryBootstrap) {
    window.__novaGalleryBootstrap.init()
    return
  }

  const ROOT_SELECTOR = '[data-gallery-root]'
  const SLOT_PREFIX = 'nova-gallery-item--slot-'
  let controller = null

  function decoratePage(root) {
    document.body.classList.add('nova-gallery-route')

    const header = document.querySelector('#page-header')
    if (header) header.classList.add('nova-gallery-nav-header')

    const comment = document.querySelector('#post-comment')
    if (comment) {
      comment.classList.add('nova-gallery-comments')
      const headline = comment.querySelector('.comment-headline')
      if (headline && !headline.querySelector('strong')) {
        headline.innerHTML = 'NIGHT MESSAGES留言'
      }
    }

    return root
  }

  function initGallery() {
    const root = document.querySelector(ROOT_SELECTOR)
    if (!root) return
    decoratePage(root)
    if (root.dataset.galleryReady === 'true') return
    controller?.destroy()
    root.dataset.galleryReady = 'true'

    const grids = [...root.querySelectorAll('[data-gallery-grid]')]
    const photos = [...root.querySelectorAll('[data-gallery-photo]')]
    const items = [...root.querySelectorAll('[data-gallery-item]')]
    const buttons = [...root.querySelectorAll('[data-gallery-filter]')]
    const sort = root.querySelector('[data-gallery-sort]')
    const empty = root.querySelector('[data-gallery-empty]')
    const categories = [...new Set(items.map(item => item.dataset.category).filter(Boolean))]
    let activeFilter = 'all'
    let resizeTimer = 0

    const total = root.querySelector('[data-gallery-total]')
    const categoryTotal = root.querySelector('[data-gallery-category-total]')
    const updated = root.querySelector('[data-gallery-updated]')
    if (total) total.textContent = String(items.length)
    if (categoryTotal) categoryTotal.textContent = String(categories.length)

    const latestDate = photos
      .map(photo => photo.dataset.updated)
      .filter(Boolean)
      .sort()
      .at(-1)

    if (updated && latestDate) {
      updated.dateTime = latestDate
      updated.textContent = latestDate.replaceAll('-', '.')
    }

    function sortItems(mode) {
      const ordered = [...items].sort((a, b) => {
        if (mode === 'default') return Number(a.dataset.originalIndex) - Number(b.dataset.originalIndex)
        const aDate = a.querySelector('[data-gallery-photo]')?.dataset.updated || ''
        const bDate = b.querySelector('[data-gallery-photo]')?.dataset.updated || ''
        const dateOrder = mode === 'newest' ? bDate.localeCompare(aDate) : aDate.localeCompare(bDate)
        return dateOrder || Number(a.dataset.originalIndex) - Number(b.dataset.originalIndex)
      })
      ordered.forEach(item => {
        const targetName = item.hasAttribute('data-gallery-featured') ? 'featured' : 'archive'
        root.querySelector(`[data-gallery-grid="${targetName}"]`)?.appendChild(item)
      })
    }

    function setItemRatio(item) {
      const photo = item.querySelector('[data-gallery-photo]')
      const width = photo?.naturalWidth || Number(photo?.getAttribute('width')) || 1
      const height = photo?.naturalHeight || Number(photo?.getAttribute('height')) || 1
      const ratio = width / height
      item.dataset.galleryRatio = ratio >= 1.35 ? 'wide' : ratio  {
        ;[...item.classList]
          .filter(className => className.startsWith(SLOT_PREFIX))
          .forEach(className => item.classList.remove(className))
        item.classList.remove('nova-gallery-item--last-group')
      })
      const visibleItems = items.filter(item => !item.hidden)
      grids.forEach(itemGrid => {
        const groupItems = [...itemGrid.querySelectorAll('[data-gallery-item]:not([hidden])')]
        groupItems.forEach((item, index) => {
          setItemRatio(item)
          item.dataset.galleryCount = String(groupItems.length)
          item.classList.add(`${SLOT_PREFIX}${index % 6 + 1}`)
        })
        itemGrid.dataset.visibleRemainder = String(groupItems.length % 6)
        itemGrid.closest('.nova-gallery-collection')?.toggleAttribute('hidden', groupItems.length === 0)
      })
      if (empty) empty.hidden = visibleItems.length !== 0
      requestAnimationFrame(() => visibleItems.forEach(measureItem))
    }

    function applyFilter(filter) {
      activeFilter = filter
      buttons.forEach(button => {
        const active = button.dataset.galleryFilter === filter
        button.classList.toggle('is-active', active)
        button.setAttribute('aria-pressed', String(active))
      })
      items.forEach(item => {
        item.hidden = filter !== 'all' && item.dataset.category !== filter
      })
      arrangeVisibleItems()
    }

    buttons.forEach(button => {
      button.addEventListener('click', () => applyFilter(button.dataset.galleryFilter))
    })

    if (sort) {
      sort.addEventListener('change', () => {
        sortItems(sort.value)
        applyFilter(activeFilter)
      })
    }

    photos.forEach(photo => {
      const rearrange = () => arrangeVisibleItems()
      if (!photo.complete) photo.addEventListener('load', rearrange, { once: true })
      photo.addEventListener('error', () => {
        photo.closest('[data-gallery-item]')?.classList.add('is-image-error')
        photo.setAttribute('aria-label', `${photo.alt || '照片'}加载失败`)
      }, { once: true })
    })

    const handleResize = () => {
      window.clearTimeout(resizeTimer)
      resizeTimer = window.setTimeout(arrangeVisibleItems, 140)
    }
    window.addEventListener('resize', handleResize, { passive: true })

    sortItems('default')
    applyFilter('all')
    controller = {
      destroy() {
        window.clearTimeout(resizeTimer)
        window.removeEventListener('resize', handleResize)
      }
    }
  }

  function leaveGallery() {
    controller?.destroy()
    controller = null
    document.body.classList.remove('nova-gallery-route')
    document.querySelector('#page-header')?.classList.remove('nova-gallery-nav-header')
  }

  window.__novaGalleryBootstrap = { init: initGallery, destroy: leaveGallery }
  initGallery()
  document.addEventListener('DOMContentLoaded', initGallery, { once: true })
  document.addEventListener('pjax:send', leaveGallery)
  document.addEventListener('pjax:complete', initGallery)
})()

(() => {
  'use strict'
  if (window.__fliexSnow) return
  let running = false, activeStop = null
  const storageKey = 'fliex-coast-snow-v1'
  const mount = (root, options = {}) => {
    activeStop?.()
    const listeners = []
    const on = (target, name, fn) => { target.addEventListener(name, fn); listeners.push(() => target.removeEventListener(name, fn)) }
    const canvas = options.canvas || root.querySelector('[data-coast-snow]')
    const context = canvas?.getContext('2d')
    const toggle = options.toggle || root.querySelector('[data-coast-snow-toggle]')
    if (!canvas || !context || !toggle) return () => {}
    const media = matchMedia('(prefers-reduced-motion: reduce)')
    // Keep the supplied photographic branches; no generated zigzag geometry.
    const lightningLayer = document.createElement('div')
    lightningLayer.className = 'coast-lightning'
    lightningLayer.setAttribute('aria-hidden', 'true')
    const lightningImage = document.createElement('img')
    lightningImage.src = '/img/lightning-reference.png'
    lightningImage.alt = ''
    lightningLayer.appendChild(lightningImage)
    ;(options.lightningRoot || root).appendChild(lightningLayer)
    let saved = null
    try { saved = localStorage.getItem(storageKey) } catch (_) {}
    let enabled = saved === null ? !media.matches : saved === 'true'
    let raf = 0, lastFrame = 0, width = 0, height = 0, pixelRatio = 0, particles = [], lightning = null, nextLightning = 0, disposed = false, animating = false
    const scheduleLightning = time => time + (10 + Math.random() * 20) * 1000
    const stop = () => {
      cancelAnimationFrame(raf); raf = 0; running = false; animating = false; lastFrame = 0
      lightning = null; nextLightning = 0
      lightningLayer.style.opacity = '0'
      context?.clearRect(0, 0, width, height)
    }
    const resize = () => {
      const rect = (canvas || root).getBoundingClientRect()
      const ratio = Math.min(devicePixelRatio || 1, 1.5)
      if (rect.width = lightning.duration) { lightning = null; lightningLayer.style.opacity = '0'; return }
      const pulse = age < 90 ? Math.sin(age / 90 * Math.PI) : age < 170 ? .08 : Math.exp(-(age - 170) / 110) * .72
      lightningLayer.style.opacity = String(pulse * .85)
    }
    const frame = time => {
      if (disposed || !animating) return
      if (!root.isConnected) { stop(); return }
      // PJAX styles can arrive after mounting. Never stretch a stale bitmap.
      if (!resize()) { stop(); return }
      const elapsed = lastFrame ? time - lastFrame : 34
      if (elapsed >= 32) {
        const delta = Math.min(elapsed, 80) / 1000
        lastFrame = time
        context.clearRect(0, 0, width, height)
        for (const p of particles) {
          p.x += (-p.speed * .22 + Math.sin(time / 1800 + p.phase) * p.sway) * delta; p.y += p.speed * delta
          context.fillStyle = "rgba(219,235,244," + p.alpha + ")"
          if (p.x < -4) p.x = width + 4
          if (p.x > width + 4) p.x = -4
          if (p.y > height + 4) p.y = -4
          context.beginPath(); context.ellipse(p.x, p.y, p.r, p.r * .9, 0, 0, Math.PI * 2); context.fill()
        }
        drawLightning(time)
      }
      raf = requestAnimationFrame(frame)
    }
    const sync = () => {
      if (disposed) return
      const active = enabled && !media.matches
      toggle.setAttribute('aria-checked', String(active))
      toggle.textContent = active ? 'SNOW · ON' : 'SNOW · OFF'
      toggle.title = media.matches ? '系统已开启减少动态效果' : active ? '关闭风雪动画' : '开启风雪动画'
      if (!active || document.hidden || !root.isConnected || !context) { stop(); return }
      if (!animating && resize()) { nextLightning = scheduleLightning(performance.now()); running = true; animating = true; raf = requestAnimationFrame(frame) }
    }
    on(toggle, 'click', () => {
      enabled = !enabled
      try { localStorage.setItem(storageKey, String(enabled)) } catch (_) {}
      sync()
    })
    on(media, 'change', sync)
    on(document, 'visibilitychange', sync)
    on(window, 'resize', () => { resize(); sync() })
    const observer = typeof ResizeObserver === 'function' ? new ResizeObserver(() => { if (!disposed) { resize(); sync() } }) : null
    observer?.observe(canvas)
    resize(); sync()
    const cleanup = () => {
      if (disposed) return
      disposed = true; stop(); observer?.disconnect(); listeners.forEach(off => off()); lightningLayer.remove()
      if (activeStop === cleanup) activeStop = null
    }
    activeStop = cleanup
    return cleanup
  }
  window.__fliexSnow = { mount, get running() { return running } }
})()

(() => {
  'use strict'
