        if (list.audios.length) list.switch(Math.min(index, list.audios.length - 1))
        else { audio.pause(); audio.removeAttribute('src'); audio.load(); wantsPlay = false; failed = true; message = '当前没有可播放的歌曲'; emit() }
      }
