  const read = key => { try { return JSON.parse(localStorage.getItem(key)) || [] } catch (_) { return [] } }
  const init = () => {
    const root = document.querySelector('.nova-music-page')
    if (!root || mounted === root || !window.__fliexMusic) return
    cleanup(); mounted = root
