        lyrics.innerHTML = lines.length ? lines.map(line => '' + escape(line.text) + '').join('') : untimed.length ? '歌词原文 · 暂无时间轴' + untimed.map(line => '' + escape(line) + '').join('') : '暂无歌词添加本地 LRC 后，歌词将在这里同步。'
        render()
      } catch (error) { if (destroyed || lyricSong !== key) return; console.error('[Fliex Music] 歌词加载失败', error); lyrics.innerHTML = '歌词加载失败' }
    }
