})()

(() => {
  'use strict'

  const INSTANCE_KEY = '__princeEasterEgg'
  if (window[INSTANCE_KEY]) {
    window[INSTANCE_KEY].init()
    return
  }

  // Five independent entries are selected randomly without immediate repetition.
  const princeQuotes = [
    {
      zh: "完美并非无以复加，而是无处可减。",
      en: "Perfection is achieved, not when there is nothing more to add, but when there is nothing left to take away.",
      source: "— Antoine de Saint-Exupéry"
    },
    {
      zh: "我不能创造的东西，我就无法真正理解。",
      en: "What I cannot create, I do not understand.",
      source: "— Richard Feynman（理查德·费曼）"
    },
    {
      zh: "万物皆不急就，却无所不成。",
      en: "Nature does not hurry, yet everything is accomplished.",
      source: "— Lao Tzu（老子）"
    },
    {
      zh: "“简单是可靠性的先决条件。”",
      en: "Simplicity is prerequisite for reliability.",
      source: "— Edsger W. Dijkstra（艾兹格·迪杰斯特拉）"
    },
    {
      zh: "不要再去争论一个好人应该是什么样，去成为他。",
      en: "Waste no more time arguing what a good man should be. Be one.",
      source: "— Marcus Aurelius（马可·奥勒留）"
    }
  ]

  const RETURN_DELAY = 2000
  const QUOTE_MIN_DURATION = 3000
  const QUOTE_AUTO_CLOSE_DELAY = 5000
  const QUOTE_LEAVE_CLOSE_DELAY = 2000
  const QUOTE_CLOSE_ANIMATION = 280

  const state = {
    name: 'hidden',
    lastQuoteIndex: -1,
    frame: 0,
    prepareTimer: 0,
    returnTimer: 0,
    returnAnimationTimer: 0,
    quoteUnlockTimer: 0,
    quoteAutoCloseTimer: 0,
    quoteLeaveTimer: 0,
    quoteCloseTimer: 0,
    quoteOpenedAt: 0,
    quoteUnlocked: false,
    quoteHovered: false,
    observer: null,
    globalEventsBound: false,
    domCreated: false
  }

  const scriptUrl = document.currentScript && document.currentScript.src
    ? new URL(document.currentScript.src, window.location.href)
    : new URL(window.location.href)
  const rootPath = scriptUrl.pathname.includes('/rose-galaxy/')
    ? scriptUrl.pathname.split('/rose-galaxy/')[0] + '/'
    : '/'
  const assetUrl = filename => new URL(`${rootPath}img/${filename}`, window.location.origin).href

  function createDom() {
    let root = document.querySelector('[data-prince-egg]')
    if (!root) {
      root = document.createElement('div')
      root.className = 'prince-egg is-hidden'
      root.dataset.princeEgg = ''
      root.setAttribute('aria-hidden', 'true')
      root.innerHTML = `





        `
      document.body.appendChild(root)
    }

    let popover = document.querySelector('[data-prince-quote-popover]')
    if (!popover) {
      popover = document.createElement('div')
      popover.id = 'prince-quote-popover'
      popover.className = 'prince-quote-popover'
      popover.dataset.princeQuotePopover = ''
      popover.setAttribute('role', 'dialog')
      popover.setAttribute('aria-live', 'polite')
      popover.setAttribute('aria-hidden', 'true')
      popover.innerHTML = `









        `
      document.body.appendChild(popover)
    }

    root.querySelectorAll('img').forEach(image => {
      image.loading = 'lazy'
      image.decoding = 'async'
    })
    state.domCreated = true
    bindElementEvents(root, popover)
    return { root, popover }
  }

  function setState(root, next) {
    if (!root) return
    if (state.name === next && root.classList.contains(`is-${next}`)) return
    state.name = next
    root.classList.remove(
      'is-hidden', 'is-peeking', 'is-preparing', 'is-jumping',
      'is-standing', 'is-returning', 'is-quote-open'
    )
    root.classList.add(`is-${next}`)
    root.dataset.state = next
    root.setAttribute('aria-hidden', String(next === 'hidden'))
  }

  function cancelReturnToPeek() {
    window.clearTimeout(state.returnTimer)
    state.returnTimer = 0
  }

  function beginJump(root) {
    if (state.name !== 'peeking') return
    cancelReturnToPeek()
    window.clearTimeout(state.prepareTimer)
    setState(root, 'preparing')

    state.prepareTimer = window.setTimeout(() => {
      if (state.name !== 'preparing') return
      const character = root.querySelector('.prince-egg__character')
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        setState(root, 'standing')
        if (!character.matches(':hover')) scheduleReturnToPeek(root)
        return
      }

      const finishJump = event => {
        if (event.animationName !== 'prince-jump' || state.name !== 'jumping') return
        character.removeEventListener('animationend', finishJump)
        setState(root, 'standing')
        if (!character.matches(':hover')) scheduleReturnToPeek(root)
      }
      character.addEventListener('animationend', finishJump)
      setState(root, 'jumping')
    }, 140)
  }

  function returnToPeek(root) {
    cancelReturnToPeek()
    if (state.name !== 'standing') return
    setState(root, 'returning')
    window.clearTimeout(state.returnAnimationTimer)
    state.returnAnimationTimer = window.setTimeout(() => {
      if (state.name === 'returning') setState(root, 'peeking')
      state.returnAnimationTimer = 0
    }, 650)
  }

  function scheduleReturnToPeek(root) {
    cancelReturnToPeek()
    if (state.name !== 'standing') return
    const character = root.querySelector('.prince-egg__character')
    if (character && character.matches(':hover')) return
    state.returnTimer = window.setTimeout(() => returnToPeek(root), RETURN_DELAY)
  }

  function getRandomQuote() {
    let nextIndex
    do {
      nextIndex = Math.floor(Math.random() * princeQuotes.length)
    } while (nextIndex === state.lastQuoteIndex && princeQuotes.length > 1)
    state.lastQuoteIndex = nextIndex
    return princeQuotes[nextIndex]
  }

  function clearQuoteTimers() {
    window.clearTimeout(state.quoteUnlockTimer)
    window.clearTimeout(state.quoteAutoCloseTimer)
    window.clearTimeout(state.quoteLeaveTimer)
    window.clearTimeout(state.quoteCloseTimer)
    state.quoteUnlockTimer = 0
    state.quoteAutoCloseTimer = 0
    state.quoteLeaveTimer = 0
    state.quoteCloseTimer = 0
  }

  function scheduleQuoteClose(root, popover, delay) {
    window.clearTimeout(state.quoteAutoCloseTimer)
    state.quoteAutoCloseTimer = window.setTimeout(
      () => closeQuotePopover(root, popover),
      delay
    )
  }

  function scheduleQuoteLeaveClose(root, popover) {
    window.clearTimeout(state.quoteLeaveTimer)
    state.quoteLeaveTimer = window.setTimeout(
      () => closeQuotePopover(root, popover),
      QUOTE_LEAVE_CLOSE_DELAY
    )
  }

  function positionQuotePopover(root, popover) {
    if (!root || !popover || !popover.classList.contains('is-visible')) return
    const character = root.querySelector('.prince-egg__character')
    const rect = character.getBoundingClientRect()
    popover.classList.add('is-measuring')
    const popoverRect = popover.getBoundingClientRect()
    const horizontalGap = 8
    const verticalOffset = 22
    const edge = 12
    const viewportWidth = document.documentElement.clientWidth
    const viewportHeight = window.innerHeight
    const fitsRight = rect.right + horizontalGap + popoverRect.width  {
      if (state.name !== 'quote-open') return
      state.quoteUnlocked = true
      state.quoteUnlockTimer = 0
      if (!state.quoteHovered) {
        const elapsed = Date.now() - state.quoteOpenedAt
        scheduleQuoteClose(root, popover, Math.max(0, QUOTE_AUTO_CLOSE_DELAY - elapsed))
      }
    }, QUOTE_MIN_DURATION)

    scheduleQuoteClose(root, popover, QUOTE_AUTO_CLOSE_DELAY)
  }

  function requestCloseQuotePopover(root, popover) {
    if (state.name !== 'quote-open' || !state.quoteUnlocked) return
    closeQuotePopover(root, popover)
  }

  function closeQuotePopover(root, popover) {
    if (state.name !== 'quote-open') return
    clearQuoteTimers()
    state.quoteUnlocked = false
    state.quoteHovered = false
    popover.classList.add('is-closing')
    popover.classList.remove('is-visible')

    state.quoteCloseTimer = window.setTimeout(() => {
      popover.classList.remove('is-closing', 'is-left', 'is-right')
      popover.setAttribute('aria-hidden', 'true')
      popover.style.removeProperty('left')
      popover.style.removeProperty('top')
      setState(root, 'standing')
      const character = root.querySelector('.prince-egg__character')
      if (!character.matches(':hover')) scheduleReturnToPeek(root)
      state.quoteCloseTimer = 0
    }, QUOTE_CLOSE_ANIMATION)
  }

  function forceCloseQuotePopover(root, popover) {
    clearQuoteTimers()
    state.quoteUnlocked = false
    state.quoteHovered = false
    if (popover) {
      popover.classList.remove('is-visible', 'is-closing', 'is-measuring', 'is-left', 'is-right')
      popover.setAttribute('aria-hidden', 'true')
      popover.style.removeProperty('left')
      popover.style.removeProperty('top')
    }
    if (root && state.name === 'quote-open') setState(root, 'standing')
  }

  function bindElementEvents(root, popover) {
    if (root.dataset.eventsBound !== 'true') {
      root.dataset.eventsBound = 'true'
      const character = root.querySelector('.prince-egg__character')
      character.addEventListener('mouseenter', () => {
        cancelReturnToPeek()
        if (state.name === 'peeking') beginJump(root)
      })
      character.addEventListener('mouseleave', () => {
        if (state.name === 'standing') scheduleReturnToPeek(root)
      })
      character.addEventListener('dblclick', event => {
        event.preventDefault()
        event.stopPropagation()
        if (state.name !== 'standing' && state.name !== 'quote-open') return
        cancelReturnToPeek()
        if (state.name === 'quote-open' && !state.quoteUnlocked) return
        openQuotePopover(root, popover)
      })
    }

    if (popover.dataset.eventsBound !== 'true') {
      popover.dataset.eventsBound = 'true'
      popover.addEventListener('click', event => {
        event.preventDefault()
        event.stopPropagation()
        requestCloseQuotePopover(root, popover)
      })
      popover.addEventListener('mouseenter', () => {
        state.quoteHovered = true
        window.clearTimeout(state.quoteAutoCloseTimer)
        window.clearTimeout(state.quoteLeaveTimer)
        state.quoteAutoCloseTimer = 0
        state.quoteLeaveTimer = 0
      })
      popover.addEventListener('mouseleave', () => {
        state.quoteHovered = false
        if (state.name === 'quote-open' && state.quoteUnlocked) {
          scheduleQuoteLeaveClose(root, popover)
        }
      })
    }
  }

  function isHomePage() {
    const normalizedRoot = rootPath.replace(/\/+$/, '') || '/'
    const normalizedPath = window.location.pathname.replace(/\/index\.html$/, '').replace(/\/+$/, '') || '/'
    return normalizedPath === normalizedRoot && document.body.classList.contains('nova-home-active')
  }

  function isVisible(element) {
    if (!element) return false
    const style = window.getComputedStyle(element)
    const rect = element.getBoundingClientRect()
    return style.display !== 'none' && style.visibility !== 'hidden' &&
      Number(style.opacity) !== 0 && rect.width > 0 && rect.height > 0
  }

  function hasBlockingModal() {
    const selectors = [
      '#search-mask',
      '#local-search .search-dialog',
      '.medium-zoom-overlay',
      '.fancybox__container',
      '.pswp',
      '[aria-modal="true"]:not([data-prince-quote-popover])'
    ]
    return selectors.some(selector =>
      Array.from(document.querySelectorAll(selector)).some(isVisible)
    )
  }

  function updateVisibility() {
    window.cancelAnimationFrame(state.frame)
    state.frame = window.requestAnimationFrame(() => {
      const routeEligible = isHomePage() &&
        window.innerWidth >= 768 &&
        window.scrollY > window.innerHeight * .8

      if (!routeEligible) {
        const root = document.querySelector('[data-prince-egg]')
        const popover = document.querySelector('[data-prince-quote-popover]')
        if (root) {
          cancelReturnToPeek()
          forceCloseQuotePopover(root, popover)
          setState(root, 'hidden')
        }
        return
      }

      const { root, popover } = createDom()
      if (hasBlockingModal()) {
        cancelReturnToPeek()
        forceCloseQuotePopover(root, popover)
        setState(root, 'hidden')
        return
      }
      if (state.name === 'hidden') setState(root, 'peeking')
      if (state.name === 'quote-open') positionQuotePopover(root, popover)
    })
  }

  function bindGlobalEvents() {
    if (state.globalEventsBound) return
    state.globalEventsBound = true
    window.addEventListener('scroll', updateVisibility, { passive: true })
    window.addEventListener('resize', () => {
      updateVisibility()
      const root = document.querySelector('[data-prince-egg]')
      const popover = document.querySelector('[data-prince-quote-popover]')
      if (state.name === 'quote-open') positionQuotePopover(root, popover)
    }, { passive: true })
    document.addEventListener('keydown', event => {
      if (event.key !== 'Escape') return
      const root = document.querySelector('[data-prince-egg]')
      const popover = document.querySelector('[data-prince-quote-popover]')
      requestCloseQuotePopover(root, popover)
    })
    document.addEventListener('pjax:complete', init)
  }

  function observeModals() {
    state.observer?.disconnect()
    state.observer = new MutationObserver(updateVisibility)
    const modalRoots = [
      document.getElementById('search-mask'),
      document.getElementById('local-search'),
      document.querySelector('.medium-zoom-overlay'),
      document.querySelector('.fancybox__container'),
      document.querySelector('.pswp')
    ].filter(Boolean)
    modalRoots.forEach(element => state.observer.observe(element, {
      attributes: true,
      attributeFilter: ['class', 'hidden', 'style']
    }))
    if (document.body) {
      state.observer.observe(document.body, { childList: true })
    }
  }

  function init() {
    if (!document.body) return
    bindGlobalEvents()
    observeModals()
    updateVisibility()
  }

  window[INSTANCE_KEY] = { init }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init, { once: true })
  } else {
    init()
  }
})()

(() => {
  'use strict'
  if (window.__novaHomeBootstrap) { window.__novaHomeBootstrap.init(); return }
  let cleanup = () => {}
  const destroy = () => { cleanup(); cleanup = () => {} }
  const init = () => {
    const root = document.querySelector('[data-nova-home]')
    if (!root || root.dataset.ready) return
    destroy()
    root.dataset.ready = 'true'
    const listeners = []
    const on = (target, name, fn) => {
      target.addEventListener(name, fn)
      listeners.push(() => target.removeEventListener(name, fn))
    }
    const stopSnow = window.__fliexSnow.mount(root)
    on(root.querySelector('[data-coast-search]'), 'click', () => window.__fliexOpenSearch?.())
    on(root.querySelector('[data-coast-theme]'), 'click', () => document.getElementById('darkmode')?.click())
    const renderMusic = () => {
      const state = window.__fliexMusic?.snapshot()
      if (!state) return
      root.querySelectorAll('[data-music-title]').forEach(el => { el.textContent = state.title })
      root.querySelectorAll('[data-music-artist]').forEach(el => { el.textContent = state.artist })
      root.querySelectorAll('[data-music-summary]').forEach(el => { el.textContent = state.playing ? state.artist + ' — ' + state.title : state.ready ? 'Music / Ready' : 'Music' })
      root.querySelectorAll('[data-music-toggle]').forEach(el => {
        el.disabled = !state.ready
        el.title = state.ready ? '' : '等待添加歌曲'
        el.setAttribute('aria-label', state.ready ? (state.playing ? '暂停音乐' : '播放音乐') : '暂无可播放音乐')
        el.innerHTML = ''
      })
      const progress = state.duration ? Math.min(100, state.currentTime / state.duration * 100) : 0
      root.querySelector('[data-music-progress]').style.width = progress + '%'
      root.querySelector('.coast-progress').setAttribute('aria-valuenow', String(Math.round(progress)))
      root.querySelector('[data-music-retry]').hidden = !state.failed
    }
    on(document, 'fliex:music', renderMusic)
    root.querySelectorAll('[data-music-toggle]').forEach(el => on(el, 'click', () => window.__fliexMusic?.toggle()))
    on(root.querySelector('[data-music-retry]'), 'click', () => window.__fliexMusic?.retry())
    cleanup = () => { stopSnow(); listeners.splice(0).forEach(off => off()); delete root.dataset.ready }
    renderMusic()
    window.__fliexMusic?.load()
  }
  window.__novaHomeBootstrap = { init, destroy, get running() { return window.__fliexSnow.running } }
  document.addEventListener('pjax:send', destroy)
  document.addEventListener('pjax:complete', init)
  document.addEventListener('pjax:error', init)
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true })
  else init()
})()

(() => {
  'use strict'

  if (window.__novaUxReady) return
  window.__novaUxReady = true

  const INITIAL_MIN_DURATION = 150
  const INITIAL_MAX_DURATION = 2000
  const EXIT_DURATION = 180
  const ROUTE_CLASSES = [
    'nova-home-active',
    'nova-music-route',
    'nova-archive-route',
    'nova-category-route',
    'nova-tag-route',
    'nova-tags-route',
    'nova-template-route',
    'nova-shuoshuo-route',
    'nova-about-route',
    'nova-gallery-route'
  ]
  let initialFinishTimer = 0
  let initialFallbackTimer = 0
  let removeTimer = 0
  let initialFinishScheduled = false
  let statsTimer = 0
  let navigationObserver = null
  let searchObserver = null

  function getLoader() {
    const loaders = Array.from(document.querySelectorAll('[data-nova-loading]'))
    let loader = loaders.shift()
    loaders.forEach(item => item.remove())
    if (loader) return loader

    loader = document.createElement('div')
    loader.className = 'nova-page-loading'
    loader.dataset.novaLoading = ''
    loader.setAttribute('aria-hidden', 'true')
    loader.innerHTML = `


        FLIEX
        LOADING THE NIGHT...
      `
    document.body.appendChild(loader)
    return loader
  }

  function enhanceSearch() {
    const dialog = document.querySelector('#local-search .search-dialog')
    const input = dialog?.querySelector('.local-search-input input')
    const results = dialog?.querySelector('#local-search-results')
    if (!dialog || !input || !results || dialog.dataset.novaSearchReady === 'true') return
    dialog.dataset.novaSearchReady = 'true'

    searchObserver?.disconnect()
    searchObserver = null

    const state = document.createElement('div')
    state.className = 'nova-search-state'
    state.innerHTML = `
      QUICK PASSAGE
      从这里进入夜航档案
      输入关键词，或先浏览常用页面。

        归档
        分类
        光影
        音乐
      `
    results.before(state)

    const renderState = () => {
      const query = input.value.trim()
      const hasResults = Boolean(results.querySelector('.local-search-hit-item'))
      state.hidden = Boolean(query && hasResults)
      state.classList.toggle('is-empty-result', Boolean(query && !hasResults))
      if (query && !hasResults) {
        state.querySelector('.nova-search-state__eyebrow').textContent = 'NO SIGNAL'
        state.querySelector('strong').textContent = '没有找到相关记录'
        state.querySelector('p').textContent = '换一个更短的关键词，或从快速入口继续浏览。'
      } else {
        state.querySelector('.nova-search-state__eyebrow').textContent = 'QUICK PASSAGE'
        state.querySelector('strong').textContent = '从这里进入夜航档案'
        state.querySelector('p').textContent = '输入关键词，或先浏览常用页面。'
      }
    }

    input.addEventListener('input', () => window.setTimeout(renderState, 0))
    searchObserver = new MutationObserver(renderState)
    searchObserver.observe(results, { childList: true, subtree: true })
    renderState()
  }

  function cleanupSearch() {
    searchObserver?.disconnect()
    searchObserver = null
  }

  function finishInitialLoading() {
    window.clearTimeout(window.__novaLoaderDelayTimer)
    window.__novaLoaderDelayTimer = 0
    const loader = document.querySelector('[data-nova-loading]')
    if (!loader) {
      document.body.classList.remove('nova-loading-active')
      return
    }
    if (loader.dataset.novaLoadingState === 'leaving') return

    if (!loader.classList.contains('is-visible')) {
      window.clearTimeout(initialFinishTimer)
      window.clearTimeout(initialFallbackTimer)
      window.clearTimeout(removeTimer)
      loader.remove()
      document.body.classList.remove('nova-loading-active')
      return
    }

    loader.dataset.novaLoadingState = 'leaving'
    loader.setAttribute('aria-hidden', 'true')
    loader.classList.add('is-leaving')
    loader.classList.remove('is-visible')
    window.clearTimeout(initialFinishTimer)
    window.clearTimeout(initialFallbackTimer)
    window.clearTimeout(removeTimer)
    removeTimer = window.setTimeout(() => {
      loader.remove()
      document.body.classList.remove('nova-loading-active')
    }, EXIT_DURATION)
  }

  function scheduleInitialFinish() {
    if (initialFinishScheduled) return
    initialFinishScheduled = true
    window.clearTimeout(window.__novaLoaderDelayTimer)
    window.__novaLoaderDelayTimer = 0
    const loader = document.querySelector('[data-nova-loading]')
    if (!loader?.classList.contains('is-visible')) {
      finishInitialLoading()
      return
    }
    const visibleAt = Number(window.__novaLoaderVisibleAt) || Date.now()
    const elapsed = Date.now() - visibleAt
    initialFinishTimer = window.setTimeout(
      finishInitialLoading,
      Math.max(0, INITIAL_MIN_DURATION - elapsed)
    )
  }

  function initInitialLoading() {
    const loader = getLoader()
    loader.classList.remove('is-leaving')
    if (loader.classList.contains('is-visible')) {
      loader.dataset.novaLoadingState = 'visible'
      loader.setAttribute('aria-hidden', 'false')
      document.body.classList.add('nova-loading-active')
    } else {
      loader.dataset.novaLoadingState = 'pending'
      loader.setAttribute('aria-hidden', 'true')
      document.body.classList.remove('nova-loading-active')
    }

    initialFallbackTimer = window.setTimeout(finishInitialLoading, INITIAL_MAX_DURATION)
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', scheduleInitialFinish, { once: true })
    } else {
      scheduleInitialFinish()
    }
  }

  function beginNavigation() {
    cleanupSearch()
    document.body.classList.remove(...ROUTE_CLASSES)
    finishInitialLoading()
  }

  function finishNavigation() {
    finishInitialLoading()
  }

  function normalizePath(value) {
    const path = `/${value || ''}`.replace(/\/+/g, '/')
    return path.length > 1 ? path.replace(/\/$/, '') : path
  }

  function isHomePage() {
    if (
      document.body.classList.contains('nova-home-active') ||
      document.body.classList.contains('page-type-index') ||
      document.body.classList.contains('home')
    ) {
      return true
    }

    return normalizePath(location.pathname) === normalizePath(window.GLOBAL_CONFIG?.root || '/')
  }

  function syncHomeThemeToggle() {
    const button = document.getElementById('home-theme-toggle')
    if (!button) return

    const isDark = document.documentElement.getAttribute('data-theme') === 'dark'
    const label = isDark ? '切换到浅色模式' : '切换到深色模式'
    button.setAttribute('aria-label', label)
    button.setAttribute('title', label)
  }

  function createHomeThemeToggle() {
    const button = document.createElement('button')
    button.id = 'home-theme-toggle'
    button.className = 'fliex-rightside-button'
    button.type = 'button'
    button.innerHTML = `








      `

    button.addEventListener('click', event => {
      event.preventDefault()
      event.stopPropagation()
      document.getElementById('darkmode')?.click()
    })
    button.dataset.bound = 'true'
    return button
  }

  function initRightsideEnhancement() {
    const rightside = document.getElementById('rightside')
    const goUpButton = document.getElementById('go-up')
    if (!rightside || !goUpButton) return

    rightside
      .querySelectorAll('button[id], a[id]')
      .forEach(button => button.classList.add('fliex-rightside-button'))

    let homeThemeToggle = document.getElementById('home-theme-toggle')
    if (!homeThemeToggle) homeThemeToggle = createHomeThemeToggle()

    const visibleControls = goUpButton.parentElement
    if (homeThemeToggle.parentElement !== visibleControls || homeThemeToggle.nextElementSibling !== goUpButton) {
      visibleControls.insertBefore(homeThemeToggle, goUpButton)
    }

    rightside.classList.toggle('is-home-minimal', isHomePage())
    syncHomeThemeToggle()

    if (!window.__fliexRightsideThemeObserver) {
      window.__fliexRightsideThemeObserver = new MutationObserver(syncHomeThemeToggle)
      window.__fliexRightsideThemeObserver.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ['data-theme']
      })
    }
  }

  function initStatsFallback() {
    window.clearTimeout(statsTimer)
    const targets = [
      document.getElementById('busuanzi_value_site_uv'),
      document.getElementById('busuanzi_value_site_pv'),
      document.getElementById('last-push-date')
    ].filter(Boolean)
    if (!targets.length) return

    statsTimer = window.setTimeout(() => {
      targets.forEach(target => {
        if (!target.isConnected || !target.querySelector('.fa-spinner')) return
        target.textContent = '—'
        target.title = '统计服务暂时不可用'
      })
    }, 9000)
  }

  function syncNavigationSemantics() {
    const desktopMenu = document.getElementById('menus')
    const desktopMenuItems = desktopMenu?.querySelector('.menus_items')
    const mobileMenu = document.getElementById('sidebar-menus')
    const isMobile = window.matchMedia('(max-width: 768px)').matches
    const mobileMenuOpen = Boolean(isMobile && mobileMenu?.classList.contains('open'))

    if (desktopMenu) {
      desktopMenu.inert = false
      desktopMenu.removeAttribute('aria-hidden')
    }
    if (desktopMenuItems) {
      desktopMenuItems.inert = isMobile
      desktopMenuItems.setAttribute('aria-hidden', String(isMobile))
    }
    if (mobileMenu) {
      mobileMenu.inert = !mobileMenuOpen
      mobileMenu.setAttribute('aria-hidden', String(!mobileMenuOpen))
    }

    navigationObserver?.disconnect()
    if (mobileMenu) {
      navigationObserver = new MutationObserver(syncNavigationSemantics)
      navigationObserver.observe(mobileMenu, { attributes: true, attributeFilter: ['class'] })
    }
  }

  function syncRouteState() {
    document.body.classList.remove(...ROUTE_CLASSES)
    const routeMarkers = [
      ['.nova-music-page', ['nova-music-route']],
      ['.nova-about-shell', ['nova-about-route']],
      ['.coast-home[data-nova-home]', ['nova-home-active']],
      ['main.nova-archive-main', ['nova-archive-route']],
      ['main.nova-category-content', ['nova-category-route']],
      ['main.nova-tags-overview', ['nova-tag-route', 'nova-tags-route']],
      ['main.nova-tag-content:not(.nova-tags-overview)', ['nova-tag-route']],
      ['.nova-template-page', ['nova-template-route']],
      ['.nova-shuoshuo-page', ['nova-shuoshuo-route']],
      ['.nova-about-page', ['nova-about-route']],
      ['[data-gallery-root]', ['nova-gallery-route']]
    ]
    const match = routeMarkers.find(([selector]) => document.querySelector(selector))
    if (match) document.body.classList.add(...match[1])
  }

  document.addEventListener('pjax:send', beginNavigation)
  document.addEventListener('pjax:complete', finishNavigation)
  document.addEventListener('pjax:error', finishNavigation)
  document.addEventListener('DOMContentLoaded', enhanceSearch, { once: true })
  document.addEventListener('DOMContentLoaded', initRightsideEnhancement, { once: true })
  document.addEventListener('DOMContentLoaded', initStatsFallback, { once: true })
  document.addEventListener('DOMContentLoaded', syncNavigationSemantics, { once: true })
  document.addEventListener('DOMContentLoaded', syncRouteState, { once: true })
  document.addEventListener('pjax:complete', enhanceSearch)
  document.addEventListener('pjax:complete', initRightsideEnhancement)
  document.addEventListener('pjax:complete', initStatsFallback)
  document.addEventListener('pjax:complete', syncNavigationSemantics)
  document.addEventListener('pjax:complete', syncRouteState)
  window.addEventListener('pageshow', finishInitialLoading)
  window.addEventListener('pageshow', scheduleInitialFinish, { once: true })
  window.addEventListener('resize', syncNavigationSemantics)
  initInitialLoading()
  if (document.readyState !== 'loading') {
    enhanceSearch()
    initRightsideEnhancement()
    initStatsFallback()
    syncNavigationSemantics()
    syncRouteState()
  }
})()

(() => {
  'use strict'

  if (!window.__novaTagReader) {
    const reader = {
      observer: null,
      page: null,
      cards: [],
      links: [],
      activeIndex: -1,

      destroy() {
        this.observer?.disconnect()
        this.observer = null
        this.page = null
        this.cards = []
        this.links = []
        this.activeIndex = -1
      },

      setActive(index) {
        if (!this.page || index < 0 || index >= this.cards.length || index === this.activeIndex) return
        this.activeIndex = index
        const card = this.cards[index]
        const title = card.dataset.noteTitle || '当前专题'
        const href = card.dataset.noteHref || '#'
        const position = index + 1
        const percent = Math.round((position / this.cards.length) * 100)

        this.cards.forEach((item, itemIndex) => item.classList.toggle('is-current-note', itemIndex === index))
        this.links.forEach(link => {
          const targetIndex = this.cards.findIndex(item => item.id === link.dataset.noteTarget)
          link.classList.toggle('is-current', targetIndex === index)
          link.classList.toggle('is-complete', targetIndex >= 0 && targetIndex < index)
          if (targetIndex === index) link.setAttribute('aria-current', 'true')
          else link.removeAttribute('aria-current')
        })

        const titleElement = this.page.querySelector('.nova-tag-current-title')
        const countElement = this.page.querySelector('.nova-tag-current-count')
        const percentElement = this.page.querySelector('.nova-tag-current-percent')
        const progress = this.page.querySelector('.nova-tag-progress i')
        const openLink = this.page.querySelector('.nova-tag-current-open')
        if (titleElement) titleElement.textContent = title
        if (countElement) countElement.textContent = `${String(position).padStart(2, '0')} / ${String(this.cards.length).padStart(2, '0')}`
        if (percentElement) percentElement.textContent = `${percent}%`
        if (progress) progress.style.transform = `scaleX(${percent / 100})`
        if (openLink) openLink.href = href
      },

      init() {
        this.destroy()
        const page = document.querySelector('body.nova-tag-route .nova-tag-content')
        if (!page) return
        this.page = page
        this.cards = [...page.querySelectorAll('.nova-tag-post-card')]
        this.links = [...page.querySelectorAll('.nova-tag-reading-link[data-note-target]')]
        if (!this.cards.length || !('IntersectionObserver' in window)) return

        this.observer = new IntersectionObserver(entries => {
          const visible = entries
            .filter(entry => entry.isIntersecting)
            .sort((left, right) => right.intersectionRatio - left.intersectionRatio)
          if (!visible.length) return
          this.setActive(this.cards.indexOf(visible[0].target))
        }, {
          root: null,
          rootMargin: '-22% 0px -58% 0px',
          threshold: [0, 0.15, 0.35, 0.6]
        })
        this.cards.forEach(card => this.observer.observe(card))
      }
    }

    window.__novaTagReader = reader
    document.addEventListener('pjax:send', () => reader.destroy())
    document.addEventListener('pjax:complete', () => reader.init())
  }

  window.__novaTagReader.init()
})()

(() => {
  'use strict'

  if (window.__novaShuoshuoBootstrap) {
    window.__novaShuoshuoBootstrap.init()
    return
  }

  function initialiseShuoshuoPage() {
    const page = document.querySelector('.nova-shuoshuo-page')
    if (!page || page.dataset.ready === 'true') return
    page.dataset.ready = 'true'

    page.querySelectorAll('.nova-shuoshuo-like').forEach(button => {
      const count = button.querySelector('b')
      const icon = button.querySelector('span')
      const baseCount = Number(button.dataset.baseCount || 0)
      const storageKey = button.dataset.storageKey
      const applyState = liked => {
        button.classList.toggle('is-liked', liked)
        button.setAttribute('aria-pressed', String(liked))
        count.textContent = String(baseCount + (liked ? 1 : 0))
        icon.textContent = liked ? '♥' : '♡'
      }

      let liked = false
      try {
        liked = localStorage.getItem(storageKey) === 'true'
      } catch (_) {
        liked = false
      }
      applyState(liked)

      button.addEventListener('click', () => {
        liked = !liked
        try {
          localStorage.setItem(storageKey, String(liked))
        } catch (_) {
          // Visual feedback remains available when storage is blocked.
        }
        applyState(liked)
      })
    })
  }

  window.__novaShuoshuoBootstrap = { init: initialiseShuoshuoPage }
  document.addEventListener('DOMContentLoaded', initialiseShuoshuoPage, { once: true })
  document.addEventListener('pjax:complete', initialiseShuoshuoPage)
  if (document.readyState !== 'loading') initialiseShuoshuoPage()
})()
